// ==========================================
// ★ K 의 방 — B등급 직업 갈림길 · 회피
// ==========================================

// ── 곡예사 (acrobat) · 무력 ──────────────────
kJob('acrobat', 'B', [
  { at:'B', t:'옥상 — 젖은 난간',
    x:`비가 옆으로 온다. 옥상 문이 등 뒤에서 닫혔다. 안쪽에서 빗장 거는 소리가 났다.<br><br>
    계단 아래에서 구두 소리가 올라온다. 한 사람이다. 서두르지 않는다. 서두를 필요가 없는 사람의 걸음이다.<br>
    옆 건물 옥상까지 네 걸음. 사이가 비었다. 아래에서 네온이 번진다. 빨강과 초록이 빗물에 섞여 흐른다.<br><br>
    곡예사는 젖은 쇠를 딛을 때 발바닥이 아니라 발가락으로 쥔다. 난간이 젖었다.`,
    o:[
      { l:'① 난간을 딛고 건너뛴다.', k:'evade', dc:20, wake:1,
        ok:`난간 위에 섰다. 발가락으로 쇠를 쥐었다. 미끄러운 쇠도 쥐면 잡힌다.<br><br>뛰었다. 빗줄기가 얼굴을 친다. 네온이 발밑으로 지나간다. 건너편 물탱크 옆에 내렸다. 무릎으로 받고 한 바퀴 굴렀다.<br>돌아봤다. 이쪽이 섰던 난간 앞에 구두 한 켤레가 서 있다. 뛰지 않는다. 우산을 편다.<br><br>뛰기 전에 내릴 자리가 이미 발바닥에 그려져 있었다. 처음이다. 전에는 뛰고 나서 찾았다.`,
        ng:`뛰는 순간 난간이 한 번 흔들렸다. 누가 뒤에서 건드렸다.<br><br>반 뼘 모자랐다. 건너편 처마를 팔로 걸었다. 팔꿈치가 콘크리트에 갈렸다.<br>기어 올라오는 동안 아래 네온이 한 칸씩 꺼졌다. 누가 세는 것처럼.`,
        win:{ exp:22, dream:2 }, lose:{ hp:-26, mind:-12 } },
      { l:'② 무력을 실어 배수관을 타고 내려간다.', k:'steady', dc:20, cost:{ might:22 },
        ok:`배수관을 두 손으로 쥐었다. 쇠띠로 벽에 박힌 관이다. 띠와 띠 사이로 손을 옮겼다. 다리는 벽을 밀었다.<br><br>세 층을 내려왔다. 위에서 빗장 소리가 다시 났다. 옥상 문이 열렸다. 내려다보는 얼굴이 있다. 우산 그늘이라 안 보인다.<br>골목에 내렸다. 손바닥에 녹이 붉게 묻었다.<br><br>골목 끝 간판이 깜박인다. 『영업중』. 영업하는 가게는 없다.`,
        ng:`둘째 쇠띠가 벽에서 빠졌다.<br><br>관이 바깥으로 기울며 이쪽을 허공에 내밀었다. 버텼다. 관이 다시 벽에 붙었다. 손바닥이 찢어졌다.<br>내려와 보니 관 밑동 나사가 다 풀려 있었다. 녹이 안 묻은 나사다. 오늘 푼 것이다.`,
        win:{ exp:18, dream:1 }, lose:{ hp:-24, mind:-10 } },
      { l:'③ 구두 소리가 몇 걸음에서 멈추는지 센다.', k:'sense', dc:20,
        ok:`발소리를 셌다. 열여섯에서 멈췄다. 층계참이다. 거기서 기다린다. 옥상까지는 안 온다.<br><br>안 오는 데는 이유가 있다. 옥상 바닥을 봤다. 물웅덩이 하나가 유난히 넓다. 그 밑에 점검구가 있다. 뚜껑이 열린 채 물에 잠겼다.<br>점검구로 내려갔다. 아래층 천장 속이다. 기어서 건물 반대편까지 갔다.<br><br>층계참의 구두는 아직 기다린다. 옥상 문이 열리기를.`,
        ng:`열여섯에서 멈춘 발소리가 다시 났다. 이번에는 이쪽 바로 뒤에서.<br><br>발소리는 둘이었다. 하나가 멈추고 하나가 올라왔다. 등이 밀렸다. 난간에 허리가 꺾였다.<br>버티고 돌아섰다. 아무도 없다. 옥상 문은 그대로 잠겼다. 허리가 펴지지 않는다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-24, spirit:-14 } }
    ] },

  { at:'B', t:'비상계단 — 층마다 잠긴 문',
    x:`비상계단이다. 내려가는 층마다 문이 잠겼다. 손잡이에 사슬이 감겼다. 새 사슬이다.<br><br>
    위에서 발소리가 내려온다. 한 층 위. 이쪽이 한 층 내려가면 저쪽도 한 층 내려온다.<br>
    계단 한가운데가 뚫렸다. 난간과 난간 사이로 아래가 까맣다. 맨 밑바닥에 비상등 하나가 초록으로 떠 있다.<br><br>
    계단을 세 칸씩 뛰어 내려가는 건 느리다. 난간에서 난간으로 떨어지면 빠르다.`,
    o:[
      { l:'① 난간에서 난간으로 떨어져 내려간다.', k:'evade', dc:21,
        doom:{ title:'계단통', what:'계단통 아래로 떨어졌습니다', dc:17, sec:55,
          text:`난간을 놓고 아래층 난간을 잡았다. 또 놓고, 또 잡았다. 다섯 층을 그렇게 내려갔다.<br><br>여섯째 난간이 손에 안 걸렸다. 난간이 없다. 누가 그 층만 뜯어냈다. 볼트 구멍이 하얗다.<br>몸이 계단통 한가운데로 떨어진다. 손끝이 계단 모서리에 걸렸다. 손가락 네 개다.<br><br>위에서 발소리가 멈췄다. 내려다보는 숨소리가 난다.`,
          dieText:`떨어지는 법은 안다. 받아 줄 것이 있을 때 이야기다.<br><br>비상등 초록 불빛이 한 번 가려졌다가 다시 떴다.<br>위층에서 누가 난간 볼트를 다시 조인다. 하나씩. 천천히.` },
        ok:`난간을 놓고 아래층 난간을 잡았다. 놓고, 잡고. 박자를 셌다.<br><br>여섯째 층에 난간이 없는 걸 떨어지는 중에 봤다. 볼트 구멍이 하얗다. 몸을 틀어 계단참으로 내렸다. 발목이 받았다.<br>남은 층은 걸어 내려갔다. 위의 발소리가 끊겼다. 따라 뛰어내릴 사람은 없다.<br><br>맨 아래 문은 잠기지 않았다. 잠글 필요가 없다고 생각한 문이다.`,
        win:{ exp:24, dream:3 } },
      { l:'② 사슬 감긴 문의 틈을 찾는다.', k:'sense', dc:20,
        ok:`셋째 층 문을 봤다. 사슬은 감겼는데 경첩 쪽이 헐겁다. 문짝이 한 뼘 벌어진다.<br><br>한 뼘이면 된다. 어깨를 빼고 갈비를 접어 들어갔다. 사슬이 등을 긁었다.<br>불 꺼진 복도다. 뒤에서 발소리가 계단을 계속 내려간다. 이쪽이 아직 계단에 있는 줄 안다.<br><br>복도 끝 정수기에서 물이 똑똑 떨어진다. 통을 받쳐 채웠다.`,
        ng:`문이 한 뼘 벌어졌다. 들어가다 사슬이 조였다.<br><br>사슬이 저절로 조인 게 아니다. 반대편에서 누가 사슬 끝을 쥐고 당겼다.<br>몸을 비틀어 빼냈다. 갈비 사이가 결린다. 틈 너머에서 손이 문을 다시 당겨 닫았다.`,
        win:{ exp:16, item:'맑은 물' }, lose:{ hp:-22, spirit:-12 } }
    ] },

  { at:'B', t:'잠긴 방 — 도는 날개',
    x:`막다른 방이다. 문은 하나, 밖에서 잠겼다. 열쇠 꽂는 소리가 났다. 돌리지는 않았다. 기다린다.<br><br>
    천장 구석에 환기구가 있다. 덮개 나사가 하나 빠졌다. 사람 하나 들어가기 힘든 너비다.<br>
    안쪽 깊은 데서 날개가 돈다. 웅, 웅. 돌 때마다 바람이 끊긴다.<br><br>
    곡예사는 몸을 접어 그 너비를 사람 하나만큼으로 만든다.`,
    o:[
      { l:'① 몸을 접어 덕트를 기어간다.', k:'evade', dc:20, wake:1,
        ok:`어깨를 하나씩 빼서 넣었다. 덕트가 몸에 맞게 줄었다. 아니다. 몸이 덕트에 맞게 줄었다.<br><br>팔꿈치로 끌고 무릎으로 밀었다. 날개 앞에서 멈췄다. 날개 사이가 열렸다 닫힌다. 박자가 셋이다. 셋째 박자에 몸을 밀어 넣었다. 날개가 옷자락을 물었다가 놓았다.<br>옆 건물로 이어진 덕트에서 나왔다. 몸을 폈다. 접혔던 데가 하나도 안 아프다.<br><br>접는 게 버티는 일이 아니라 쉬는 일이 됐다. 좁은 데 들어가면 몸이 먼저 숨을 고른다.`,
        ng:`날개 박자를 잘못 셌다.<br><br>날개가 신발 뒤축을 쳤다. 다리가 덕트 벽에 부딪쳤다. 소리가 쇠를 타고 건물 전체로 울렸다.<br>문 쪽에서 열쇠가 돌아가는 소리가 났다. 빠져나오기는 했다. 발목이 퉁퉁 부었다.`,
        win:{ exp:22, dream:2 }, lose:{ hp:-24, mind:-12 } },
      { l:'② 문 위 벽에 매달려 기다린다.', k:'hide', dc:21,
        ok:`문 위 벽에 손가락을 걸고 매달렸다. 문틀 위 한 뼘 턱에 발끝을 올렸다.<br><br>열쇠가 돌았다. 문이 열렸다. 들어온 사람이 방 한가운데까지 걸었다. 위를 안 봤다. 방이 비었다는 것만 봤다.<br>그 등 뒤로 내려 문을 나섰다. 밖에서 문을 잠갔다. 열쇠는 꽂혀 있었다.<br><br>안에서 문고리가 한 번 돌았다. 그다음은 조용하다. 조용한 게 더 이상하다.`,
        ng:`손가락이 먼저 지쳤다.<br><br>문이 열리는 순간 미끄러졌다. 들어온 사람 어깨 위로 떨어졌다. 둘이 같이 굴렀다.<br>먼저 일어나 뛰었다. 등 뒤의 사람은 일어나지 않았다. 앉은 채로 이쪽을 봤다. 웃는 것 같았다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-22, spirit:-14 } }
    ] },

  { at:'B', t:'바깥벽 — 젖은 간판',
    x:`건물 바깥벽에 세로 간판이 붙었다. 다섯 층 높이다. 글자마다 네온관이 휘었다. 『호텔』. '호' 자가 깜박인다.<br><br>
    아래 골목에 차 한 대가 섰다. 시동을 안 껐다. 와이퍼가 계속 움직인다. 아무도 안 내린다.<br>
    간판 뒤로 철골이 사다리처럼 짜였다. 비에 젖었다. 전선이 철골을 따라 감겼다. 피복이 군데군데 벗겨졌다.<br><br>
    쥘 데를 고르는 건 늘 하던 일이다. 오늘은 쥐면 안 되는 데도 골라야 한다.`,
    o:[
      { l:'① 무력을 실어 철골을 타고 내려간다.', k:'evade', dc:21, cost:{ might:24 },
        ok:`전선 없는 마디만 골라 쥐었다. 쥐는 손은 한 번에 하나. 다른 손은 쥐기 전까지 비워 뒀다.<br><br>'텔' 자를 지나고 '호' 자를 지났다. '호'가 깜박일 때마다 철골이 찌릿 운다. 그때는 손을 뗐다. 발로만 버텼다.<br>골목에 내렸다. 차가 없다. 아스팔트에 바퀴 자국만 젖어 있다.<br><br>위를 보니 간판 글자가 하나 줄었다. '호'가 꺼졌다. 이쪽이 지나간 뒤에.`,
        ng:`'호' 자 철골을 쥐는 순간 깜박였다.<br><br>팔이 튕겨 나갔다. 손이 저절로 펴졌다. 한 층을 떨어지다 차양에 걸렸다.<br>차양이 찢어지며 이쪽을 내려놨다. 손가락이 아직 떨린다. 골목의 차가 천천히 출발했다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-30, mind:-12 } },
      { l:'② 위로 올라 옥상으로 빠진다.', k:'sense', dc:20,
        ok:`위로 올랐다. 아래 차는 이쪽이 내려올 줄 알고 서 있다. 위는 안 본다.<br><br>간판 꼭대기에서 옥상 난간을 잡았다. 옥상에 빗물 받는 통이 있다. 넘칠 만큼 찼다. 맑다.<br>반대편 비상계단으로 내려갔다.<br><br>골목의 차가 와이퍼를 멈췄다. 기다리던 것을 놓친 줄 아직 모른다.`,
        ng:`꼭대기 철골이 녹슬어 있었다.<br><br>디딘 마디가 부러졌다. 매달렸다. 발밑에서 '호' 자가 깜박였다. 골목의 차 창문이 내려갔다.<br>기어 올라 옥상에 엎드렸다. 손바닥이 녹에 다 갈렸다.`,
        win:{ exp:16, item:'맑은 물' }, lose:{ hp:-22, spirit:-12 } },
      { l:'③ 손을 놓고 차 지붕으로 떨어진다.', k:'luck', dc:22,
        ok:`철골 중간에서 손을 놓았다. 아래 차 지붕으로. 다섯 층이 아니라 세 층이다. 세 층이면 곡예사는 산다.<br><br>차 지붕이 움푹 꺼지며 받았다. 굴러서 보닛으로, 보닛에서 길로. 와이퍼가 이쪽 등을 한 번 쓸었다.<br>운전석을 봤다. 비었다. 시동만 걸려 있다. 조수석에 사진 한 장. 이쪽 무리 사진이다. 오늘 찍은 것이다.<br><br>사진은 두고 왔다. 가져가도 또 있을 것이다.`,
        ng:`차가 움직였다. 이쪽이 떨어지는 사이 한 뼘.<br><br>지붕이 아니라 트렁크 모서리에 떨어졌다. 허리부터. 길바닥으로 굴렀다.<br>차는 천천히 떠났다. 브레이크등이 두 번 깜박였다. 인사처럼. 일어나는 데 한참 걸렸다.`,
        win:{ exp:20, dream:3 }, lose:{ hp:-34, mind:-10 } }
    ] },

  { at:'B', t:'엘리베이터 통로 — 올라오는 칸',
    x:`엘리베이터 문을 손으로 벌렸다. 칸은 없다. 통로다. 위아래로 케이블이 흔들린다.<br><br>
    아래층 표시등이 오른다. 4, 5, 6. 누가 칸을 타고 올라온다. 이 층에서 설 것이다.<br>
    맞은편 벽에 정비용 사다리가 붙었다. 세 걸음 너비를 건너야 한다. 케이블 두 줄이 그 한가운데를 지난다.<br><br>
    흔들리는 것을 잡는 법은 안다. 흔들리는 쪽으로 같이 가면 된다.`,
    o:[
      { l:'① 케이블을 잡고 사다리로 건너간다.', k:'evade', dc:21,
        doom:{ title:'케이블', what:'엘리베이터 통로로 끌려 내려갑니다', dc:17, sec:50,
          text:`케이블에 뛰어 붙었다. 기름이 묻어 미끄럽다. 손을 감았다. 몸이 사다리 쪽으로 흔들렸다.<br><br>그때 케이블이 움직였다. 아래로. 칸이 올라오는 만큼 반대쪽 줄은 내려간다. 이쪽이 그 반대쪽 줄을 잡았다.<br>몸이 통로 아래로 끌려 내려간다. 아래에서 칸 지붕이 올라온다. 그 사이가 줄어든다.<br><br>표시등 바뀌는 소리가 들린다. 7.`,
          dieText:`흔들리는 쪽으로 같이 가면 된다. 줄이 어느 쪽으로 가는지 알 때 이야기다.<br><br>칸이 이 층에 섰다. 문이 열렸다. 타는 사람은 없었다.<br>문이 닫히고 칸이 다시 내려갔다. 내려가는 내내 지붕 위에서 무언가 끌리는 소리가 났다.` },
        ok:`두 줄 중 어느 것이 내려가는지 먼저 봤다. 칸이 오르면 추 쪽 줄은 내려간다. 기름이 덜 반짝이는 쪽이 칸 줄이다.<br><br>칸 줄을 잡았다. 같이 올라갔다. 흔들림을 타고 사다리로 건너붙었다. 바로 밑으로 칸 지붕이 지나갔다. 머리카락 한 올 거리다.<br>칸이 이 층에 섰다. 문이 열렸다. 아무도 안 내린다.<br><br>문이 닫히자 칸 안에서 휘파람 소리가 났다. 이쪽이 아까 복도에서 흥얼거린 곡이다.`,
        win:{ exp:25, dream:3 } },
      { l:'② 무력을 실어 문틀 안쪽에 매달려 칸을 보낸다.', k:'steady', dc:20, cost:{ might:22 },
        ok:`통로 안쪽 문틀 턱에 손가락을 걸고 매달렸다. 발은 벽을 짚었다. 몸을 벽에 붙였다.<br><br>칸이 올라와 섰다. 바로 등 뒤다. 문이 열리고 닫혔다. 칸 안에서 누가 버튼을 누른다. 닫힘. 닫힘. 닫힘.<br>칸이 위로 갔다. 팔이 타는 것 같았다. 칸 바닥이 다 지날 때까지 안 놓았다.<br><br>칸 바닥에서 쪽지 하나가 팔랑 떨어졌다. 받았다. 『여기서 내리지 마시오』. 이쪽은 여기서 내렸다.`,
        ng:`칸이 생각보다 일찍 섰다.<br><br>칸 문턱이 이쪽 손가락을 밀었다. 손가락이 문틀과 칸 사이에 끼었다. 빼냈다. 손톱 두 개가 시퍼렇다.<br>칸이 떠난 뒤 통로 아래로 피 한 방울이 떨어졌다. 떨어지는 소리가 오래 안 났다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-24, mind:-14 } }
    ] },

  { at:'B', t:'지하 주차장 — 내려오는 셔터',
    x:`지하 주차장 출구에 셔터가 내려온다. 모터 소리가 일정하다. 바닥까지 열을 셀 만큼.<br><br>
    뒤에서 차 한 대가 전조등을 켰다. 이쪽을 비춘다. 엔진이 한 번 운다.<br>
    셔터 밑 틈이 허리 높이다. 무릎 높이가 된다. 정강이 높이가 된다.<br><br>
    굴러서 들어가면 된다. 언제 구르느냐가 전부다.`,
    o:[
      { l:'① 마지막 틈으로 굴러 빠진다.', k:'evade', dc:21, wake:1,
        ok:`달렸다. 셔터를 보지 않았다. 바닥에 그려진 노란 선을 봤다. 셋째 선에서 몸을 낮췄다.<br><br>옆으로 누워 굴렀다. 셔터 날이 코앞을 지난다. 한 바퀴 반. 등이 바깥의 젖은 바닥에 닿았다. 발끝 뒤에서 셔터가 바닥을 쳤다.<br>안에서 차가 셔터에 부딪는 소리가 났다. 브레이크 소리는 없었다.<br><br>누운 채 숨을 셌다. 구르기 시작한 자리를 몸이 기억한다. 이제부터 닫히는 문은 높이가 아니라 남은 셈으로 보인다.`,
        ng:`선을 하나 늦게 봤다.<br><br>구르는데 셔터 날이 허벅지를 눌렀다. 빼냈다. 바지가 날에 물려 찢어졌다. 살갗도.<br>셔터 틈으로 전조등이 새어 나온다. 차가 셔터 앞에 섰다. 나오지 않는다. 기다린다.`,
        win:{ exp:22, dream:2 }, lose:{ hp:-28, mind:-10 } },
      { l:'② 기둥 뒤로 비켜 차를 먼저 보낸다.', k:'hide', dc:20,
        ok:`기둥 뒤에 붙었다. 차가 달려왔다. 셔터 앞에서 설 생각이 없는 속도다.<br><br>차가 셔터를 들이받았다. 셔터가 휘어 밑이 들렸다. 차는 거기 박혔다. 운전석이 비어 있었다.<br>휘어진 틈으로 기어 나갔다.<br><br>빈 운전석 백미러에 젖은 장갑 한 짝이 걸려 있었다. 핸들을 쥐던 모양 그대로 굳었다.`,
        ng:`기둥 뒤가 전조등에 다 비쳤다.<br><br>차가 방향을 틀어 기둥 쪽으로 왔다. 옆으로 굴렀다. 사이드미러가 어깨를 쳤다.<br>차는 기둥에 박혀 섰다. 셔터는 이미 닫혔다. 다른 출구를 찾는 데 오래 걸렸다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-26, spirit:-12 } }
    ] },

  { at:'B', t:'처마 끝 — 내민 손',
    x:`건물 끝에 매달렸다. 손가락 끝으로. 아래는 일곱 층이다. 빗물이 손등을 타고 흐른다.<br><br>
    위에서 손이 하나 내려왔다. 일행이 끼던 장갑이다. 잡으라고 한다. 목소리도 맞다.<br>
    줄 위에서 받아 주는 손을 여러 번 잡아 봤다. 끌어 올릴 손은 손목에 힘줄이 선다.<br><br>
    저 손목에는 힘줄이 없다. 손바닥이 아래를 향했다. 미는 손이다.`,
    o:[
      { l:'① 손을 피해 벽을 차고 스스로 오른다.', k:'evade', dc:21,
        ok:`손 옆으로 벽을 찼다. 손이 빈 데를 짚었다.<br><br>처마 끝 홈통을 잡고 몸을 끌어 올렸다. 옆으로 굴러 옥상에 들어왔다. 손 주인은 이미 계단 문 안으로 들어갔다. 장갑 한 짝이 옥상에 떨어져 있다.<br>장갑 주인인 일행은 아래층에서 이쪽을 찾고 있었다. 두 손에 장갑이 다 있다.<br><br>그러면 저 한 짝은 누가 벗어 놓은 것이다.`,
        ng:`벽을 찼는데 벽이 젖었다.<br><br>발이 미끄러졌다. 손가락 끝 하나로 매달렸다. 그 손을 위의 발이 밟았다. 가볍게.<br>다른 손으로 홈통을 잡아 버텼다. 발이 떠났다. 기어오르고 나서 손가락 하나가 안 굽혀진다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-26, spirit:-14 } },
      { l:'② 아래층 창을 차서 일행을 부른다.', k:'bond', dc:20,
        ok:`손을 무시하고 아래층 창을 발로 찼다. 유리가 깨지지 않을 만큼. 세 번.<br><br>창이 열렸다. 일행이 내다봤다. 이쪽 발목을 잡아 안으로 당겼다. 진짜 손이다. 손목에 힘줄이 섰다.<br>위를 봤다. 내민 손이 천천히 거둬졌다.<br><br>안으로 들어와 일행을 셌다. 다 있다. 그러면 위의 손은 일행 수에 없다.`,
        ng:`창을 찼는데 안 열렸다. 안에서 커튼만 흔들렸다.<br><br>손가락이 먼저 풀렸다. 한 층을 떨어져 아래층 실외기 위에 떨어졌다. 실외기가 찌그러졌다.<br>늑골이 결린다. 위에서 손이 박수를 두 번 쳤다.`,
        win:{ exp:16, dream:1, hp:8 }, lose:{ hp:-30, mind:-12 } },
      { l:'③ 손을 잡고, 미는 힘으로 몸을 흔든다.', k:'evade', dc:22,
        ok:`손을 잡았다. 손이 밀었다. 미는 힘을 그대로 받아 몸을 바깥으로 흔들었다. 그네처럼.<br><br>돌아오는 흔들림에 손을 놓았다. 몸이 아래층 열린 창으로 들어갔다. 바닥을 구르며 내렸다.<br>위에서 손이 빈 데를 잡았다. 잡을 게 없다. 손이 한동안 그대로 있었다.<br><br>남이 미는 힘도 받아 내면 이쪽 힘이다.`,
        ng:`손을 잡는 순간 손이 먼저 놓았다.<br><br>몸이 떨어졌다. 아래층 창틀에 배를 찧었다. 숨이 멈췄다. 매달려서 숨이 돌아오기를 기다렸다.<br>창 안으로 굴러 들어갔다. 위에서 장갑 한 짝이 떨어져 이쪽 얼굴 위에 내려앉았다.`,
        win:{ exp:22, dream:2 }, lose:{ hp:-30, mind:-14 } }
    ] },

  { at:'B', t:'열 층 창밖 — 한 뼘 턱',
    x:`방 안으로 누가 들어왔다. 문 밑으로 그림자가 먼저 들어왔다.<br><br>
    이쪽은 창밖이다. 창 턱에 섰다. 한 뼘 너비. 비가 등을 친다. 열 층 아래 차도에서 경적이 길게 운다.<br>
    옆 방 창까지 다섯 걸음. 턱이 이어진다. 중간에 비둘기 둥지가 하나 있다.<br><br>
    벽에는 등이 아니라 배를 붙인다. 넘어질 때 벽 쪽으로 넘어지게.`,
    o:[
      { l:'① 턱을 따라 옆 방으로 간다.', k:'evade', dc:20,
        ok:`배를 벽에 붙이고 옆걸음으로 갔다. 발뒤꿈치는 허공에 있었다.<br><br>둥지에서 비둘기가 날았다. 날개가 얼굴을 쳤다. 몸이 뒤로 기운다. 배로 벽을 눌렀다. 돌아왔다.<br>옆 방 창으로 들어갔다. 빈방이다. 침대 위에 이쪽 짐이 놓여 있다. 이쪽은 이 방에 짐을 둔 적이 없다.<br><br>짐을 열지 않고 나왔다.`,
        ng:`비둘기가 날았다. 놀란 건 이쪽 발이었다.<br><br>한 발이 턱에서 빠졌다. 창틀을 잡았다. 유리가 깨졌다. 손바닥에 박혔다.<br>방 안의 그림자가 깨진 소리 쪽으로 돌아섰다. 옆 방으로 굴러 들어갔다. 피가 창틀에 길게 남았다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-28, mind:-10 } },
      { l:'② 창 위 차양에 올라 엎드린다.', k:'hide', dc:21,
        ok:`창 위 차양을 잡고 올라섰다. 차양이 빗물에 휘청인다. 엎드렸다.<br><br>창이 열렸다. 머리 하나가 나와 아래를 본다. 열 층 아래를. 오래 본다. 이쪽은 그 머리 바로 위다. 차양에서 빗물이 그 정수리에 떨어진다.<br>머리가 들어갔다. 창이 닫혔다.<br><br>그 사람은 정수리에 떨어지는 물을 한 번도 닦지 않았다.`,
        ng:`차양이 이쪽 무게를 싫어했다.<br><br>고정쇠 하나가 빠지며 한쪽이 기울었다. 미끄러져 창 앞으로 떨어질 뻔했다. 창틀 위를 겨우 잡았다.<br>창 안의 얼굴과 눈이 마주쳤다. 유리 한 장 사이다. 그 얼굴은 놀라지 않았다.`,
        win:{ exp:16, dream:2 }, lose:{ hp:-22, spirit:-16 } }
    ] },

  { at:'B1', t:'야적장 — 젖은 크레인 팔',
    x:`컨테이너 야적장 위로 크레인 팔이 뻗었다. 팔 끝이 방파제 쪽을 가리킨다.<br><br>
    탐조등이 야적장을 훑는다. 바닥을 지날 때 빗줄기가 하얗게 선다. 위는 안 훑는다. 아무도 위로 다니지 않으니까.<br>
    크레인 팔은 쇠 격자다. 걸으라고 만든 게 아니다. 바다 쪽 바람이 팔을 흔든다.<br><br>
    곡예사는 아래를 보지 않는다. 그건 거짓말이다. 아래를 보고, 그다음에 안 본다.`,
    o:[
      { l:'① 크레인 팔 위를 걸어 방파제로 간다.', k:'evade', dc:21,
        doom:{ title:'크레인 팔', what:'크레인 팔에서 미끄러졌습니다', dc:17, sec:55,
          text:`팔 위를 반쯤 갔다. 격자 사이로 야적장이 내려다보인다. 탐조등이 그 위를 지난다.<br><br>그때 크레인이 돌기 시작했다. 운전실에 불이 켜졌다. 아무도 안 탔던 운전실이다.<br>팔이 바다 쪽으로 휜다. 몸이 기울어 격자에서 미끄러진다. 한 손이 철선에 걸렸다. 발밑에 검은 물이 있다.<br><br>운전실 유리에 비가 흐른다. 그 안에서 누가 레버를 하나 더 당긴다.`,
          dieText:`아무도 위로 다니지 않는다. 그래서 위를 안 훑는 줄 알았다.<br><br>크레인은 원래 무언가를 들어 옮기는 기계다.<br>팔이 제자리로 돌아왔다. 갈고리 끝에 젖은 끈 한 가닥이 걸려 흔들린다.` },
        ok:`격자 이음매만 디뎠다. 이음매는 볼트가 받친다.<br><br>반쯤 갔을 때 운전실에 불이 켜졌다. 크레인이 돈다. 걸음을 멈추지 않았다. 도는 쪽 반대로 몸을 실었다. 팔이 도는 만큼 방파제가 가까워졌다.<br>팔 끝에서 방파제 등대 난간으로 내려섰다.<br><br>뒤에서 운전실 불이 꺼졌다. 크레인이 이쪽을 실어다 준 셈이다. 그럴 생각은 아니었을 것이다.`,
        win:{ exp:25, dream:3 } },
      { l:'② 팔 밑 사다리로 컨테이너 지붕에 내린다.', k:'sense', dc:20,
        ok:`팔 밑에 정비 사다리가 달렸다. 내려가 컨테이너 지붕에 섰다.<br><br>탐조등이 컨테이너 옆면을 훑고 간다. 지붕은 안 비춘다. 지붕에서 지붕으로 건넜다.<br>열린 컨테이너 하나에 건어물 상자가 있다. 말린 고기 한 묶음을 품에 넣었다.<br><br>상자 송장에 받는 사람 칸이 비었다. 여기 있는 것은 다 받는 사람이 없다.`,
        ng:`사다리 마지막 칸이 없었다.<br><br>컨테이너 지붕까지 떨어졌다. 쇠지붕이 크게 울었다. 탐조등이 그쪽으로 고개를 돌렸다.<br>지붕 틈으로 몸을 밀어 넣었다. 빛이 머리 위에서 오래 머물렀다. 무릎이 쇠에 찍혔다.`,
        win:{ exp:16, item:'말린 고기' }, lose:{ hp:-24, mind:-12 } },
      { l:'③ 탐조등 탑에 올라 등을 꺾어 놓는다.', k:'break', dc:21,
        ok:`탐조등 탑 사다리를 탔다. 젖은 가로대 서른 칸. 꼭대기에서 등 받침 볼트를 발로 찼다. 세 번.<br><br>등이 고개를 떨궜다. 바다 쪽만 비춘다. 비가 하얗게 서는 바다 위만 훑는다.<br>야적장이 까매졌다. 그 까만 데를 걸어서 건넜다.<br><br>바다를 비추는 불빛 끝에 작은 배가 하나 떠 있다. 불이 없는 배다. 이쪽이 등을 꺾기 전부터 거기 있었다.`,
        ng:`둘째 발길질에 등이 돌았다. 이쪽 쪽으로.<br><br>눈앞이 하얘졌다. 아무것도 안 보인다. 아래에서 호루라기 소리가 났다.<br>더듬어 사다리를 내려왔다. 마지막 다섯 칸은 떨어졌다. 눈앞에 하얀 동그라미가 오래 떠 있었다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-22, mind:-16 } }
    ] },

  { at:'B1', t:'냉동 창고 — 레일의 갈고리',
    x:`냉동 창고 천장에 레일이 지난다. 갈고리가 줄지어 매달려 움직인다. 아무것도 안 걸렸다.<br><br>
    바닥은 얼음이다. 저쪽에서 고무장화 소리가 난다. 청소하는 소리다. 솔이 얼음을 문지른다.<br>
    레일은 창고 끝 활송구까지 간다. 그 너머가 바깥이다.<br><br>
    매달린 것을 잡고 건너는 건 익숙하다. 손이 얼면 어떻게 되는지는 아직 모른다.`,
    o:[
      { l:'① 갈고리에 매달려 레일을 따라간다.', k:'evade', dc:21, wake:1,
        ok:`지나가는 갈고리를 잡았다. 쇠가 얼어서 손바닥이 붙는다. 붙는 게 오히려 낫다. 안 미끄러진다.<br><br>다리를 접어 올렸다. 아래로 고무장화가 지나간다. 솔질 소리가 이쪽 그림자 위에서 잠깐 멈췄다. 다시 이어졌다.<br>활송구 앞에서 갈고리를 놓았다. 손바닥 살갗이 쇠에 조금 남았다.<br><br>매달린 동안 팔이 아니라 등으로 버텼다. 언제 배운 건지 모른다. 몸이 혼자 무게 둘 데를 찾았다.`,
        ng:`손바닥이 쇠에 붙었다. 너무 붙었다.<br><br>놓아야 할 데서 안 놓아졌다. 갈고리가 이쪽을 반대쪽으로 데려간다. 억지로 떼어 냈다. 살갗이 쇠에 남았다.<br>얼음 바닥에 떨어졌다. 솔질 소리가 멈췄다. 고무장화가 이쪽으로 온다. 서두르지 않는다.`,
        win:{ exp:22, dream:2 }, lose:{ hp:-26, mind:-12 } },
      { l:'② 무력을 실어 레일 위로 올라탄다.', k:'steady', dc:20, cost:{ might:24 },
        ok:`갈고리를 잡고 몸을 끌어 올렸다. 레일 위로 올라섰다. 레일 폭은 손바닥만 하다.<br><br>엎드려 레일을 끌어안고 같이 움직였다. 갈고리가 이쪽 밑에서 흔들린다. 아래에서 보면 빈 갈고리뿐이다.<br>창고 끝에 소금 자루가 쌓였다. 레일에서 내려 그 위로 떨어졌다. 터진 자루에서 소금 덩이 하나를 주웠다.<br><br>솔질 소리가 멈추지 않는다. 같은 자리를 계속 문지른다. 거기 뭐가 있는지 보지 않았다.`,
        ng:`끌어 올리다 팔이 얼었다. 힘이 반만 들어간다.<br><br>레일에 반만 올라탔다. 다리가 아래로 늘어졌다. 고무장화가 그 밑을 지나갔다. 솔이 이쪽 신발 끝을 한 번 문지르고 갔다.<br>내려와 보니 신발 끝이 하얗게 바랬다. 표백제다.`,
        win:{ exp:18, item:'소금 덩이' }, lose:{ hp:-22, spirit:-14 } }
    ] },

  { at:'B1', t:'야적장 — 다섯 단 위',
    x:`컨테이너가 다섯 단으로 쌓였다. 단 사이 골목이 미로다. 골목 끝마다 우비를 입은 것이 하나씩 서 있다. 얼굴은 모른다.<br><br>
    꼭대기 단은 아무도 안 지킨다. 컨테이너 사이 틈이 한 걸음 반이다. 쇠지붕이 빗물에 번들거린다.<br>
    멀리 해무호 불빛이 방파제 끝에 붙었다. 시계는 04:12.<br><br>
    틈은 걸음으로 세지 않는다. 숨으로 센다.`,
    o:[
      { l:'① 꼭대기 단으로 올라 지붕을 건너뛴다.', k:'evade', dc:21, wake:1,
        ok:`컨테이너 문 손잡이를 딛고 다섯 단을 올라갔다.<br><br>첫 틈을 뛰었다. 숨 하나. 둘째 틈, 숨 하나. 셋째 틈에서는 숨을 들이쉰 채 내렸다. 쇠지붕이 울지 않았다. 발바닥이 먼저 소리를 먹었다.<br>아래 우비들은 위를 안 본다. 서로 마주 보고 서 있다. 지키는 게 아니라 기다리는 것이다.<br><br>마지막 틈 너머가 방파제 길이다. 내려선 소리가 이쪽 귀에도 안 들렸다. 발이 쇠를 어떻게 먹는지 알았다.`,
        ng:`셋째 틈에서 숨이 엉켰다.<br><br>모서리에 정강이를 찍으며 내렸다. 쇠지붕이 종처럼 울었다. 아래 우비들이 한꺼번에 위를 봤다.<br>엎드려서 빗소리가 그 소리를 덮기를 기다렸다. 덮였다. 정강이 피가 빗물에 섞여 흘렀다.`,
        win:{ exp:22, dream:2 }, lose:{ hp:-26, mind:-12 } },
      { l:'② 우비 하나를 오래 지켜본다.', k:'gaze', dc:20,
        ok:`가장 가까운 우비를 봤다. 비가 오는데 어깨가 안 젖는다. 안이 비었다. 옷걸이에 걸어 세워 둔 것이다.<br><br>다섯 중 넷이 그렇다. 하나만 숨을 쉰다. 그 하나 앞만 피해 지나갔다.<br>빈 우비 주머니에 약초 뭉치가 들어 있다. 누군가의 상비약이었다.<br><br>숨 쉬는 하나는 끝내 고개를 안 돌렸다. 그것도 세워 둔 것인지 모른다.`,
        ng:`오래 보다가 들켰다.<br><br>빈 줄 알았던 우비가 고개를 돌렸다. 손에 쥔 것이 번쩍였다.<br>뛰었다. 골목 셋을 지나서야 발소리가 끊겼다. 옆구리가 길게 베였다. 언제 베였는지 모른다.`,
        win:{ exp:16, item:'약초 뭉치' }, lose:{ hp:-28, spirit:-14 } }
    ] },

  { at:'B1', t:'방파제 — 계류줄',
    x:`해무호는 방파제에 굵은 줄 두 가닥으로 묶여 있다. 배가 파도에 들리면 줄이 팽팽해진다. 내려앉으면 처진다.<br><br>
    배에 오를 건 아니다. 배 너머 방파제 끝 계단이 바깥 길로 이어진다. 배가 그 길을 막고 있다.<br>
    갑판에 양동이 하나가 놓였다. 걸레가 걸쳐졌다. 갑판은 깨끗하다. 깨끗한데 아직 젖었다.<br><br>
    곡예사는 줄을 탄다. 움직이는 줄은 처음이다.`,
    o:[
      { l:'① 처진 줄에 올라 박자에 맞춰 건넌다.', k:'evade', dc:22,
        ok:`배가 내려앉을 때 줄에 올랐다. 처진 줄은 발을 받는다.<br><br>배가 들린다. 줄이 팽팽해지며 이쪽을 위로 튕긴다. 무릎을 굽혀 받았다. 다시 처진다. 세 번 들리고 세 번 처지는 동안 반을 건넜다.<br>갑판을 밟지 않고 줄 끝 말뚝에서 방파제 계단으로 내렸다.<br><br>갑판의 양동이가 이쪽을 향해 놓여 있다. 아까는 반대쪽이었다.`,
        ng:`배가 생각보다 높이 들렸다.<br><br>줄이 튕겨 이쪽이 떨어졌다. 줄을 손으로 잡았다. 매달린 채 배와 방파제 사이로 흔들렸다. 그 사이로 배가 방파제에 부딪는다.<br>다리를 끌어 올리는 순간 그 틈이 닫혔다. 신발 하나가 바다로 갔다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-30, mind:-12 } },
      { l:'② 무력을 실어 줄에 거꾸로 매달려 건넌다.', k:'steady', dc:21, cost:{ might:25 },
        ok:`줄에 두 손으로 매달렸다. 다리도 줄에 걸었다. 거꾸로.<br><br>배가 들리면 같이 들렸다. 내려앉으면 같이 내렸다. 손은 줄이 멈췄을 때만 옮겼다. 손바닥이 젖은 줄에 탄다.<br>말뚝까지 갔다. 계단으로 넘었다. 팔이 이쪽 팔 같지 않다.<br><br>뒤에서 누가 줄을 칼로 끊는 소리가 났다. 이쪽이 건넌 바로 뒤다. 조금만 일찍 끊었어도 됐을 텐데.`,
        ng:`반쯤 가서 배가 크게 기울었다.<br><br>줄이 비틀렸다. 걸었던 다리가 풀렸다. 손으로만 매달려 물 위에서 버텼다.<br>파도가 등을 쳤다. 손을 하나씩 옮겨 겨우 건넜다. 손바닥 껍질이 줄에 다 남았다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-26, spirit:-14 } }
    ] },

  { at:'B2', t:'병실 — 배식구',
    x:`병실 문은 안에서 안 열린다. 문 아래 배식구가 있다. 쟁반 하나 들어가는 너비다. 밖에서만 열리는 덮개가 달렸다.<br><br>
    복도에서 바퀴 소리가 난다. 배식 카트다. 이 시간에 배식은 없다. 03:00.<br>
    카트가 문 앞에 섰다. 덮개가 열렸다. 쟁반이 들어왔다. 종이컵 하나. 물이 담겼다.<br><br>
    쟁반 하나 너비면 몸 하나 너비로 만들 수 있다. 다만 덮개는 금방 닫힌다.`,
    o:[
      { l:'① 덮개가 닫히기 전에 배식구로 빠진다.', k:'evade', dc:22, wake:1,
        ok:`쟁반을 받는 척 손을 넣었다. 어깨를 하나 빼고 머리를 눕혔다. 갈비를 접었다. 골반이 제일 늦게 접힌다. 접혔다.<br><br>복도 바닥으로 미끄러져 나왔다. 카트 밑이다. 카트를 민 사람의 발이 보인다. 흰 실내화. 발목에 이름표가 걸렸다. 사진 칸이 비었다.<br>카트가 다음 문으로 갔다. 이쪽은 카트 밑에 매달려 같이 갔다.<br><br>몸이 접히는 순서를 처음으로 이쪽이 정했다. 전에는 몸이 정했다.`,
        ng:`골반에서 걸렸다.<br><br>덮개가 내려와 허리를 눌렀다. 반은 복도, 반은 병실이다. 카트를 민 사람이 내려다본다. 종이컵을 집어 이쪽 입에 댄다. 고개를 돌렸다.<br>억지로 빠져나왔다. 허리에 덮개 자국이 깊다. 쏟아진 물에서 단내가 났다.`,
        win:{ exp:22, dream:2 }, lose:{ hp:-24, mind:-14 } },
      { l:'② 물은 두고 쟁반을 뒤집어 본다.', k:'gaze', dc:20,
        ok:`쟁반을 뒤집었다. 밑에 테이프로 열쇠가 붙어 있다. 이 병실 열쇠다. 누가 붙였는지 모른다. 쟁반을 돌려받는 사람은 뒷면을 안 본다.<br><br>문을 열었다. 복도가 비었다. 카트만 다음 문 앞에 서 있다. 아래 칸에 꿀 한 줌이 든 종지가 있다. 밤참이라고 적혔다.<br>꿀은 챙겼다. 종이컵은 그대로 두었다.<br><br>카트 위 종이컵이 하나도 줄지 않았다. 다른 방들도 안 마셨다.`,
        ng:`쟁반 뒤집는 소리가 컸다.<br><br>덮개가 닫혔다가 다시 열렸다. 이번에는 쟁반 대신 눈이 하나 들여다봤다. 오래.<br>덮개가 닫혔다. 그다음부터 병실 불이 꺼지지 않는다. 눈을 감아도 밝다.`,
        win:{ exp:16, item:'꿀 한 줌' }, lose:{ mind:-14, spirit:-16 } }
    ] },

  { at:'B2', t:'점호 — 하나 빈 침대',
    x:`점호다. 손전등 하나가 병실을 차례로 돈다. 침대마다 비추고 수를 센다. 일곱 병실, 스물한 침대.<br><br>
    무리가 한 병실에 숨어들었다. 침대 셋에 원래 환자가 셋이어야 한다. 둘뿐이다. 침대 하나가 비었다.<br>
    수가 맞아야 한다. 안 맞으면 문이 전부 잠긴다. 아까 잠기는 걸 봤다. 다시 열리는 건 못 봤다.<br><br>
    천장에 배관이 지난다. 병실과 병실 사이 벽 위로 넘어간다.`,
    o:[
      { l:'① 세어지고, 배관을 넘어 옆 방에서 또 세어진다.', k:'evade', dc:21, wake:1,
        ok:`빈 침대에 누워 손전등을 받았다. 하나.<br><br>손전등이 옆 병실로 가는 사이 배관을 잡고 올라갔다. 벽 위 틈을 넘었다. 옆 병실에도 빈 침대가 있다. 내려가 이불을 덮었다. 손전등이 들어왔다. 하나.<br>스물하나. 맞았다. 손전등이 나갔다.<br><br>두 번 세어진 몸으로 배관을 넘어 돌아왔다. 숨이 하나도 안 찼다. 높은 데서 낮은 데로 옮기는 동안 몸이 소리 없이 무게를 옮겨 실었다.`,
        ng:`옆 병실 침대로 내리다 배관 받침이 삐걱 울었다.<br><br>손전등이 천장을 비췄다. 이쪽은 이미 이불 속이다. 빛이 이불 위에 오래 머물렀다. 하나, 했다. 그리고 하나, 를 한 번 더 했다.<br>스물둘. 복도 끝에서 문 잠기는 소리가 났다. 무리 전부 다른 길을 찾아야 했다.`,
        win:{ exp:22, dream:3 }, lose:{ mind:-16, spirit:-14 } },
      { l:'② 빈 침대에 일행을 눕히고 침대 밑에 숨는다.', k:'bond', dc:20,
        ok:`무리 중 숨이 가장 고른 사람을 빈 침대에 눕혔다. 이불을 목까지 덮었다. 이쪽과 나머지는 침대 밑에 들어갔다.<br><br>손전등이 셋을 셌다. 맞다. 침대 밑은 비추지 않는다. 세는 건 침대다.<br>손전등이 나갔다. 누웠던 일행이 일어나 이불을 걷었다. 베개 밑에 손목 띠가 하나 있다. 이름이 적혔다. 그 일행의 이름이다.<br><br>아무도 그 이름을 여기 쓴 적이 없다.`,
        ng:`손전등이 침대 밑까지 내려왔다.<br><br>이쪽 얼굴 위에 빛이 섰다. 세는 목소리가 멈췄다. 넷, 했다. 이 병실에는 침대가 셋이다.<br>문이 잠겼다. 다시 열리는 데 반 시간이 걸렸다. 그 반 시간 동안 아무도 말을 안 했다.`,
        win:{ exp:16, dream:2, mind:6 }, lose:{ mind:-14, spirit:-18 } }
    ] },

  { at:'B2', t:'복도 — 굴러오는 침대',
    x:`긴 복도다. 끝에 계단 문이 있다. 문 위 비상구 표시가 초록이다.<br><br>
    복도 저쪽에서 침대가 굴러온다. 바퀴 달린 병원 침대가 줄지어 밀려온다. 미는 사람은 안 보인다. 침대마다 시트가 덮였다. 시트 아래가 사람 모양이다.<br>
    벽 양옆으로 비킬 틈은 없다. 침대 너비가 복도 너비다.<br><br>
    넘으면 된다. 짐 없이, 소리 없이.`,
    o:[
      { l:'① 침대 위를 딛고 넘어간다.', k:'evade', dc:21,
        doom:{ title:'시트', what:'침대에 실려 갑니다', dc:17, sec:50,
          text:`첫 침대 머리판을 짚고 넘었다. 둘째 침대 난간을 딛고, 셋째로.<br><br>넷째 침대 위를 디뎠는데 시트가 꺼졌다. 아래가 비었다. 사람 모양으로 접혀 있었을 뿐이다. 발이 매트리스 틈에 빠졌다. 난간이 올라와 발목을 물었다.<br>침대가 이쪽을 싣고 돌아선다. 복도 반대편으로 굴러간다. 그쪽 끝에 문이 열려 있다. 안이 하얗다.<br><br>바퀴 소리가 빨라진다.`,
          dieText:`시트 아래가 사람 모양이었다. 이제는 맞다.<br><br>하얀 문이 닫혔다. 문 위 명판에 처치실이라고 적혔다.<br>복도 끝에서 점호 목소리가 침대 하나를 더 센다.` },
        ok:`첫 침대 머리판을 짚고 넘었다. 둘째 침대 난간을 딛고, 셋째로. 시트 아래는 밟지 않았다. 난간만 디뎠다.<br><br>넷째 침대 시트가 바람에 꺼졌다. 아래가 비었다. 난간만 디딘 게 맞았다.<br>마지막 침대를 넘어 계단 문 앞에 내렸다. 뒤로 침대들이 계속 굴러간다. 반대편 하얀 문 안으로 하나씩 들어간다.<br><br>문 안에서 누가 침대를 센다. 하나 모자란다고 한다.`,
        win:{ exp:25, dream:3 } },
      { l:'② 첫 침대 밑으로 미끄러져 든다.', k:'hide', dc:20,
        ok:`바닥에 누워 미끄러졌다. 첫 침대 밑으로. 바퀴 사이에 몸을 맞췄다.<br><br>침대들이 머리 위로 지나간다. 밑판이 코앞을 스친다. 어느 밑판에 손톱 자국이 있다. 위에서, 안쪽에서 긁은 자국이다.<br>다 지나갔다. 일어나 계단 문으로 갔다.<br><br>손톱 자국을 떠올려 셌다. 열. 손가락 수다.`,
        ng:`바퀴 하나가 손등을 밟고 지나갔다.<br><br>소리를 삼켰다. 둘째 침대 바퀴가 같은 손등을 밟았다. 셋째도. 침대들이 한 줄을 따라 굴렀다.<br>다 지나가고 손을 쥐어 봤다. 안 쥐어진다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-28, mind:-12 } }
    ] },

  { at:'B2', t:'세탁실 — 아래로 난 통로',
    x:`세탁실 벽에 쇠 뚜껑이 있다. 열면 아래로 곧게 떨어지는 통로다. 빨랫감을 지하로 보내는 길이다.<br><br>
    계단은 전부 잠겼다. 엘리베이터는 7층에서만 선다. 내려가는 길은 이것뿐이다.<br>
    통로에서 바람이 올라온다. 세제 냄새. 그 밑에 다른 냄새.<br><br>
    떨어지기 전에는 어디서 멈출지 먼저 정한다. 이 통로는 멈출 데가 안 보인다.`,
    o:[
      { l:'① 등과 발로 벽을 버티며 내려간다.', k:'evade', dc:21,
        ok:`등을 한쪽 벽에, 발을 반대쪽 벽에 댔다. 몸을 다리처럼 걸쳤다. 한 칸씩 내려갔다.<br><br>층마다 쇠 뚜껑이 있다. 6, 5, 4. 4층 뚜껑 틈으로 불빛이 샌다. 안에서 누가 빨래를 갠다. 이 시간에.<br>지하까지 내려왔다. 빨랫감 더미 위에 내렸다. 시트 사이로 물 한 병이 굴러다닌다. 뚜껑이 안 따졌다.<br><br>더미 위쪽 시트에는 7층 병상 번호가 찍혔다. 스물두 장이다.`,
        ng:`5층에서 뚜껑이 열렸다. 빨랫감이 쏟아져 내려왔다.<br><br>무게에 밀려 등이 벽에서 떨어졌다. 두 층을 미끄러져 4층 턱에 걸렸다. 등이 다 쓸렸다.<br>위에서 뚜껑이 닫혔다. 쏟아진 시트에 젖은 손으로 짚은 자국이 있었다.`,
        win:{ exp:18, item:'맑은 물' }, lose:{ hp:-28, mind:-12 } },
      { l:'② 무력을 실어 시트를 꼬아 줄을 만든다.', k:'fix', dc:20, cost:{ might:22 },
        ok:`시트를 꼬아 묶었다. 당길수록 조이는 매듭으로. 쇠 뚜껑 경첩에 걸었다.<br><br>줄을 타고 내려갔다. 팔로만. 무리가 뒤를 따랐다. 매듭이 하나도 안 풀렸다.<br>마지막 사람이 내려오고 줄을 당겨 거뒀다. 위에 남기면 따라온다.<br><br>거둔 시트 하나에 이름이 수놓여 있었다. 무리 중 누구 이름도 아니다. 다음에 올 사람 이름일 것이다.`,
        ng:`셋째 매듭에서 시트가 찢어졌다.<br><br>찢어지는 소리를 듣고 팔로 벽을 짚었다. 떨어지는 건 멈췄다. 손가락 끝이 다 까졌다.<br>위의 무리가 남은 시트로 이쪽을 끌어 올렸다. 다시 묶는 데 오래 걸렸다. 그동안 복도에서 점호 목소리가 가까워졌다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-22, spirit:-14 } }
    ] },

  { at:'B3', t:'객차 지붕 — 터널',
    x:`객차 안에 그것이 있다. 얼굴을 바꾸는 손님. 앞 칸으로 가는 통로는 그 옆을 지나야 한다.<br><br>
    창을 열었다. 빗바람이 쏟아져 들어온다. 창 위에 지붕으로 오르는 쇠고리가 있다.<br>
    지붕 위로는 비가 옆으로 친다. 기차가 얼마나 빠른지는 생각하지 않기로 했다.<br><br>
    앞쪽에서 기적이 운다. 터널 앞에서 우는 소리다.`,
    o:[
      { l:'① 지붕을 달려 앞 칸으로 간다.', k:'evade', dc:22,
        doom:{ title:'터널', what:'터널 입구에 걸렸습니다', dc:18, sec:45,
          text:`지붕 위를 달렸다. 객차와 객차 사이를 뛰어 넘었다. 한 칸, 두 칸.<br><br>앞에서 산이 다가온다. 터널 입구가 검다. 엎드려야 한다. 엎드릴 자리에 환기통이 솟았다.<br>환기통 옆으로 몸을 굴렸다. 외투 자락이 환기통에 걸렸다. 몸이 지붕 위로 반쯤 들렸다.<br><br>터널 입구의 돌 테두리가 다가온다. 들린 높이만큼.`,
          dieText:`기차는 서지 않는다. 터널도 비키지 않는다.<br><br>터널을 빠져나온 지붕 위에 외투 한 벌이 환기통에 걸려 펄럭인다.<br>안내 방송이 다음 역을 부른다. 내리실 문은 오른쪽입니다.` },
        ok:`지붕 위를 달렸다. 객차 사이를 뛰어 넘었다.<br><br>기적이 한 번 더 운다. 달리면서 외투를 벗어 던졌다. 걸릴 것이 없다. 환기통 사이에 엎드렸다. 등 위로 돌 천장이 지나간다. 공기가 눌린다. 귀가 먹먹하다.<br>터널을 나왔다. 다음 칸 지붕 고리를 잡고 내려 창으로 들어갔다.<br><br>창가 손님이 이쪽을 보고 고개를 끄덕였다. 아까 뒤 칸에서 본 얼굴이다. 이쪽보다 먼저 와 있다.`,
        win:{ exp:25, dream:3 } },
      { l:'② 무력을 실어 창틀을 잡고 옆으로 간다.', k:'steady', dc:21, cost:{ might:25 },
        ok:`창틀에서 창틀로 손을 옮겼다. 발은 객차 밑 발판 턱에 걸었다. 바퀴가 바로 아래서 돈다.<br><br>창마다 안이 보인다. 손님들이 잔다. 셋째 창 손님이 이쪽으로 고개를 돌린다. 눈을 뜨지 않은 채. 손을 옮겼다.<br>칸 끝 연결 통로 문으로 들어갔다. 팔이 빗물보다 무겁다.<br><br>창에 남긴 손자국이 빗물에 안 지워진다. 안쪽에서 누가 그 손자국에 손을 맞대고 있다.`,
        ng:`넷째 창틀이 젖은 고무였다.<br><br>손이 미끄러졌다. 한 손으로 매달려 객차 옆구리에 붙었다. 침목이 발밑에서 흐른다. 버텼다.<br>창이 안에서 열렸다. 손 하나가 이쪽 손목을 잡아 안으로 당겼다. 고마웠다. 손목에 남은 자국은 손가락이 여섯 개다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-30, mind:-14 } },
      { l:'③ 그것 옆을 옷자락 하나 안 닿게 지난다.', k:'evade', dc:21,
        ok:`통로로 걸었다. 그것이 좌석에 앉아 신문을 펼쳤다. 다리를 통로에 뻗었다.<br><br>다리를 넘었다. 어깨를 틀어 신문 끝을 비켰다. 옷자락 하나 안 닿았다. 닿은 것의 얼굴을 쓴다고 했다. 등받이 글씨가 그렇게 적었다.<br>앞 칸 문을 열었다. 등 뒤에서 신문 넘기는 소리가 났다.<br><br>문 유리에 비친 신문 1면에 이쪽 얼굴 사진이 있었다. 표정이 지금 이쪽 표정이다.`,
        ng:`기차가 덜컹했다. 어깨가 신문 끝을 스쳤다.<br><br>신문이 내려갔다. 그 뒤의 얼굴이 이쪽을 봤다. 한 번 깜박이더니 이쪽 얼굴이 됐다. 이쪽보다 조금 늦게 깜박인다.<br>앞 칸으로 뛰었다. 등 뒤에서 이쪽 목소리가 이쪽 이름을 불렀다.`,
        win:{ exp:20, dream:2 }, lose:{ mind:-16, spirit:-20 } }
    ] },

  { at:'B3', t:'연결 통로 — 어긋나는 발판',
    x:`객차와 객차 사이 연결 통로다. 쇠 발판 두 장이 겹쳐 있다. 기차가 휠 때마다 발판이 어긋난다.<br><br>
    어긋난 틈 아래로 침목이 흘러간다. 빠르다. 빗물이 틈으로 튄다.<br>
    뒤 칸 문 유리에 얼굴 하나가 붙었다. 이쪽 일행의 얼굴이다. 일행은 전부 앞에 있다.<br><br>
    움직이는 발판 위에 서는 법은 안다. 움직이는 박자에 무릎을 맞춘다.`,
    o:[
      { l:'① 휘는 박자에 맞춰 건넌다.', k:'evade', dc:21, wake:1,
        ok:`기차가 왼쪽으로 휜다. 발판이 벌어진다. 오른쪽으로 휜다. 닫힌다. 그 박자를 무릎으로 받았다.<br><br>닫히는 박자에 건넜다. 문을 열고 들어갔다. 등 뒤에서 발판이 다시 벌어졌다.<br>뒤 칸 문이 열렸다. 일행 얼굴을 한 것이 발판에 섰다. 박자를 모른다. 벌어진 틈에 발이 빠졌다. 소리 없이 빼고 다시 섰다.<br><br>앞으로 갔다. 발밑이 흔들려도 몸이 안 흔들린다. 흔들림을 무릎에서 다 받아 버렸다.`,
        ng:`커브가 둘 겹쳤다.<br><br>닫히는 줄 알았던 발판이 한 번 더 벌어졌다. 발이 틈에 빠졌다. 정강이가 쇠 모서리에 갈렸다. 침목 바람이 신발을 당긴다.<br>빼냈다. 신발 끈이 틈에 남았다. 뒤 칸 유리의 얼굴이 이쪽을 따라 웃는다.`,
        win:{ exp:22, dream:2 }, lose:{ hp:-28, mind:-12 } },
      { l:'② 뒤 칸 문을 묶어 두고 간다.', k:'fix', dc:20,
        ok:`외투 끈을 풀어 뒤 칸 문 손잡이와 난간을 묶었다. 매듭을 두 번 감았다.<br><br>유리의 얼굴이 손잡이를 돌린다. 문이 한 뼘에서 멈춘다. 끈이 팽팽하다. 그 틈으로 손이 나와 끈을 더듬는다. 매듭을 못 찾는다. 곡예단 매듭은 당길수록 조인다.<br>앞 칸으로 넘어갔다.<br><br>나중에 돌아보니 끈은 그대로다. 손도 얼굴도 없다. 다른 길로 오는 것이다.`,
        ng:`묶는 사이 기차가 휘었다.<br><br>발판이 벌어지며 이쪽이 난간에 매달렸다. 끈이 풀렸다. 문이 열렸다. 일행 얼굴을 한 것이 이쪽 손을 잡아 일으켜 줬다. 다정하게.<br>잡힌 손이 차갑다. 뿌리치고 앞 칸으로 뛰었다. 손등에 냉기가 오래 남았다.`,
        win:{ exp:16, dream:2 }, lose:{ mind:-14, spirit:-16 } }
    ] },

  { at:'B3', t:'침대칸 — 그물 선반',
    x:`침대칸 통로가 좁다. 통로 끝에 그것이 서 있다. 차장 옷을 입었다. 얼굴은 차장이 아니다. 아까 식당칸 종업원이었다.<br><br>
    통로로 가면 그것을 스친다. 위를 봤다. 위 칸 침대들 위로 짐 선반이 길게 이어진다. 그물로 된 선반이다.<br>
    선반으로 가면 그것의 머리 위를 지난다. 그물은 사람 무게를 받으라고 만든 게 아니다.<br><br>
    무게는 넷으로 나누면 가벼워진다. 두 손, 두 무릎.`,
    o:[
      { l:'① 선반에 올라 기어간다.', k:'evade', dc:21,
        ok:`위 칸 사다리를 밟고 선반에 올랐다. 그물 이음매만 짚었다. 무게를 손과 무릎 넷에 나눴다.<br><br>그것의 머리 위를 지났다. 그것이 고개를 든다. 멈췄다. 그물이 조금 처졌다. 그것은 짐을 본다. 짐 사이의 이쪽을 짐으로 본다.<br>통로 끝에서 소리 없이 내렸다.<br><br>선반에 누가 두고 간 꾸러미가 있었다. 말린 고기다. 챙겼다. 꾸러미 끈이 이쪽이 쓰는 매듭으로 묶여 있었다.`,
        ng:`그물 한 가닥이 끊어졌다.<br><br>무릎이 빠졌다. 매달렸다. 바로 아래서 그것이 올려다본다. 얼굴이 이쪽 얼굴로 바뀌는 중이다. 절반쯤.<br>그물을 끌어안고 기어 빠져나갔다. 무릎에 그물 자국이 깊다. 끝까지 뒤를 안 봤다.`,
        win:{ exp:18, item:'말린 고기' }, lose:{ hp:-22, spirit:-18 } },
      { l:'② 아래 칸 커튼 안으로 침대를 건너간다.', k:'hide', dc:21,
        ok:`아래 칸 커튼을 열고 들어갔다. 침대 사이 칸막이가 낮다. 넘었다. 다음 침대로.<br><br>침대마다 손님이 잔다. 깨지 않게 몸을 접어 지났다. 하나, 둘, 셋. 넷째 침대가 비었다. 베개가 아직 따뜻하다.<br>통로 끝에서 커튼을 열고 나왔다. 그것이 등 뒤에 있다. 이쪽을 못 봤다.<br><br>넷째 침대 주인이 어디 갔는지는 안다. 통로 끝에 서 있다.`,
        ng:`셋째 침대 손님이 눈을 떴다.<br><br>소리는 안 질렀다. 이쪽 소매를 잡았다. 놓지 않는다. 손님 얼굴이 잠깐 흐려졌다가 다시 맞춰졌다.<br>소매를 찢어 내고 빠져나왔다. 그 손님은 소매 조각을 쥔 채 계속 잤다.`,
        win:{ exp:18, dream:2 }, lose:{ mind:-16, spirit:-14 } }
    ] },

  { at:'B3', t:'맨 앞 칸 — 승강 발판',
    x:`맨 앞 칸 문이다. 내리는 문은 맨 앞에만. 열면 바깥 승강 발판이다. 기차는 서지 않는다.<br><br>
    시계는 04:39. 창밖으로 선로가 크게 휜다. 휠 때 기차가 조금 느려진다.<br>
    발판 아래로 자갈 둑이 흐른다. 비에 젖은 둑이다. 둑 너머는 풀숲이다.<br><br>
    곡예사는 뛰어내리는 법을 안다. 달리는 것에서 뛰어내리는 건 다른 이야기다. 땅도 달리고 있다.`,
    o:[
      { l:'① 휘는 데서 기차 방향으로 뛰어 구른다.', k:'evade', dc:22, wake:1,
        ok:`발판 끝에 섰다. 기차가 휜다. 느려진다. 기차가 가는 쪽을 보고 뛰었다. 땅에 닿기 전에 몸을 이미 말았다.<br><br>어깨, 등, 엉덩이, 다시 어깨. 네 바퀴. 자갈이 등을 긁고 풀숲이 받았다. 멈췄다. 숨을 쉬었다. 쉬어진다.<br>기차가 빗속으로 간다. 꼬리등이 작아진다.<br><br>구르는 동안 땅이 어느 쪽으로 흐르는지 몸이 셌다. 다음에는 안 세도 될 것 같다.`,
        ng:`뛰는 순간 기차가 덜컹했다.<br><br>방향이 틀어졌다. 옆으로 떨어졌다. 자갈 둑에 옆구리부터 닿았다. 구르지 못하고 미끄러졌다.<br>풀숲에 닿아 멈췄다. 일어나는 데 오래 걸렸다. 숨 쉴 때마다 갈비 쪽이 운다.`,
        win:{ exp:24, dream:3 }, lose:{ hp:-32, mind:-12 } },
      { l:'② 일행을 하나씩 먼저 내보낸다.', k:'bond', dc:21,
        ok:`일행을 발판에 세웠다. 하나씩 어깨를 잡고 기차가 휘는 박자를 셌다. 지금, 하고 밀었다. 기차 방향으로.<br><br>하나, 둘, 셋. 다 굴렀다. 마지막에 이쪽이 뛰었다.<br>풀숲에서 일어나 일행을 셌다. 맞다.<br><br>세는 동안 누가 이쪽 어깨를 두드렸다. 지금, 하는 목소리로. 돌아보니 아무도 없다. 꼬리등만 멀어진다.`,
        ng:`둘째 일행이 박자를 놓쳤다. 이쪽 손을 잡은 채.<br><br>둘이 같이 떨어졌다. 이쪽이 밑에 깔렸다. 자갈이 등을 찢었다. 일행은 이쪽 위에서 멀쩡했다.<br>남은 일행이 다 뛰어내릴 때까지 누워 있었다. 일어날 수가 없었다.`,
        win:{ exp:18, dream:2, spirit:8 }, lose:{ hp:-30, spirit:-12 } },
      { l:'③ 기관실 문을 두드려 세워 달라고 한다.', k:'luck', dc:22,
        ok:`기관실 문을 두드렸다. 세 번. 대답이 없다. 문 아래 틈으로 불빛이 샌다.<br><br>문이 열렸다. 기관사 모자를 쓴 것이 이쪽을 본다. 얼굴이 일행 중 하나다. 아니다, 셋이다. 바뀌는 중이다.<br>그것이 레버를 당겼다. 기차가 비명을 지르며 느려졌다. 발판에서 걸어 내리듯 뛰었다. 가볍게 내렸다.<br><br>왜 세워 줬는지 모른다. 다음 손님을 태우려는 것일 수도 있다.`,
        ng:`문이 안 열렸다. 안에서 누가 이쪽이 두드린 박자를 그대로 두드려 돌려보냈다.<br><br>시간을 썼다. 04:42. 휘는 데를 지났다. 곧은 선로에서 뛰어야 했다. 기차가 제일 빠를 때다.<br>뛰었다. 다섯 바퀴를 구르고도 안 멈췄다. 풀숲에 처박혔다. 한쪽 귀가 한동안 안 들렸다.`,
        win:{ exp:16, dream:4 }, lose:{ hp:-34, mind:-14 } }
    ] }
]);

// ── 경신술사 (lightfoot) · 내공 ──────────────
kJob('lightfoot', 'B', [
  { at:'B', t:'골목 — 깔아 둔 유리',
    x:`골목 바닥에 유리가 깔렸다. 병 조각이다. 깨진 지 얼마 안 됐다. 모서리가 날카롭다. 누가 일부러 깔았다.<br><br>
    골목 끝 담벼락에 남자 하나가 기대 섰다. 담뱃불이 빨갛게 켜졌다 꺼진다. 눈을 감고 있다. 듣고 있다.<br>
    유리를 밟으면 운다. 이 골목은 그러라고 깔아 둔 것이다.<br><br>
    경신술사는 무게를 덜어 걷는다. 덜어 낸 무게는 유리가 모른다.`,
    o:[
      { l:'① 발끝으로 유리 사이를 지난다.', k:'evade', dc:21, wake:1,
        ok:`유리와 유리 사이 맨바닥을 골랐다. 발끝만 닿게. 닿는 순간 뗐다.<br><br>남자 앞 다섯 걸음. 담뱃불이 켜졌다. 멈췄다. 꺼졌다. 다시 걸었다. 숨을 담뱃불 박자에 맞췄다.<br>남자 옆을 지났다. 남자가 눈을 감은 채 고개를 갸웃했다. 소리는 없는데 바람이 지나갔다.<br><br>골목을 나와서 알았다. 내내 발뒤꿈치가 땅에 한 번도 안 닿았다. 그런데 종아리가 안 아프다. 몸이 그 걸음을 쉬는 걸음으로 삼았다.`,
        ng:`맨바닥인 줄 알고 디딘 데에 유리 가루가 있었다.<br><br>사각, 했다. 아주 작게. 담뱃불이 바닥에 떨어졌다. 남자가 눈을 떴다.<br>뛰었다. 유리가 줄줄이 울었다. 발바닥이 베였다. 남자는 쫓아오지 않았다. 휘파람을 한 번 불었다. 골목 반대쪽에서 대답하는 휘파람이 왔다.`,
        win:{ exp:22, dream:2 }, lose:{ hp:-24, mind:-12 } },
      { l:'② 내공을 끌어올려 담장 위로 지난다.', k:'evade', dc:20, cost:{ qi:22 },
        ok:`숨을 단전에 모았다. 담장을 한 번 딛고 위로 올랐다. 담장 위는 한 뼘이다. 그 위로 달렸다.<br><br>담장 끝에 깨진 병이 꽂혀 있다. 넘는 사람 막으라고 꽂은 병이다. 그 사이를 발끝으로 짚었다.<br>남자 머리 위를 지났다. 남자가 연기를 위로 뿜었다. 연기가 이쪽 발목을 감고 지나갔다.<br><br>담장 끝에서 내공을 풀었다. 발이 땅에 붙는다. 무겁다. 골목에서 남자가 혼잣말을 했다. 오늘은 조용하네.`,
        ng:`끌어올린 숨이 반에서 걸렸다.<br><br>담장에 오르다 발이 병 조각에 걸렸다. 신발이 찢어지고 발등이 베였다. 담장 위에 엎드렸다.<br>남자가 담뱃불을 이쪽으로 튕겼다. 불똥이 손등에 떨어졌다. 남자는 보지도 않았다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-26, mind:-10 } }
    ] },

  { at:'B', t:'밤 시장 — 맞춰 오는 발소리',
    x:`비 오는 밤 시장이다. 셔터가 다 내려왔다. 천막 끝에서 빗물이 줄줄 떨어진다.<br><br>
    뒤에서 발소리가 따라온다. 이쪽 걸음과 똑같은 박자다. 빨라지면 빨라진다. 가까워지지는 않는다. 늘 열다섯 걸음 뒤다.<br>
    가까워질 생각이 없는 발소리다. 어디로 모는 것이다.<br><br>
    걸음을 바꾸는 건 보법이다. 몰리는 데를 바꾸는 건 다른 공부다.`,
    o:[
      { l:'① 보법을 바꿔 박자를 끊는다.', k:'evade', dc:21,
        ok:`두 걸음 짧게, 한 걸음 길게, 반 걸음 비껴서. 박자를 셋으로 쪼갰다.<br><br>뒤의 발소리가 처음으로 엇갈렸다. 따라 하려다 박자를 놓쳤다. 열다섯 걸음이 스물이 되고 서른이 됐다.<br>그 틈에 천막 사이 좁은 통로로 꺾었다. 모는 쪽이 아니다.<br><br>통로 끝에서 돌아보니 시장 큰길 끝에 사람 셋이 서 있다. 이쪽이 몰려갈 자리였다. 셋이 같이 시계를 본다.`,
        ng:`박자를 쪼갰다. 뒤의 발소리도 쪼갰다. 똑같이.<br><br>보법을 바꾸는 박자까지 안다. 등이 서늘해서 뛰었다. 뛴 쪽이 저쪽이 몰던 쪽이었다.<br>큰길 끝에서 누가 어깨를 쳤다. 넘어졌다. 일어나 다른 데로 뛰었다. 어깨가 빠질 듯 아프다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-22, spirit:-14 } },
      { l:'② 천막 밑 빗물 뒤에 서서 먼저 보낸다.', k:'hide', dc:20,
        ok:`천막 밑 기둥 뒤에 섰다. 빗물이 천막 끝에서 커튼처럼 떨어진다. 그 뒤에 섰다.<br><br>발소리가 왔다. 이쪽 앞을 지났다. 멈추지 않는다. 이쪽 박자로 계속 걷는다. 이쪽이 없는데도.<br>발소리가 큰길 끝으로 갔다. 그쪽에서 누가 웃었다. 잡았다고 생각한 웃음이다.<br><br>박자만 따라오던 것이다. 이쪽이 빠져도 박자는 계속 걸었다.`,
        ng:`발소리가 이쪽 앞에서 멈췄다.<br><br>빗물 커튼 너머에 우산이 섰다. 우산 끝이 커튼을 갈랐다. 얼굴은 안 보인다. 우산 살 끝이 이쪽 뺨을 그었다.<br>밀치고 뛰었다. 뺨에서 피가 빗물과 같이 흘렀다. 우산은 그 자리에 그대로 섰다.`,
        win:{ exp:16, dream:2 }, lose:{ hp:-22, mind:-14 } },
      { l:'③ 내공을 다해 끝까지 달려 떼어 낸다.', k:'evade', dc:22, cost:{ qi:26 },
        doom:{ title:'막다른 골목', what:'막다른 골목에 몰렸습니다', dc:17, sec:55,
          text:`내공을 다리에 몰아 달렸다. 시장 끝까지. 발소리가 멀어진다. 된다.<br><br>시장 끝을 돌았다. 골목이다. 골목 끝이 벽이다. 벽에 새 페인트로 화살표가 그려져 있다. 이쪽을 가리킨다.<br>돌아섰다. 발소리가 골목 입구에 섰다. 이번에는 하나가 아니다. 우산 셋이 골목을 막았다.<br><br>내공은 아까 다 썼다. 다리가 떨린다.`,
          dieText:`빨리 달리면 떼어 낼 수 있다. 상대가 쫓을 때 이야기다.<br><br>저쪽은 쫓지 않았다. 기다렸다.<br>비가 그 골목 벽의 화살표를 씻어 낸다. 다음 날 아침에는 다시 그려져 있을 것이다.` },
        ok:`내공을 다리에 몰아 달렸다. 모는 쪽으로는 안 달렸다. 몰리는 쪽 반대, 담 너머로.<br><br>담 너머가 막혔는지 열렸는지 몰랐다. 모르니까 저쪽도 몰랐다. 담 셋을 넘었다. 발소리가 끊겼다.<br>넷째 담 위에서 보니 시장 끝 골목이 벽으로 막혀 있다. 벽에 화살표가 그려져 있다.<br><br>그쪽으로 갔으면 거기서 끝이었다.`,
        win:{ exp:25, dream:3 } }
    ] },

  { at:'B', t:'지붕 — 낡은 슬레이트',
    x:`낮은 지붕들이 이어진다. 낡은 슬레이트다. 비에 젖어 검다. 군데군데 금이 갔다.<br><br>
    아래 골목에서 손전등 둘이 위를 비춘다. 하나는 왼쪽, 하나는 오른쪽. 가운데로 모인다.<br>
    슬레이트는 사람 무게를 못 받는다. 이 지붕들은 누가 오르라고 만든 게 아니다.<br><br>
    무게를 다 싣지 않으면 된다. 얼마나 덜 싣느냐가 문제다.`,
    o:[
      { l:'① 지붕 위를 가볍게 달려 건넌다.', k:'evade', dc:21,
        doom:{ title:'꺼진 지붕', what:'지붕이 꺼져 아래로 떨어졌습니다', dc:17, sec:55,
          text:`슬레이트 위를 달렸다. 발이 닿는 순간 뗐다. 셋째 지붕까지 갔다.<br><br>넷째 지붕 슬레이트가 다른 소리를 냈다. 속이 빈 소리. 발이 떨어지기 전에 판이 먼저 깨졌다.<br>몸이 지붕 아래로 빠졌다. 부러진 각목에 옷이 걸렸다. 반쯤 매달렸다. 아래는 캄캄한 방이다. 방 안에서 손전등이 켜졌다. 위를 비춘다.<br><br>손전등이 하나 더 켜졌다. 그 방 안에서.`,
          dieText:`다 싣지 않으면 된다. 지붕 속이 이미 비어 있으면 덜 실어도 다 실은 것이다.<br><br>골목의 손전등 둘이 꺼졌다. 할 일이 끝났다.<br>지붕 구멍으로 비가 들어간다. 방 안에서는 아무 소리도 안 난다.` },
        ok:`슬레이트 위를 달렸다. 발이 닿는 순간 뗐다. 넷째 지붕에서 소리가 달랐다. 속이 빈 소리다.<br><br>그 지붕은 딛지 않았다. 처마 끝 홈통 위를 발끝으로 짚고 지났다. 홈통이 휘었다가 돌아왔다.<br>다섯째 지붕에서 내려섰다. 돌아보니 넷째 지붕 슬레이트 틈으로 불빛이 하나 샌다. 안에서 기다리던 것이다.<br><br>골목의 손전등 둘은 끝내 가운데로 못 모였다.`,
        win:{ exp:25, dream:3 } },
      { l:'② 손전등이 엇갈리는 박자를 본다.', k:'sense', dc:20,
        ok:`손전등 둘이 움직이는 걸 봤다. 둘이 서로를 비추는 순간이 있다. 그때는 둘 다 눈이 부시다.<br><br>그 순간마다 한 지붕씩 건넜다. 서른을 세면 한 번 온다. 다섯 번에 다섯 지붕.<br>마지막 지붕 끝에 빗물 받는 함지박이 있었다. 물이 맑다. 한 모금 마시고 통에 담았다.<br><br>손전등 둘은 아직 서로를 비춘다. 둘 다 그게 일인 줄 안다.`,
        ng:`셋째 순간이 오지 않았다. 손전등 하나가 박자를 바꿨다.<br><br>지붕 한가운데에서 빛을 맞았다. 그대로 엎드렸다. 배 밑에서 슬레이트가 금 가는 소리가 났다.<br>빛이 떠나고 기어서 건넜다. 깨진 모서리에 배가 길게 그어졌다.`,
        win:{ exp:16, item:'맑은 물' }, lose:{ hp:-26, mind:-12 } }
    ] },

  { at:'B', t:'철교 — 뒤에서 오는 기차',
    x:`강을 건너는 철교다. 사람 다니는 길이 없다. 침목 사이로 검은 강이 보인다. 비에 불어 빠르다.<br><br>
    철교 저편이 나가는 길이다. 이편 끝은 손전등 든 것들이 막았다. 다리로 들어오지는 않는다.<br>
    선로가 웅 하고 운다. 발바닥이 먼저 안다. 뒤에서 기차가 온다. 철교 길이는 이백 걸음이다.<br><br>
    침목은 한 걸음에 둘. 이백 걸음이면 침목 사백 개다.`,
    o:[
      { l:'① 내공을 끌어올려 침목을 달린다.', k:'evade', dc:21, cost:{ qi:25 },
        ok:`숨을 끌어올려 다리에 몰았다. 침목 하나 건너 하나씩 디뎠다. 발이 닿는 시간을 반으로 줄였다.<br><br>뒤에서 전조등이 비친다. 이쪽 그림자가 앞으로 길게 늘어난다. 그림자 끝을 따라 달렸다. 그림자가 짧아진다. 기적이 귀 뒤에서 운다.<br>철교 끝에서 옆으로 몸을 던졌다. 기차가 등 뒤로 지나갔다. 바람이 등을 떠밀었다.<br><br>마지막 칸 문이 열려 있었다. 그 안에서 누가 이쪽을 내려다봤다. 손전등은 없다. 손가락으로 셋을 센다.`,
        ng:`백오십 걸음째에 숨이 끊겼다.<br><br>내공이 빠지자 다리가 무거워졌다. 침목을 헛디뎠다. 무릎이 침목 사이로 빠졌다. 강물 소리가 바로 아래다.<br>빼내고 달렸다. 끝에서 몸을 던졌다. 기차 바람에 둑을 굴렀다. 무릎이 펴지지 않는다.`,
        win:{ exp:22, dream:2 }, lose:{ hp:-30, mind:-12 } },
      { l:'② 철교 옆 점검 발판으로 내려가 버틴다.', k:'steady', dc:20,
        ok:`철교 옆구리에 점검용 발판이 달렸다. 쇠 그물이다. 내려가 섰다. 난간을 쥐었다.<br><br>기차가 머리 위로 지났다. 발판이 떨린다. 뼈까지 떨린다. 버텼다. 오래 걸렸다. 화물칸이었다.<br>기차가 지나가고 발판을 따라 건넜다. 발판은 철교 끝까지 이어져 있었다.<br><br>발판 끝에 누가 두고 간 보따리가 있다. 말린 고기와 젖은 지도. 지도에 이 철교가 동그라미 쳐져 있다.`,
        ng:`발판 그물이 녹슬어 있었다.<br><br>기차가 지날 때 그물 한 칸이 떨어져 나갔다. 한 발이 빠졌다. 난간을 쥔 손에 기차 떨림이 다 왔다. 손이 저절로 풀리려 한다.<br>안 놓았다. 기차가 지나간 뒤 손가락을 하나씩 펴야 했다.`,
        win:{ exp:16, item:'말린 고기' }, lose:{ hp:-24, spirit:-14 } }
    ] },

  { at:'B', t:'뒷문 복도 — 누르면 켜지는 바닥',
    x:`긴 복도 바닥에 네모난 판이 깔렸다. 밟으면 판이 손톱만큼 내려간다. 내려가면 어딘가에서 불이 켜진다.<br><br>
    복도 끝 문 너머에 뒷문이 있다. 그게 이쪽이 받은 쪽지다.<br>
    쪽지를 준 사람은 이 복도를 안 걸어 봤다. 걸어 봤으면 말했을 것이다.<br><br>
    판이 내려가는 건 무게 때문이다. 무게는 덜어 낼 수 있다.`,
    o:[
      { l:'① 판에 무게를 싣지 않고 지난다.', k:'evade', dc:21, wake:1,
        ok:`판 한가운데를 발끝으로 짚었다. 짚는 순간 다음 판으로. 판이 내려갈 틈을 안 줬다.<br><br>서른 판. 내려간 판이 없다. 천장의 붉은 등이 끝까지 안 켜졌다.<br>뒷문 앞에서 숨을 내쉬었다. 그제야 무게가 발로 돌아왔다. 판 하나가 손톱만큼 내려갔다. 등이 한 번 깜박였다. 문을 열고 나갔다.<br><br>무게를 덜어 내는 게 아니었다. 숨에 실어 두는 것이었다. 숨을 머금은 동안은 발이 가볍다. 처음 알았다.`,
        ng:`열아홉째 판이 다른 판보다 얕았다.<br><br>발끝만 짚었는데 내려갔다. 천장 등이 켜졌다. 벽에서 철창이 내려오기 시작했다.<br>남은 판을 그냥 달렸다. 철창 밑으로 굴러 빠졌다. 철창 끝이 등을 긁었다. 뒷문 밖까지 사이렌이 따라왔다.`,
        win:{ exp:22, dream:2 }, lose:{ hp:-26, mind:-12 } },
      { l:'② 이음매를 읽어 안 내려가는 판만 고른다.', k:'gaze', dc:20,
        ok:`이음매를 봤다. 대부분 먼지가 끼었다. 먼지가 없는 이음매가 있다. 자주 내려간 판이다.<br><br>먼지 낀 판만 디뎠다. 비스듬히, 지그재그로. 멀리 돌았다.<br>뒷문에 닿았다. 등은 한 번도 안 켜졌다.<br><br>나오며 돌아보니 먼지 낀 판만 이은 길이 보였다. 이 길을 아는 사람이 쪽지를 썼다면 길을 적었을 것이다. 안 적었다.`,
        ng:`먼지 낀 판 하나가 내려갔다. 그 먼지는 일부러 뿌린 것이었다.<br><br>천장 등이 켜졌다. 뒷문 쪽에서 빗장 걸리는 소리가 났다. 반대쪽 문으로 뛰었다.<br>문틀에 어깨를 찧었다. 쪽지를 구겨 버렸다. 버리고 나서야 쪽지 뒷면을 안 본 게 생각났다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-22, spirit:-14 } }
    ] },

  { at:'B', t:'폐차장 — 잠든 개 다섯',
    x:`폐차장 마당이다. 차체가 산처럼 쌓였다. 비가 쇳물 색으로 흐른다.<br><br>
    마당 한가운데 개 다섯 마리가 잔다. 사슬에 묶였다. 사슬이 마당을 가로질러 엉켰다. 하나만 건드려도 다섯이 깬다.<br>
    마당 끝 철문은 열려 있다. 열어 둔 것이다. 개가 지키니까.<br><br>
    개는 소리보다 땅 떨림에 깬다. 경신술사의 발은 땅을 안 떨게 한다.`,
    o:[
      { l:'① 사슬 사이 맨땅만 짚어 지난다.', k:'evade', dc:21,
        ok:`사슬이 놓인 모양을 봤다. 다섯 줄이 엉켰다. 엉킨 사이 맨땅이 손바닥만 하게 남았다.<br><br>손바닥만 한 땅을 발끝으로 짚었다. 짚을 때마다 숨을 멈췄다. 한 마리가 귀를 털었다. 멈췄다. 다시 짚었다.<br>철문까지 왔다. 개들은 그대로 잔다.<br><br>철문 기둥에 여섯째 사슬이 매여 있다. 끝에 묶인 것이 없다. 끝이 잘렸다. 새로 자른 자국이다.`,
        ng:`맨땅인 줄 알고 디딘 데가 물웅덩이였다.<br><br>찰박, 했다. 한 마리가 눈을 떴다. 나머지가 따라 떴다. 다섯이 한꺼번에 사슬을 끌며 일어섰다.<br>철문까지 달렸다. 사슬 끝에서 이빨이 바지를 물었다. 찢고 나왔다. 종아리에 이빨 자국이 났다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-28, mind:-10 } },
      { l:'② 내공으로 숨과 기척을 안으로 만다.', k:'hide', dc:21, cost:{ qi:22 },
        ok:`숨을 안으로 말았다. 몸에서 나가는 열까지 줄였다. 내공을 그렇게 쓰는 건 오래 못 한다.<br><br>개들 사이를 그냥 걸었다. 사슬 위로도 걸었다. 사슬이 울지 않을 만큼만 실었다. 개 코가 이쪽으로 벌름거렸다. 냄새 없는 것이 지나간다.<br>철문을 나섰다. 내공을 풀었다. 숨이 한꺼번에 터져 나왔다.<br><br>그 소리에 한 마리가 깼다. 짖지 않았다. 철문 쪽을 오래 봤다.`,
        ng:`숨을 말다가 기침이 났다.<br><br>다섯이 동시에 깼다. 짖지도 않고 달려왔다. 사슬 끝까지. 사슬이 팽팽해졌다. 이쪽 발끝 반 뼘 앞에서.<br>뒷걸음으로 빠졌다. 한 놈 사슬이 다른 놈 것보다 길었다. 손등을 물렸다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-26, spirit:-12 } },
      { l:'③ 차체 더미 위로 돌아간다.', k:'sense', dc:20,
        ok:`차체 더미를 타고 올랐다. 녹슨 지붕에서 지붕으로. 개들 머리 위다.<br><br>꼭대기 차 안에 누가 살던 흔적이 있다. 담요, 깡통, 약초 뭉치. 운전석 위에 사진이 붙었다. 강아지 다섯 마리.<br>약초를 챙겨 반대편으로 내려왔다.<br><br>사진 뒷면에 이름이 다섯. 맨 끝 이름에 줄이 그어졌다.`,
        ng:`차체 하나가 이쪽 무게에 기울었다.<br><br>더미가 한 번 출렁였다. 쇠 갈리는 소리가 마당을 울렸다. 개들이 깨어 더미 밑을 맴돈다.<br>꼭대기에서 오래 기다렸다. 비가 안 그친다. 몸이 다 식어 손가락이 안 움직였다.`,
        win:{ exp:16, item:'약초 뭉치' }, lose:{ mind:-14, spirit:-16 } }
    ] },

  { at:'B', t:'여관 — 열세 칸 나무 계단',
    x:`낡은 여관 계단이다. 나무 열세 칸. 칸마다 우는 소리가 다르다.<br><br>
    계단 아래 접수대에 노인이 앉았다. 눈을 감고 장부를 넘긴다. 계단이 울 때마다 장부에 줄을 하나 긋는다.<br>
    줄이 열셋이 되면 노인이 일어선다고 했다. 위층 누가 그렇게 말해 줬다. 그러고는 방문을 잠갔다.<br><br>
    장부에 줄이 벌써 넷 그어져 있다. 일행 중 누가 먼저 내려갔다.`,
    o:[
      { l:'① 난간 손잡이 위를 딛고 내려간다.', k:'evade', dc:21, wake:1,
        ok:`난간 손잡이 위에 발을 올렸다. 둥근 나무다. 발 옆날로 디뎠다. 미끄러지듯 내려갔다.<br><br>계단은 한 번도 안 울었다. 난간이 한 번 끽, 했다. 노인 손이 멈췄다. 펜 끝이 장부 위에 떠 있다. 이쪽도 멈췄다. 펜이 내려가지 않았다.<br>마지막 기둥에서 바닥으로 내렸다. 노인 옆을 지났다. 장부를 봤다. 넷.<br><br>둥근 데를 딛는 발이 평평한 데를 딛는 발과 똑같았다. 디딜 데가 좁아질수록 발이 편해진다.`,
        ng:`난간 가운데가 썩어 있었다.<br><br>발 옆날이 미끄러졌다. 셋째 칸에 떨어졌다. 셋째 칸이 크게 울었다. 다섯째, 여섯째까지 같이 울었다.<br>노인이 줄을 셋 그었다. 일곱. 펜을 쥔 손가락이 까딱거린다. 일행을 데리고 다른 계단을 찾았다. 발목이 부었다.`,
        win:{ exp:22, dream:2 }, lose:{ hp:-22, mind:-14 } },
      { l:'② 벽 쪽 끝만 짚어 울음을 줄인다.', k:'sense', dc:20,
        ok:`나무 계단은 가운데가 운다. 벽에 붙은 끝은 못이 박혀 덜 운다.<br><br>벽 쪽 끝만 짚었다. 열세 칸 중 둘이 작게 울었다. 노인이 줄을 둘 그었다. 여섯.<br>접수대 옆을 지날 때 노인이 눈을 감은 채 말했다. 손님, 우산 두고 가요. 접수대 옆에 우산이 있다. 이쪽 것이 아니다. 들고 나왔다.<br><br>밖에서 우산을 폈다. 안쪽 천에 일행 이름이 다 적혀 있다. 줄이 그어진 이름은 아직 없다.`,
        ng:`벽 쪽 끝을 짚었는데 그 칸만 못이 빠졌다.<br><br>판이 들리며 크게 울었다. 노인이 줄을 그었다. 그리고 눈을 떴다. 처음으로.<br>노인이 이쪽을 보고 장부를 봤다. 장부에 이쪽 이름을 썼다. 손이 떨리지 않았다. 뛰어서 나왔다. 정강이가 계단 모서리에 찍혔다.`,
        win:{ exp:16, dream:2 }, lose:{ hp:-22, spirit:-14 } }
    ] },

  { at:'B', t:'큰길 — 노란 신호',
    x:`큰길을 건너야 한다. 여섯 차로. 신호등이 다 노랗게 깜박인다. 아무도 서지 않는 시간이다.<br><br>
    차들이 비를 가르며 지나간다. 전조등 줄기 사이로 빗줄기가 하얗다. 경적이 없다. 다들 빠르고 조용하다.<br>
    건너편 골목 입구에 검은 차 한 대가 섰다. 그 차만 서 있다. 시동을 켠 채.<br><br>
    차와 차 사이는 늘 있다. 그 사이에 발을 놓는 박자가 있다.`,
    o:[
      { l:'① 차와 차 사이에 발을 놓으며 건넌다.', k:'evade', dc:21, wake:1,
        ok:`첫 차가 지났다. 그 꼬리에 붙어 한 걸음. 둘째 차 앞으로 반 걸음. 셋째 차 옆구리를 스치듯 비켰다.<br><br>여섯 차로를 그렇게 건넜다. 전조등이 몸을 훑고 지나간다. 하나도 안 선다. 다들 이쪽을 못 봤다. 봤으면 섰을 것이다. 섰으면 뒤차가 받았다.<br>건너편 인도에 섰다. 숨이 고르다.<br><br>차 사이를 셀 때 눈이 먼저 갔다. 눈이 간 데로 발이 따라갔다. 눈과 발 사이가 처음으로 붙었다.`,
        ng:`넷째 차로에서 차 한 대가 차선을 바꿨다. 이쪽으로.<br><br>비켰다. 사이드미러가 엉덩이를 쳤다. 빗길에 미끄러져 다섯째 차로까지 굴렀다. 다음 차가 코앞에서 꺾었다.<br>기어서 인도에 올라왔다. 허리 아래로 감각이 없다. 건너편의 검은 차가 천천히 출발했다.`,
        win:{ exp:22, dream:2 }, lose:{ hp:-30, mind:-12 } },
      { l:'② 내공을 실어 분리대 위를 달려 먼 데서 건넌다.', k:'evade', dc:20, cost:{ qi:22 },
        ok:`숨을 끌어올려 세 차로를 단숨에 건넜다. 중앙 분리대에 올랐다. 분리대 위는 한 뼘이다. 그 위로 달렸다.<br><br>검은 차가 이쪽을 따라 천천히 움직인다. 분리대 위로는 못 온다. 이백 걸음을 달렸다. 다음 교차로에서 나머지 세 차로를 건넜다.<br>검은 차는 빨간불에 섰다. 깜박이던 신호가 그 차 앞에서만 빨갛게 바뀌었다.<br><br>골목으로 들어왔다. 내공을 풀었다. 무릎이 한 번 꺾였다. 일어섰다.`,
        ng:`분리대 위가 젖은 페인트였다.<br><br>발이 미끄러졌다. 분리대에서 떨어져 차로 끝으로 굴렀다. 지나가던 차가 물웅덩이를 끼얹고 갔다. 숨이 끊겼다.<br>내공이 흩어졌다. 걸어서 건넜다. 검은 차가 옆에서 같은 속도로 따라왔다. 창문은 안 내려갔다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-24, spirit:-14 } }
    ] },

  { at:'B1', t:'3번 창고 — 기름 먹은 바닥',
    x:`창고 바닥에 기름이 깔렸다. 누가 일부러 쏟았다. 드럼통이 옆으로 누웠다. 아직 졸졸 흐른다.<br><br>
    창고 반대편 끝에 쪽문이 있다. 쪽문 앞에 양동이 하나와 대걸레. 청소부는 안 보인다. 대걸레 끝이 젖었다.<br>
    기름 위에서는 아무도 못 뛴다. 뛰려면 발에 무게를 실어야 하니까.<br><br>
    무게를 안 싣고 뛰는 것. 그게 이 공부다.`,
    o:[
      { l:'① 기름 위를 무게 없이 달린다.', k:'evade', dc:21, wake:1,
        ok:`발을 기름 위에 놓았다. 놓는 순간 뗐다. 미끄러질 틈이 없다. 미끄러지는 건 무게가 실린 다음이다.<br><br>스무 걸음을 달렸다. 기름이 밑창에만 묻었다. 쪽문 앞에 섰다.<br>대걸레 손잡이에 장갑 자국이 젖어 있다. 방금 놓은 것이다. 쪽문이 반쯤 열렸다. 열린 쪽이 바깥이다.<br><br>미끄러운 바닥이 무섭지 않았다. 디딜 때 바닥에 기대지 않는 버릇이 발에 붙었다.`,
        ng:`일곱째 걸음에서 발뒤꿈치가 닿았다.<br><br>그대로 미끄러져 드럼통에 처박혔다. 기름이 옷에 다 뱄다. 일어서려다 두 번 더 넘어졌다.<br>쪽문 쪽에서 성냥 긋는 소리가 났다. 불은 안 붙었다. 젖은 성냥이다. 다시 긋는 소리가 났다. 기어서 빠져나왔다.`,
        win:{ exp:22, dream:2 }, lose:{ hp:-26, mind:-14 } },
      { l:'② 소금 자루를 뜯어 길을 깔며 간다.', k:'fix', dc:20,
        ok:`벽에 쌓인 소금 자루를 뜯었다. 기름 위에 뿌렸다. 소금이 기름을 먹는다. 발이 잡힌다.<br><br>한 자루, 두 자루. 길이 났다. 일행이 그 위로 걸어왔다. 소금 덩이 하나는 품에 넣었다.<br>쪽문에 닿았다. 문이 반쯤 열려 있다.<br><br>뒤를 봤다. 소금 길 끝에 양동이가 놓여 있다. 아까는 쪽문 앞에 있던 양동이다.`,
        ng:`소금 뿌리는 소리가 컸다.<br><br>위층 난간에서 불빛이 켜졌다. 기름 위에 불빛이 번진다. 아직 불은 아니다.<br>일행을 재촉해 소금 길을 뛰었다. 길이 모자랐다. 마지막 다섯 걸음을 미끄러지며 갔다. 무릎과 손바닥이 다 까졌다.`,
        win:{ exp:16, item:'소금 덩이' }, lose:{ hp:-22, spirit:-14 } }
    ] },

  { at:'B1', t:'경매장 — 수조 위 판자',
    x:`경매장 바닥이 뜯겼다. 그 아래가 수조다. 흐린 바닷물이 고였다. 무언가 천천히 돈다.<br><br>
    수조 위로 판자가 걸쳤다. 생선 상자를 뜯어 이은 얇은 판이다. 못이 반쯤 빠졌다.<br>
    경매대 칠판에 숫자가 적혔다. 낙찰가가 아니라 시각이다. 04:30. 그 옆에 이쪽 무리 수만큼 동그라미.<br><br>
    판자가 받을 수 있는 무게가 얼마인지는 판자도 모른다.`,
    o:[
      { l:'① 판자마다 한 번씩만 짚고 건넌다.', k:'evade', dc:21,
        ok:`판자 하나에 한 번씩만 발을 댔다. 판자가 휘기 전에 뗐다.<br><br>수조 안에서 도는 것이 이쪽 그림자를 따라 돌기 시작했다. 판자 밑을 지날 때마다 물이 솟는다. 발목 높이까지. 발이 떠난 다음에.<br>건너편에 내렸다. 수조의 것이 수면 위로 등을 한 번 보였다. 생선이 아니다. 생선 비늘을 붙인 것이다.<br><br>칠판의 동그라미 하나에 누가 가위표를 쳤다. 이쪽 동그라미가 아니다.`,
        ng:`셋째 판자 못이 빠졌다.<br><br>판자가 기울었다. 발이 물에 잠겼다. 물속에서 무언가 발목을 스쳤다. 미끈하고 차갑다. 쥐려다 놓쳤다.<br>다음 판자로 굴렀다. 발목에 붉은 줄이 셋 그어졌다. 손가락 자국이다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-26, spirit:-14 } },
      { l:'② 내공을 실어 판자 둘씩 건너뛴다.', k:'evade', dc:20, cost:{ qi:24 },
        ok:`숨을 모아 다리에 실었다. 판자 둘을 건너 셋째에 내렸다. 내린 순간 또 뛰었다.<br><br>딛는 수가 반으로 줄었다. 수조 안의 것이 박자를 못 맞춘다. 물이 판자 하나 늦게 솟는다.<br>건너편 경매대 밑에 민물고기가 든 대야가 있다. 바다 수조 옆에 민물고기다. 어디서 가져와 숨겨 둔 것이다. 한 마리를 챙겼다.<br><br>대야에 붙은 쪽지. 『미끼』.`,
        ng:`둘째 도약에서 내공이 엇갈렸다.<br><br>판자에 너무 세게 내렸다. 판자가 부러졌다. 허리까지 물에 빠졌다. 물속에서 손이 셋 다가왔다. 판자 조각으로 쳐서 밀어냈다.<br>기어 나왔다. 몸에서 물이 안 빠지는 것처럼 무겁다. 한기가 오래 갔다.`,
        win:{ exp:18, item:'민물고기' }, lose:{ hp:-28, mind:-12 } },
      { l:'③ 벽 턱으로 돌아가 칠판의 동그라미를 지운다.', k:'luck', dc:21,
        ok:`수조를 돌아 벽을 따라갔다. 판자는 안 디뎠다. 벽 쪽 턱이 손가락 세 마디다. 발끝으로 갔다.<br><br>칠판의 동그라미를 소매로 지웠다. 하나씩. 다 지웠다.<br>수조 안에서 도는 것이 멈췄다. 이쪽이 아니라 다른 쪽으로 돌기 시작했다. 셀 것이 없어진 것이다.<br><br>지운 칠판에 분필 가루가 다시 모였다. 동그라미가 저절로 그려진다. 이쪽 무리보다 하나 많게.`,
        ng:`벽 턱이 미끄러웠다.<br><br>손으로 칠판을 짚었다. 분필 가루가 손바닥에 묻었다. 동그라미 하나가 손바닥 모양으로 뭉개졌다.<br>수조 안의 것이 그 순간 이쪽으로 달려들었다. 수조 벽이 울렸다. 턱에서 떨어질 뻔했다. 어깨를 벽에 찧었다. 손바닥 동그라미가 안 지워진다.`,
        win:{ exp:18, dream:3 }, lose:{ mind:-16, spirit:-16 } }
    ] },

  { at:'B1', t:'방파제 — 일곱째 파도',
    x:`방파제 위다. 바다 쪽에서 파도가 넘어온다. 일곱 번에 한 번 크게 온다. 큰 것은 방파제 위를 통째로 쓸고 간다.<br><br>
    끝까지 삼백 걸음. 끝에 바깥 길로 나가는 계단이 있다. 해무호가 그 옆에 대 있다. 05:10까지 이십 분.<br>
    방파제 위에 신발 한 짝이 떨어져 있다. 조금 더 가서 또 한 짝. 짝이 안 맞는다.<br><br>
    일곱을 세는 동안 몇 걸음을 갈 수 있는지가 전부다.`,
    o:[
      { l:'① 큰 파도 사이에 끝까지 달린다.', k:'evade', dc:22,
        doom:{ title:'일곱째 파도', what:'파도에 쓸려 갑니다', dc:17, sec:50,
          text:`큰 파도가 지나간 직후 달렸다. 하나, 둘, 셋. 작은 파도는 발목만 적신다. 넷, 다섯.<br><br>여섯째가 컸다. 일곱 번에 한 번이 아니었다. 바다가 박자를 바꿨다.<br>물이 허리를 쳤다. 발이 방파제에서 떴다. 몸이 바다 쪽으로 끌려간다. 손이 방파제 끝 쇠고리에 걸렸다. 손가락 셋.<br><br>다음 파도 오는 소리가 난다. 일곱째다.`,
          dieText:`일곱을 셌다. 바다는 세지 않았다.<br><br>방파제 위에 신발 한 짝이 더 떨어져 있다. 짝이 안 맞는 신발들 옆에.<br>해무호 갑판에서 누가 그 신발을 보고 장부에 줄을 긋는다.` },
        ok:`큰 파도가 지난 직후 달렸다. 하나, 둘, 셋. 다섯에서 바다 소리가 달라졌다. 박자가 당겨졌다.<br><br>쇠말뚝 뒤로 몸을 붙였다. 여섯째가 크게 넘어왔다. 말뚝을 끌어안았다. 물이 등을 밀고 지나갔다. 놓지 않았다.<br>물이 빠지는 순간 다시 달렸다. 일곱째가 오기 전에 계단에 닿았다.<br><br>계단 난간에 신발 한 짝이 걸려 있다. 짝이 안 맞던 신발들의 짝이다.`,
        win:{ exp:25, dream:3 } },
      { l:'② 떠밀려 온 밧줄로 일행을 이어 묶는다.', k:'bond', dc:20,
        ok:`방파제에 걸린 계류줄 토막을 주웠다. 일행 허리를 하나씩 이어 묶었다. 맨 앞은 이쪽이다.<br><br>파도가 올 때마다 다 같이 엎드렸다. 하나가 밀려도 나머지가 잡았다. 느리게 갔다. 이십 분 중 십오 분을 썼다.<br>계단에 닿았다. 밧줄을 풀었다. 매듭 하나가 이쪽이 묶은 매듭이 아니다.<br><br>세어 봤다. 밧줄에 묶였던 허리는 일행 수보다 하나 많았다. 그 하나는 계단에 안 올라왔다.`,
        ng:`큰 파도가 밧줄째 끌었다.<br><br>묶인 일행이 한꺼번에 미끄러졌다. 맨 앞에서 쇠말뚝을 잡고 버텼다. 밧줄이 허리를 조였다. 숨이 안 쉬어진다.<br>파도가 빠졌다. 다 있다. 허리에 밧줄 자국이 피멍으로 남았다. 시간이 많이 갔다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-26, mind:-14 } }
    ] },

  { at:'B1', t:'야적장 — 탐조등의 원',
    x:`야적장 바닥에 탐조등 원이 셋 돈다. 원과 원이 겹칠 때가 있다. 벌어질 때도 있다.<br><br>
    원 밖은 까맣다. 까만 데를 걸으면 된다. 까만 데는 계속 모양이 바뀐다.<br>
    야적장 한가운데 사람 하나가 서 있다. 탐조등이 그 위를 몇 번이고 지나간다. 움직이지 않는다. 손에 양동이를 들었다.<br><br>
    청소부다. 지나갈 길 한가운데 서 있다.`,
    o:[
      { l:'① 빛과 빛 사이 까만 틈을 달린다.', k:'evade', dc:21, wake:1,
        ok:`원 셋이 도는 박자를 봤다. 셋이 서로 멀어지는 순간 길이 하나 열린다. 열린 길은 숨 두 번이면 닫힌다.<br><br>숨 두 번에 달렸다. 원 하나가 등 뒤를 스쳤다. 둘째 틈에서 청소부 옆을 지났다. 팔 하나 거리다. 청소부는 고개를 안 돌렸다. 양동이에서 물이 한 방울 떨어졌다.<br>셋째 틈으로 야적장을 빠져나왔다.<br><br>길이 열리기 전에 발이 먼저 나갔다. 열릴 데를 미리 알았다. 보는 것보다 발이 빨라졌다.`,
        ng:`둘째 틈에서 원 하나가 방향을 바꿨다.<br><br>빛 한가운데 섰다. 온몸이 하얗다. 청소부가 그제야 고개를 돌렸다. 오래 봤다. 양동이를 내려놓았다.<br>달렸다. 컨테이너 사이로 몸을 던졌다. 모서리에 이마를 찧었다. 피가 눈에 들어갔다. 뒤에서 발소리는 없었다. 그게 더 무섭다.`,
        win:{ exp:22, dream:2 }, lose:{ hp:-24, spirit:-16 } },
      { l:'② 청소부를 오래 본다.', k:'gaze', dc:21,
        ok:`청소부를 오래 봤다. 움직이지 않는다. 탐조등이 지날 때마다 그림자가 돈다. 그런데 그림자가 한 박자 늦게 돈다.<br><br>사람이 아니다. 사람 크기 판에 우비를 걸었다. 진짜는 탐조등 탑 위에 있다. 등을 돌리는 손이 거기 있다.<br>탑에서 안 보이는 쪽, 판 그림자 뒤로 붙어서 지났다.<br><br>판 발치의 양동이는 진짜다. 물이 반쯤. 물이 붉지 않다. 그건 다행이다.`,
        ng:`오래 보는 사이 탐조등 하나가 이쪽에 멎었다.<br><br>멎은 채 안 움직였다. 탑 위에서 누가 이쪽을 보고 있다. 판이 아니라 그쪽이었다.<br>컨테이너 밑으로 굴러 들어갔다. 바닥 쇠붙이에 등이 찢어졌다. 빛이 컨테이너 밑을 오래 비췄다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-24, mind:-12 } }
    ] },

  { at:'B2', t:'소등 — 반질한 복도',
    x:`소등이다. 7층 복도에 비상등만 남았다. 바닥이 반질반질하다. 오늘 밤에도 왁스를 먹였다.<br><br>
    고무 바닥은 운다. 밟으면 끽, 하고. 맨발이면 덜 운다. 젖은 발이면 더 운다.<br>
    복도 끝 간호사실 유리창 너머에 하얀 모자 셋이 앉았다. 고개를 숙였다. 자는 것 같다. 셋이 똑같은 박자로 숨을 쉰다.<br><br>
    간호사실 앞을 지나야 계단이다. 계단은 잠겼다.`,
    o:[
      { l:'① 고무 바닥을 울리지 않고 지난다.', k:'evade', dc:21, wake:1,
        ok:`신발을 벗었다. 맨발을 마른 소매로 닦았다. 바닥에 닿는 면을 반으로 줄였다. 발 바깥 날로만 짚었다.<br><br>간호사실 앞을 지났다. 유리창 너머 모자 셋이 똑같이 숨을 쉰다. 이쪽 숨도 그 박자에 맞췄다. 넷이 같이 쉬는 숨은 하나로 들린다.<br>계단 문 앞에 섰다. 바닥이 한 번도 안 울었다.<br><br>남의 숨에 이쪽 숨을 묻는 법을 알았다. 발소리를 줄이는 것과 같은 일이었다.`,
        ng:`간호사실 앞 바닥에 물기가 있었다.<br><br>끽, 했다. 모자 셋이 한꺼번에 고개를 들었다. 얼굴이 없다. 모자 밑이 매끈하다.<br>세 모자가 이쪽을 향했다. 계단 반대쪽으로 뛰었다. 맨발이 바닥에 쩍쩍 붙었다. 발바닥 살갗이 벗겨졌다.`,
        win:{ exp:22, dream:2 }, lose:{ hp:-22, mind:-16 } },
      { l:'② 내공을 실어 벽 손잡이 난간 위로 간다.', k:'evade', dc:20, cost:{ qi:24 },
        ok:`복도 벽에 환자용 손잡이 난간이 붙었다. 쇠 파이프다. 숨을 끌어올려 그 위에 올라섰다.<br><br>파이프 위를 걸었다. 고무 바닥은 건드리지도 않았다. 간호사실 앞에서 몸을 낮췄다. 유리창에 비친 이쪽이 천장에 거꾸로 붙은 것처럼 보였다.<br>난간 끝에서 계단 문 앞에 내렸다. 내공을 풀었다. 바닥이 작게 울었다. 간호사실은 조용하다.<br><br>간호사실 벽 열쇠 걸이에 한 칸이 비었다. 이쪽은 아직 아무것도 안 가져갔다.`,
        ng:`파이프 이음매에 발이 걸렸다.<br><br>파이프가 벽에서 덜컹 울었다. 모자 하나가 일어섰다. 유리창 앞까지 왔다. 유리를 손톱으로 두드린다. 똑. 똑.<br>내려와 벽에 붙었다. 오래 숨을 참았다. 숨이 터질 때 내공도 같이 흩어졌다. 속이 뒤집혀 한동안 일어나지 못했다.`,
        win:{ exp:18, dream:2 }, lose:{ mind:-14, spirit:-18 } }
    ] },

  { at:'B2', t:'간호사실 — 열쇠 꾸러미',
    x:`간호사실 문이 열렸다. 모자 하나가 나와 복도 끝으로 걸어간다. 회진이다. 일곱 병실을 돌고 온다.<br><br>
    벽에 열쇠 꾸러미가 걸렸다. 계단 열쇠가 그 안에 있다. 꾸러미를 들면 열쇠끼리 부딪는다.<br>
    회진은 한 병실에 숨 열 번. 일곱 병실이면 일흔 번. 돌아오는 데 숨 스무 번.<br><br>
    다녀오는 데는 숨 열 번이면 된다. 꾸러미가 울면 회진이 거기서 멈춘다.`,
    o:[
      { l:'① 숨 열 번에 다녀온다.', k:'evade', dc:21,
        ok:`모자가 첫 병실에 들어가는 순간 움직였다. 간호사실까지 숨 셋. 꾸러미를 손바닥 전체로 감싸 쥐었다. 열쇠가 서로 닿지 못하게.<br><br>숨 다섯에 계단 열쇠만 뺐다. 꾸러미를 걸었다. 숨 일곱에 복도로 나왔다. 숨 열에 제자리로 돌아왔다.<br>모자가 첫 병실에서 나왔다. 둘째로 들어간다. 아무것도 모른다.<br><br>손바닥을 펴 보니 열쇠가 둘이다. 뺀 건 하나다. 하나는 언제 손에 들어왔는지 모른다. 엘리베이터 열쇠다.`,
        ng:`꾸러미를 감싸 쥐었는데 고리가 벽 못에 걸렸다.<br><br>짤랑, 했다. 회진하던 모자가 둘째 병실 앞에서 멈췄다. 돌아섰다. 걸어온다. 숨 스무 번이면 온다.<br>열쇠를 뺐다. 뛰었다. 간호사실 문이 닫히며 손가락을 찧었다. 손톱 하나가 들렸다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-22, mind:-14 } },
      { l:'② 간호사실 책상 밑에 숨어 돌아오길 기다린다.', k:'hide', dc:21,
        ok:`책상 밑에 들어갔다. 꾸러미는 안 건드렸다. 기다렸다.<br><br>모자가 돌아와 의자에 앉았다. 꾸러미를 내려 책상 위에 놓았다. 하나씩 센다. 다 셌다. 다시 벽에 걸고 고개를 숙였다. 숨이 길어졌다.<br>그때 꾸러미를 들었다. 못에서 고리만 빼서. 한 번도 안 울렸다. 계단 열쇠를 빼고 다시 걸었다.<br><br>모자 밑에서 숨이 멈췄다. 다시 이어졌다. 이쪽 숨과 같은 박자로.`,
        ng:`책상 밑이 좁았다. 무릎이 책상 다리를 건드렸다.<br><br>모자가 아래를 봤다. 모자 밑은 매끈하다. 그래도 보는 게 느껴진다. 손이 내려와 이쪽 머리카락을 쓸었다. 쓰다듬듯.<br>책상을 밀치고 뛰었다. 열쇠는 못 뺐다. 쓸린 자리가 오래 차가웠다.`,
        win:{ exp:18, dream:2 }, lose:{ mind:-16, spirit:-16 } }
    ] },

  { at:'B2', t:'투약 줄 — 짚는 손가락',
    x:`투약 시간이다. 환자들이 복도에 한 줄로 섰다. 무리도 환자복을 입고 그 줄에 섞였다.<br><br>
    줄 앞에 하얀 모자가 섰다. 종이컵을 건네며 센다. 손가락으로 이마를 하나씩 짚는다. 짚인 이마는 컵을 받는다.<br>
    줄 옆 벽에 비상계단 문이 있다. 아까 손에 넣은 열쇠가 맞는 문이다.<br><br>
    줄에서 빠지면 수가 준다. 수가 줄면 모자는 처음부터 다시 센다. 다시 세는 동안 문이 열려 있으면 안 된다.`,
    o:[
      { l:'① 세어지고, 빠지고, 다시 세기 전에 돌아온다.', k:'evade', dc:22,
        doom:{ title:'처치실', what:'처치실로 끌려갑니다', dc:18, sec:50,
          text:`이마를 짚였다. 컵을 받았다. 받자마자 줄에서 빠져 비상계단 문으로 갔다. 열쇠를 돌렸다. 문을 한 뼘 열었다. 일행에게 손짓했다.<br><br>줄로 돌아오는 데 반 걸음이 늦었다. 모자가 줄 끝까지 셌다. 하나 모자랐다. 다시 세기 시작했다. 이쪽 이마를 짚었다. 손가락이 떨어지지 않는다.<br>손가락이 이마를 누른다. 고개가 뒤로 꺾인다. 복도 끝에서 처치실 문이 열린다. 안이 하얗다.<br><br>손가락이 이쪽을 끈다. 이마 하나로.`,
          dieText:`빠지고 돌아오는 데 반 걸음. 그 반 걸음이 세어졌다.<br><br>모자가 줄을 다시 셌다. 이번에는 맞았다. 이쪽 자리에 다른 이마가 서 있었다.<br>처치실 문 위 불이 오래 켜져 있었다.` },
        ok:`이마를 짚였다. 컵을 받았다. 받자마자 줄에서 빠졌다. 비상계단 문을 소리 없이 한 뼘 열었다. 열쇠는 돌린 채 꽂아 뒀다.<br><br>모자가 줄 끝에 닿기 전에 돌아왔다. 줄 맨 끝에 섰다. 모자가 끝을 짚었다. 이쪽 이마다. 한 번 더 세어졌다. 수가 맞았다.<br>모자가 카트를 밀고 돌아섰다. 줄이 풀렸다. 일행이 하나씩 문으로 빠졌다.<br><br>손에 종이컵이 둘이다. 둘 다 바닥에 쏟았다. 쏟은 물이 하수구 쪽으로 안 가고 처치실 쪽으로 흘렀다.`,
        win:{ exp:25, dream:3 } },
      { l:'② 짚이기 직전마다 일행 하나씩 줄 뒤로 돌린다.', k:'bond', dc:21,
        ok:`이마가 짚이기 직전 일행 하나를 줄 뒤로 보냈다. 앞에서 셋을 세는 동안 뒤에서 하나가 줄 끝에 붙는다. 수는 그대로다.<br><br>한 바퀴. 두 바퀴. 일행이 줄 뒤를 돌아 비상계단 문 앞까지 하나씩 밀려났다. 문 앞에서 하나씩 빠졌다.<br>마지막에 이쪽이 빠졌다. 모자가 줄 끝을 셌다. 맞다고 했다.<br><br>남은 환자들은 아무도 그걸 말하지 않았다. 다들 같은 데를 본다. 비상계단 문을. 오래전부터 그랬다는 얼굴로.`,
        ng:`일행 하나가 컵을 받아 버렸다. 받고 마셨다.<br><br>마신 일행이 줄에서 안 움직인다. 밀어도 안 움직인다. 눈이 모자를 따라간다.<br>억지로 끌어냈다. 모자가 셌다. 하나 모자랐다. 다시 세는 사이 문으로 빠졌다. 끌려 나온 일행은 계단에서 한참 토했다. 이쪽 팔에도 손톱 자국이 남았다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-20, mind:-16 } },
      { l:'③ 내공으로 목을 닫아 마신 척만 한다.', k:'steady', dc:20, cost:{ qi:22 },
        ok:`컵을 받아 입에 털었다. 삼키지 않았다. 숨을 안으로 돌려 목을 닫았다. 내공이 목 안에서 물을 붙잡았다.<br><br>모자가 다음 이마로 갔다. 줄이 풀릴 때까지 숨을 안 쉬었다. 백을 셀 동안. 줄이 풀렸다.<br>비상계단 문 뒤에서 물을 뱉었다. 바닥에서 거품이 일었다. 한참 안 꺼진다.<br><br>목 안이 따끔하다. 머리는 맑다. 줄에 섰던 환자들은 눈이 하나같이 흐렸다.`,
        ng:`일흔을 셀 때 숨이 엇갈렸다.<br><br>물이 한 모금 넘어갔다. 머릿속이 흐려진다. 모자가 이쪽을 보고 웃는 것 같다. 모자 밑에 얼굴이 없는데.<br>일행이 팔을 끌고 문으로 갔다. 계단에서 토했다. 한참 동안 일행 이름이 생각나지 않았다.`,
        win:{ exp:18, dream:2, mind:6 }, lose:{ mind:-18, spirit:-14 } }
    ] },

  { at:'B2', t:'계단 문 — 숨 세 번',
    x:`6층으로 내려가는 계단 문은 카드로만 열린다. 카드는 직원 목에 걸렸다. 직원은 직원이 아니다.<br><br>
    하얀 가운 하나가 문 앞에 섰다. 카드를 댔다. 문이 열렸다. 다시 닫히기까지 숨 세 번.<br>
    가운은 계단을 내려가며 하나, 둘, 셋을 센다. 셋에서 뒤를 돌아본다. 매번 그렇다.<br><br>
    숨 세 번 안에 그 등 뒤로 들어가야 한다. 돌아보기 전에, 안 보이는 데까지.`,
    o:[
      { l:'① 닫히는 문으로 따라 들어가 난간 바깥에 붙는다.', k:'evade', dc:21,
        ok:`문이 열렸다. 가운이 들어갔다. 숨 하나에 문틈으로 들었다. 숨 둘에 난간 바깥쪽으로 몸을 넘겨 매달렸다.<br><br>셋. 가운이 돌아봤다. 문과 계단을 봤다. 비었다. 난간 바깥은 안 본다.<br>가운이 내려간다. 이쪽은 난간 바깥을 타고 한 층 아래로 미끄러졌다. 가운보다 먼저 6층 층계참에 섰다.<br><br>6층 문에 종이가 붙었다. 『7층 인원 이상 없음』. 오늘 날짜다. 적힌 시각은 내일 아침이다.`,
        ng:`숨 둘에서 문이 닫히기 시작했다. 생각보다 빨랐다.<br><br>문에 어깨가 끼었다. 빼냈다. 닫히는 소리가 컸다. 셋. 가운이 돌아봤다. 이쪽을 봤다.<br>가운이 웃었다. 카드를 다시 댔다. 문이 열렸다. 오라는 것이다. 7층 쪽으로 뛰어 돌아갔다. 어깨가 퉁퉁 부었다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-24, mind:-14 } },
      { l:'② 일행에게 반대편에서 소리를 내게 한다.', k:'bond', dc:20,
        ok:`일행 하나에게 손짓했다. 복도 반대편 끝에서 카트를 넘어뜨리게.<br><br>쾅. 가운이 문 앞에서 돌아섰다. 카드는 이미 대 놓았다. 문이 열려 있다. 그 사이로 들어갔다. 숨 셋. 층계참 그늘에 붙었다.<br>가운이 소리 쪽으로 걸어갔다. 문이 닫혔다. 이쪽은 안쪽이다. 일행은 바깥이다.<br><br>안쪽에 열림 단추가 있다. 눌렀다. 일행이 들어왔다. 카트를 넘어뜨린 일행이 마지막이다. 그 손에 하얀 가운 단추 하나가 쥐여 있었다.`,
        ng:`카트 넘어지는 소리에 가운이 안 돌아봤다.<br><br>대신 문 쪽의 이쪽을 봤다. 카트 소리는 매일 듣는 것이다. 이쪽 같은 것도.<br>가운이 손을 뻗었다. 뿌리쳤다. 손톱이 목덜미를 그었다. 복도로 다시 도망쳤다. 목에서 피가 한참 났다.`,
        win:{ exp:16, dream:2 }, lose:{ hp:-22, spirit:-16 } }
    ] },

  { at:'B3', t:'식당칸 — 쟁반 든 종업원',
    x:`식당칸 통로가 좁다. 식탁마다 손님이 앉았다. 다들 같은 수프를 먹는다. 숟가락 소리가 똑같은 박자다.<br><br>
    통로 저편에서 종업원이 쟁반을 들고 온다. 얼굴이 아까와 다르다. 쟁반 위에 잔 일곱. 가득 찼다. 한 방울도 안 흘린다. 기차가 이렇게 흔들리는데.<br>
    통로는 둘이 비킬 너비가 안 된다. 스치면 잔이 흔들린다. 잔이 흔들리면 다들 돌아볼 것이다.<br><br>
    흔들리는 바닥에서 안 흔들리는 걸음. 저것이 하는 걸 이쪽이 못 할 리 없다.`,
    o:[
      { l:'① 흔들림에 맞춰 종업원 곁을 스치지 않고 지난다.', k:'evade', dc:21, wake:1,
        ok:`기차가 오른쪽으로 기울 때 몸을 왼쪽에 실었다. 기울어진 만큼 통로가 넓어졌다. 그 틈으로 몸을 틀었다.<br><br>종업원과 이쪽 사이가 종이 한 장이다. 잔 일곱이 하나도 안 떨렸다. 종업원이 지나가며 고개를 숙였다. 이쪽도 숙였다. 둘 다 걸음을 안 멈췄다.<br>식당칸 끝 문에 닿았다. 숟가락 박자가 그대로다.<br><br>바닥이 흔들리는 박자가 걸음 안으로 들어왔다. 발이 바닥보다 먼저 기울었다.`,
        ng:`기차가 한 번 더 기울었다. 생각보다 깊게.<br><br>어깨가 쟁반 끝을 스쳤다. 잔 하나가 흔들렸다. 한 방울이 넘쳤다. 숟가락 소리가 다 멎었다. 손님 전부가 이쪽을 돌아봤다. 다 같은 얼굴이다.<br>뛰어서 문을 열었다. 등 뒤에서 숟가락 소리가 다시 났다. 빠르게. 손등에 넘친 한 방울이 데인 것처럼 뜨겁다.`,
        win:{ exp:22, dream:2 }, lose:{ hp:-20, spirit:-18 } },
      { l:'② 주방을 가로질러 돌아간다.', k:'sense', dc:20,
        ok:`옆 주방 문으로 들어갔다. 도마 위에 썰다 만 산나물. 냄비에서 수프가 끓는다. 아무도 없다.<br><br>주방을 가로질러 반대편 문으로 나왔다. 종업원은 통로를 지나 뒤 칸으로 갔다.<br>나오면서 산나물을 한 줌 쥐었다. 수프와 다른 냄새가 난다. 이것만 진짜다.<br><br>냄비를 돌아봤다. 수프 위에 얼굴 모양 거품이 하나 떴다가 꺼졌다.`,
        ng:`주방 문을 열자 칼 소리가 멈췄다. 아무도 없는데.<br><br>도마 위 칼이 손잡이를 이쪽으로 돌렸다. 쥐라는 것처럼. 안 쥐었다. 반대편 문으로 뛰었다.<br>문을 나서는데 칼이 문틀에 박혔다. 귀 옆이다. 귓바퀴가 베였다.`,
        win:{ exp:16, item:'산나물' }, lose:{ hp:-22, mind:-14 } }
    ] },

  { at:'B3', t:'객차 사이 — 떼어 간 발판',
    x:`6호차와 5호차 사이 발판이 없다. 누가 떼어 갔다. 연결 고리만 남았다. 그 아래로 침목이 흐른다.<br><br>
    틈은 두 걸음 반. 뛰면 넘는다. 기차가 안 흔들리면.<br>
    건너편 문에는 손잡이가 없다. 안에서 열어 줘야 한다. 유리 너머로 일행 하나가 손을 흔든다. 일행은 전부 이쪽에 있다.<br><br>
    경신술사는 발이 땅에 닿는 시간을 줄인다. 오늘은 닿을 땅이 없다.`,
    o:[
      { l:'① 연결 고리를 한 번 딛고 건너뛴다.', k:'evade', dc:22,
        doom:{ title:'연결 고리', what:'객차 사이로 빠졌습니다', dc:18, sec:45,
          text:`연결 고리를 디뎠다. 한 번. 그 힘으로 건너편으로 뛰었다.<br><br>건너편 문이 안 열렸다. 유리 너머 일행 얼굴이 웃는다. 손잡이 없는 문에 몸이 부딪쳤다. 튕겼다.<br>발이 연결 고리 옆으로 빠졌다. 허리까지 객차 사이로 들어갔다. 침목이 신발 끝을 친다. 연결 쇠사슬에 팔을 감았다.<br><br>유리 너머 얼굴이 문에 이마를 댄다. 기다린다.`,
          dieText:`닿는 시간은 줄일 수 있다. 닿을 데가 이쪽을 받아 줄 때.<br><br>5호차 문 유리에 얼굴이 하나 더 붙었다. 이쪽 얼굴이다.<br>안내 방송이 다음 역을 부른다. 내리실 문은 오른쪽입니다.` },
        ok:`연결 고리를 디뎠다. 디딘 힘으로 문이 아니라 문 위 지붕 턱을 잡았다. 문에는 안 부딪쳤다.<br><br>유리 너머 얼굴이 올려다본다. 문을 열어 줄 생각은 처음부터 없었다. 지붕 턱을 잡고 옆 창으로 돌아 들어갔다.<br>들어가 보니 문 앞에는 아무도 없다. 유리에 손자국만 남았다.<br><br>창으로 들어온 이쪽을 손님들이 쳐다본다. 하나가 일어나 자리를 비켜 줬다. 일행 얼굴이다. 일행은 전부 6호차에 있다.`,
        win:{ exp:25, dream:3 } },
      { l:'② 내공을 실어 쇠사슬을 손으로만 타고 건넌다.', k:'steady', dc:21, cost:{ qi:24 },
        ok:`연결 쇠사슬을 두 손으로 쥐었다. 숨을 끌어올려 몸무게를 손으로 옮겼다. 다리를 들었다.<br><br>손만으로 쇠사슬을 타고 건넜다. 아래로 침목이 흐른다. 바람이 다리를 당긴다. 무게를 숨에 실었다. 당겨 갈 무게가 없다.<br>건너편 발판 턱에 발을 걸었다. 문 바깥에 비상 손잡이가 하나 있다. 당겼다. 문이 열렸다.<br><br>유리 너머 얼굴은 없다. 문 안쪽 바닥에 젖은 장갑 하나. 손을 흔들던 모양 그대로다.`,
        ng:`쇠사슬이 기름에 젖어 있었다.<br><br>손이 미끄러졌다. 숨이 흩어졌다. 무게가 한꺼번에 돌아왔다. 다리가 침목에 끌렸다. 신발이 벗겨져 날아갔다.<br>쇠사슬을 팔로 감아 버텼다. 일행이 6호차 쪽에서 끌어 올렸다. 다시 처음부터다. 발목이 침목에 맞아 시퍼렇다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-30, mind:-12 } },
      { l:'③ 손 흔드는 얼굴을 오래 본다.', k:'gaze', dc:20,
        ok:`유리 너머 얼굴을 오래 봤다. 일행 얼굴이다. 그런데 손 흔드는 박자가 일행 것이 아니다. 일행은 손을 저렇게 안 흔든다.<br><br>그 얼굴 뒤 창에 5호차 통로가 비친다. 사람 넷이 서서 기다린다. 손님이 아니다. 문이 열리면 이쪽으로 올 것들이다.<br>건너지 않았다. 일행을 데리고 지붕 고리로 올라 위로 건넜다.<br><br>나중에 보니 5호차 문은 안쪽 손잡이도 없었다. 들어가는 칸이 아니라 기다리는 칸이었다.`,
        ng:`보는 사이 유리 너머 얼굴이 이쪽 얼굴로 바뀌었다.<br><br>눈을 뗄 수가 없다. 그 얼굴이 이쪽보다 먼저 웃는다. 따라 웃을 뻔했다.<br>일행이 어깨를 잡아 돌려세웠다. 머리가 아프다. 한동안 창에 비친 이쪽이 한 박자 늦게 움직이는 것 같았다.`,
        win:{ exp:18, dream:2 }, lose:{ mind:-16, spirit:-18 } }
    ] },

  { at:'B3', t:'침대칸 — 깨면 바뀌는 얼굴',
    x:`침대칸 통로 바닥은 나무다. 오래 밟혀서 가운데가 꺼졌다. 꺼진 데가 운다.<br><br>
    양옆 커튼 안에서 손님들이 잔다. 깨어난 손님은 얼굴이 바뀐다. 아까 하나가 깨는 걸 봤다. 눈을 뜨더니 일행 얼굴이 됐다.<br>
    통로는 서른 걸음. 깨어 있는 건 이쪽뿐이어야 한다.<br><br>
    가운데를 안 밟으면 덜 운다. 가운데밖에 디딜 데가 없다.`,
    o:[
      { l:'① 꺼진 데를 무게 없이 짚어 지난다.', k:'evade', dc:21,
        ok:`발끝으로 짚었다. 꺼진 판이 울기 전에 뗐다. 숨은 내쉬기만 했다. 들이쉬면 무게가 생긴다.<br><br>스무 걸음째에 커튼 하나가 흔들렸다. 손이 나와 커튼을 걷으려다 멈췄다. 다시 들어갔다. 잠꼬대다.<br>통로 끝에 닿았다. 판 하나 안 울었다.<br><br>뒤를 봤다. 커튼 하나 밑에 신발이 나와 있다. 이쪽 신발과 같은 신발이다. 이쪽은 신발을 신고 있다.`,
        ng:`열넷째 걸음에서 판이 울었다. 작게.<br><br>커튼 셋이 동시에 걷혔다. 손님 셋이 눈을 떴다. 얼굴이 바뀌는 데 숨 한 번. 셋 다 이쪽 얼굴이 됐다.<br>세 이쪽이 같이 통로로 나왔다. 뛰어 빠져나왔다. 문을 닫다 손이 끼었다. 이쪽 손인지 저쪽 손인지 잠깐 헷갈렸다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-20, spirit:-20 } },
      { l:'② 내공으로 몸을 들어 천장 손잡이 봉을 탄다.', k:'evade', dc:20, cost:{ qi:22 },
        ok:`천장 쪽에 손잡이 봉이 길게 지난다. 숨을 끌어올려 봉에 매달렸다. 무릎을 봉에 걸었다.<br><br>봉을 따라 손을 옮겼다. 발은 바닥에 한 번도 안 닿았다. 커튼 위 틈으로 잠든 얼굴들이 보인다. 다 다른 얼굴이다. 아직은.<br>통로 끝에서 내렸다. 내공을 풀며 숨을 아주 천천히 뱉었다.<br><br>봉 끝 고리에 누가 꿀 한 줌을 싼 종이를 걸어 두었다. 종이에 『깨우지 마세요』.`,
        ng:`봉 이음매가 헐거웠다.<br><br>봉이 한쪽으로 처지며 쇠 소리를 냈다. 내공이 흩어졌다. 꺼진 판 위로 떨어졌다.<br>커튼이 줄줄이 걷혔다. 문까지 굴러가 빠져나왔다. 무릎과 팔꿈치가 다 깨졌다.`,
        win:{ exp:18, item:'꿀 한 줌' }, lose:{ hp:-28, mind:-12 } }
    ] },

  { at:'B3', t:'맨 앞 칸 — 지나가는 승강장',
    x:`맨 앞 칸 문이 열렸다. 내리는 문은 맨 앞에만. 열린 문으로 빗바람이 들이친다.<br><br>
    앞에 역 하나가 다가온다. 서지 않는 역이다. 승강장 불빛이 길게 늘어진다. 승강장은 오십 걸음 길이다.<br>
    시계는 04:40. 이 역 다음이 종착이다.<br><br>
    달리는 데서 내리면 땅에 닿자마자 같이 달려야 한다. 땅에 닿는 시간을 줄여 온 발이면 할 수 있다.`,
    o:[
      { l:'① 승강장에 내려 같이 달리며 속도를 버린다.', k:'evade', dc:22, wake:1,
        ok:`승강장 끝이 왔다. 뛰었다. 땅에 닿기 전에 다리가 먼저 달리고 있었다.<br><br>한 걸음에 열 걸음 거리가 지나갔다. 다음 걸음에 일곱. 다음에 다섯. 땅에 닿는 시간을 늘려 가며 속도를 버렸다. 서른 걸음 만에 섰다. 승강장 끝 열 걸음 전이다.<br>기차가 옆으로 지나갔다. 꼬리등이 빗속으로 멀어진다.<br><br>빨리 닿는 발이 천천히 닿는 법도 알았다. 빨리 가는 것과 멈추는 것이 같은 공부였다.`,
        ng:`첫 걸음이 너무 짧았다.<br><br>다리가 속도를 못 따라갔다. 앞으로 꼬꾸라졌다. 승강장을 굴렀다. 다섯 바퀴. 기둥에 등을 박고 멈췄다.<br>등에 감각이 없다. 기차가 지나가며 창마다 얼굴이 이쪽을 내다봤다. 다 같은 얼굴이다.`,
        win:{ exp:24, dream:3 }, lose:{ hp:-34, mind:-12 } },
      { l:'② 일행 손을 잡고 같이 뛰어내린다.', k:'bond', dc:21,
        ok:`일행 손을 잡았다. 셋을 셌다. 같이 뛰었다. 이쪽이 먼저 땅을 디뎌 일행 몫까지 속도를 받았다.<br><br>같이 달렸다. 일행이 넘어지려 하면 손을 당겼다. 이쪽 다리가 둘 몫을 했다. 마흔 걸음에 섰다.<br>뒤에서 나머지 일행도 뛰어내렸다. 다 섰다.<br><br>승강장 끝 벤치에 누가 앉아 있다. 역무원 모자. 이쪽을 보고 시계를 본다. 04:41. 고개를 끄덕이고 일어나 어둠 속으로 걸어갔다.`,
        ng:`일행이 한 박자 늦게 뛰었다.<br><br>손이 당겨졌다. 둘이 같이 꼬였다. 이쪽이 밑에 깔려 승강장을 미끄러졌다. 콘크리트가 등을 갈았다.<br>일행은 무사했다. 이쪽 등에서 난 피가 빗물에 섞여 승강장 끝까지 흘렀다.`,
        win:{ exp:18, dream:2, hp:8 }, lose:{ hp:-30, spirit:-12 } },
      { l:'③ 내공을 끌어올려 기둥을 차고 속도를 버린다.', k:'evade', dc:21, cost:{ qi:26 },
        ok:`숨을 끌어올려 다리에 몰았다. 첫 기둥이 지나가는 순간 뛰었다. 기둥을 발로 찼다. 기차의 속도를 기둥에 버렸다.<br><br>몸이 한 바퀴 돌았다. 승강장에 내렸다. 두 걸음 만에 섰다. 기둥에 이쪽 신발 자국이 그을렸다.<br>내공을 풀었다. 속이 한 번 뒤집혔다. 버텼다.<br><br>그을린 자국 옆에 오래된 자국이 하나 더 있다. 누가 전에 같은 걸 했다. 그 자국은 선로 쪽을 향해 있었다.`,
        ng:`찬 기둥이 젖어 있었다.<br><br>발이 미끄러졌다. 속도가 그대로 남았다. 승강장을 굴렀다. 벽에 부딪혀 멈췄다.<br>내공이 꼬여 피를 한 모금 토했다. 한동안 못 일어났다. 확성기가 다음 열차를 안내했다. 방금 그 열차였다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-32, mind:-14 } }
    ] }
]);

// ── 환영술사 (illusion) · 마력 ──────────────
kJob('illusion', 'B', [
  { at:'B', t:'골목 — 막힌 끝',
    x:`골목 끝이 벽이다. 벽 위에 철조망. 빗물이 가시마다 맺혔다.<br><br>
    골목 입구에 사람 둘이 섰다. 우산을 접었다. 접은 우산 끝으로 쓰레기통 뚜껑을 하나씩 들춘다. 서두르지 않는다.<br>
    환영술사는 먼저 보낸다. 이쪽과 똑같이 생긴 것을. 다만 보낼 데가 저 둘 사이밖에 없다.<br><br>
    쓰레기통이 셋 남았다. 이쪽은 넷째 뒤에 있다.`,
    o:[
      { l:'① 마력으로 이쪽 환영을 입구 밖으로 달리게 한다.', k:'evade', dc:21, cost:{ mana:22 }, wake:1,
        ok:`환영을 세웠다. 이쪽 외투, 이쪽 젖은 머리. 쓰레기통 뒤에서 튀어나가게 했다. 두 사람 사이로.<br><br>둘이 동시에 돌아섰다. 환영이 입구를 빠져나간다. 발밑에서 물이 튄다. 물 튀는 것까지는 안 넣었다. 넣지 않은 것이 보였다.<br>둘이 환영을 쫓아 뛰었다. 골목이 비었다. 이쪽은 걸어서 나왔다. 반대쪽으로.<br><br>빗물이 튀는 걸 손이 기억하고 있다가 혼자 넣었다. 이제 이쪽 환영은 젖는다.`,
        ng:`환영이 튀어나가는 순간 한 사람이 우산 끝을 휘둘렀다.<br><br>우산이 환영을 지나갔다. 환영이 흩어졌다. 둘이 서로 쳐다봤다. 그리고 넷째 쓰레기통을 봤다.<br>뚜껑이 들렸다. 밀치고 빠져나왔다. 우산 끝이 옆구리를 찔렀다. 피가 셔츠에 번졌다.`,
        win:{ exp:22, dream:2 }, lose:{ hp:-26, mind:-12 } },
      { l:'② 몸 위에 젖은 상자 더미 모양을 얹는다.', k:'hide', dc:21,
        ok:`마력은 아꼈다. 손에 남은 것으로 작은 것 하나만 했다. 이쪽 몸 위에 젖은 상자 더미 모양을 얹었다.<br><br>둘이 넷째 쓰레기통까지 왔다. 뚜껑을 들췄다. 비었다. 옆의 상자 더미를 우산 끝으로 쿡 찔렀다. 이쪽 어깨 위 허공이다. 상자 소리는 안 났다.<br>둘이 돌아갔다. 입구에서 하나가 말했다. 비 오는 날은 상자도 안 울리지.<br><br>그 말이 맞아서 살았다.`,
        ng:`상자 모양이 빗물에 일렁였다.<br><br>빗줄기가 상자 위에서 튀지 않고 그냥 지나갔다. 한 사람이 그걸 봤다. 우산 끝을 상자 한가운데로 밀어 넣었다.<br>이쪽 쇄골에 닿았다. 뛰쳐나왔다. 철조망을 넘다 손바닥이 다 찢어졌다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-28, spirit:-12 } }
    ] },

  { at:'B', t:'호텔 방 — 건너편의 반짝임',
    x:`호텔 방이다. 커튼이 반쯤 열렸다. 건너편 건물 꼭대기 창에서 불빛이 한 번 반짝였다. 렌즈다.<br><br>
    방문은 하나. 문까지 가려면 창 앞을 지나야 한다. 창 앞은 건너편에서 다 보인다.<br>
    건너편 창은 이 방만 본다. 사흘이고 나흘이고 기다릴 사람이다.<br><br>
    보는 사람에게 보이는 것을 바꾸는 게 이쪽 일이다.`,
    o:[
      { l:'① 몸을 숙이고 그냥 창 앞을 지난다.', k:'evade', dc:22,
        doom:{ title:'건너편 창', what:'건너편 창에서 겨눠졌습니다', dc:17, sec:50,
          text:`몸을 숙이고 창 앞으로 나섰다. 창틀보다 낮게.<br><br>창틀 아래 벽지에 작고 붉은 점이 앉았다. 이쪽 걸음을 따라온다. 점이 벽에서 바닥으로, 바닥에서 이쪽 등으로 옮겨 왔다.<br>엎드렸다. 점이 등 한가운데서 멈췄다. 기다린다. 이쪽이 움직이기를.<br><br>창밖에서 빗소리 말고는 아무 소리도 안 난다.`,
          dieText:`숙이면 안 보인다. 저쪽이 위에서 볼 때는 아니다.<br><br>카펫에 젖은 얼룩이 생겼다. 빗물은 아니다.<br>건너편 창에서 불빛이 한 번 더 반짝이고, 꺼졌다.` },
        ok:`몸을 숙이고 창 앞으로 나섰다. 창틀보다 낮게. 기었다.<br><br>창틀 아래 벽지에 작고 붉은 점이 앉았다. 이쪽보다 한 뼘 위다. 점이 머리 위를 지나 방 안쪽을 훑는다. 숙인 높이가 저쪽 눈보다 낮았다.<br>문까지 기어가 복도로 나왔다.<br><br>붉은 점은 아직 방 안을 훑는다. 침대 위, 의자 위. 이쪽이 앉았던 데만 골라서.`,
        win:{ exp:25, dream:3 } },
      { l:'② 마력으로 창 앞에 이쪽 환영을 세워 둔다.', k:'evade', dc:21, cost:{ mana:24 },
        ok:`창 앞에 이쪽 환영을 세웠다. 커튼을 잡고 밖을 보는 모양으로. 움직이지 않게.<br><br>건너편이 반짝였다. 유리에 작은 구멍이 났다. 환영 가슴께다. 환영은 그대로 서 있다. 무게가 없으니 쓰러질 줄도 모른다.<br>그 사이 문으로 나왔다. 복도에서 환영을 거뒀다.<br><br>건너편에서 다시 반짝였다. 구멍이 하나 더 났다. 저쪽도 이상한 걸 알았다. 알았으면 이제 올 것이다.`,
        ng:`환영을 세웠는데 커튼이 환영 몸을 지나 흔들렸다.<br><br>건너편이 그걸 봤다. 붉은 점이 환영을 지나 방 안을 훑었다. 이쪽 어깨에 앉았다. 몸을 던졌다.<br>유리가 깨졌다. 어깨를 스쳤다. 화끈하다. 복도로 굴러 나왔다. 어깨에서 피가 멎지 않는다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-32, mind:-12 } },
      { l:'③ 반짝임의 박자로 저쪽이 무엇인지 본다.', k:'gaze', dc:20,
        ok:`반짝임을 셌다. 일정하다. 렌즈가 안 움직인다. 고정된 것이다. 사람이 아니라 받침대 위 카메라다.<br><br>그러면 보는 사람은 거기 없다. 화면 앞에 있다. 화면은 먼 데 있다. 와서 쏠 사람은 늦게 온다.<br>창 앞을 걸어서 지났다. 천천히. 렌즈를 한 번 봤다.<br><br>복도로 나오니 엘리베이터가 올라오고 있다. 늦게 온다던 사람이 생각보다 빨리 왔다. 계단으로 갔다.`,
        ng:`보는 사이 반짝임의 박자가 바뀌었다.<br><br>사람이다. 카메라가 아니다. 붉은 점이 이쪽 이마에 앉았다. 앉자마자 엎드렸다. 등 뒤 벽에 구멍이 났다.<br>기어서 문으로 나왔다. 엎드릴 때 탁자 모서리에 턱을 찧었다. 이가 하나 흔들린다.`,
        win:{ exp:16, dream:2 }, lose:{ hp:-28, spirit:-14 } }
    ] },

  { at:'B', t:'엘리베이터 — 버튼을 다 누른 남자',
    x:`엘리베이터에 남자가 하나 탔다. 이쪽 다음으로. 버튼을 전부 눌렀다. 서는 층마다 문이 열린다.<br><br>
    남자는 이쪽을 안 본다. 문이 열릴 때마다 밖을 본다. 이쪽이 내리는 층을 기다린다.<br>
    이쪽이 내리면 그 층을 누군가에게 알릴 것이다. 손에 쥔 전화기가 켜져 있다.<br><br>
    환영은 내리고 이쪽은 남는다. 늘 하던 대로면 된다. 늘 하던 일은 늘 보는 사람에게 들킨다.`,
    o:[
      { l:'① 마력으로 환영을 내리게 하고 이쪽은 빈 구석이 된다.', k:'evade', dc:21, cost:{ mana:22 }, wake:1,
        ok:`9층에서 문이 열렸다. 환영을 내리게 했다. 이쪽 몸 위에는 빈 구석 모양을 얹었다.<br><br>남자가 전화기에 대고 말했다. 9층. 문이 닫혔다. 남자가 구석을 한 번 봤다. 빈 구석이다. 남자는 다음 층에서 내려 9층 계단 쪽으로 뛰었다.<br>이쪽은 1층까지 내려갔다.<br><br>밖에 나와서 손을 털었다. 남의 눈이 바로 옆에서 이쪽을 찾는 동안에도 숨이 안 흔들렸다. 들킬 자리에서 띄우는 환영이 손에 익었다.`,
        ng:`환영이 내렸다. 남자가 전화기를 귀에 대지 않았다.<br><br>대신 환영의 발밑을 봤다. 문턱에 빗물이 고였다. 환영은 그 물을 밟았는데 물이 안 튀었다. 남자가 천천히 구석으로 고개를 돌렸다.<br>남자가 비상 정지 버튼을 눌렀다. 칸이 덜컥 섰다. 문을 비틀어 열고 층 사이로 기어 나왔다. 팔꿈치가 다 까졌다.`,
        win:{ exp:22, dream:2 }, lose:{ hp:-24, mind:-14 } },
      { l:'② 남자를 오래 본다.', k:'gaze', dc:20,
        ok:`남자를 봤다. 젖은 외투. 젖은 구두. 그런데 우산이 말랐다. 접은 우산에 물방울이 하나도 없다.<br><br>이음매가 보인다. 우산이 환영이다. 남자는 그 우산을 들고 밖에 나간 적이 없다. 이 건물 안에서 계속 기다린 사람이다.<br>밖으로 안 나가고 지하로 내려갔다. 지하 주차장 출구로.<br><br>남자도 환영을 쓴다. 서툴게. 서툰 환영을 든 사람을 보면 누구한테 배웠는지가 궁금해진다.`,
        ng:`보다가 남자와 눈이 마주쳤다. 문에 비친 눈.<br><br>남자가 웃었다. 우산을 바닥에 놓았다. 우산이 사라졌다. 남자 손이 비었다. 그 빈손이 이쪽 손목을 잡았다.<br>문이 열렸을 때 뿌리치고 뛰었다. 손목에 손가락 자국이 시퍼렇다. 그 층은 내리려던 층이 아니었다.`,
        win:{ exp:18, dream:2 }, lose:{ mind:-14, spirit:-18 } }
    ] },

  { at:'B', t:'다리 밑 — 혼자 온다던 사람',
    x:`다리 밑이다. 비가 다리 위를 두드린다. 아래는 마른 데가 손바닥만 하다.<br><br>
    거래 상대가 왔다. 혼자 온다고 했다. 기둥 뒤에서 담배 연기가 넷 올라온다.<br>
    상대가 가방을 보자고 한다. 상대가 원하는 건 가방이 아니다. 처음부터 이쪽 무리다.<br><br>
    이쪽이 몇인지 상대는 정확히 안다. 그 숫자를 틀리게 하는 게 첫 일이다.`,
    o:[
      { l:'① 마력으로 무리 뒤마다 그림자를 하나씩 세운다.', k:'fix', dc:21, cost:{ mana:25 },
        ok:`무리 하나하나 뒤에 흐린 그림자를 세웠다. 비 사이로 보면 사람이다. 숫자가 두 배가 됐다.<br><br>상대가 세었다. 입술이 움직인다. 다시 세었다. 기둥 뒤로 손짓했다. 담배 불이 하나씩 꺼졌다. 계산이 안 맞는 싸움은 안 하는 사람들이다.<br>상대가 가방을 안 받고 물러갔다. 거래는 깨졌다. 다들 살아서 깨졌다.<br><br>빠져나오는 동안 그림자들이 맨 뒤를 지켰다. 거둘 때 하나가 조금 늦게 사라졌다.`,
        ng:`그림자들이 빗속에서 너무 똑같이 움직였다.<br><br>상대가 웃었다. 비에 안 젖는 사람은 셀 필요가 없다고 했다. 기둥 뒤에서 셋이 걸어 나왔다.<br>무리가 흩어져 뛰었다. 이쪽이 맨 뒤였다. 쇠파이프가 등을 쳤다. 숨이 한동안 안 돌아왔다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-30, mind:-12 } },
      { l:'② 가방 환영을 건네고 진짜는 강에 떨군다.', k:'luck', dc:21, cost:{ mana:22 },
        ok:`상대 손에 가방을 건넸다. 손에서 떠나는 순간 진짜 가방을 등 뒤로 빼 강에 떨어뜨렸다. 상대 손에 남은 건 가방 모양이다.<br><br>상대가 무게를 가늠했다. 무게가 없다. 얼굴이 굳기 전에 무리는 이미 기둥 사이로 흩어졌다.<br>뒤에서 상대가 가방을 열었다. 열자마자 사라졌다. 강에서 진짜 가방이 떠올라 하류로 흘러간다. 상대가 그쪽으로 뛰었다.<br><br>가방 안에 뭐가 들었는지 이쪽은 모른다. 상대는 아는 얼굴이었다.`,
        ng:`가방 환영에 무게를 못 넣었다.<br><br>상대 손이 손잡이를 쥐는 순간 손가락이 손잡이를 지나갔다. 상대가 이쪽 손목을 잡았다. 진짜 가방은 아직 이쪽 등 뒤에 있다.<br>가방으로 상대 얼굴을 치고 뛰었다. 기둥 뒤 셋이 쫓아왔다. 다리 위 계단까지 뛰었다. 정강이가 계단에 찍혔다.`,
        win:{ exp:18, dream:3 }, lose:{ hp:-26, spirit:-14 } },
      { l:'③ 기둥 넷의 연기를 센다.', k:'sense', dc:20,
        ok:`연기 넷을 봤다. 셋은 비에 눌려 낮게 퍼진다. 하나는 곧게 올라간다. 비가 오는데도. 그 기둥 뒤에는 사람이 아니라 연기만 있다.<br><br>그러면 셋이다. 그 빈 기둥 쪽이 빠질 길이다. 상대가 가방을 열라고 할 때 무리를 그쪽으로 보냈다. 하나씩, 말없이.<br>빈 기둥을 지나 둑 위로 올라왔다. 상대는 끝까지 가방만 봤다.<br><br>빈 기둥 뒤 땅에 담배 한 개비가 꽂혀 있었다. 아직 탄다. 누가 꽂아 둔 것이다. 이쪽이 그 기둥으로 갈 줄 알고.`,
        ng:`연기를 세는 사이 상대가 가방을 낚아챘다.<br><br>안 놓았다. 둘이 당겼다. 끈이 손바닥을 파고들었다. 기둥 뒤에서 하나가 나와 이쪽 무릎을 찼다.<br>가방을 놓고 굴렀다. 무리가 이쪽을 끌어 둑 위로 올렸다. 무릎이 안 굽혀진다.`,
        win:{ exp:16, dream:2 }, lose:{ hp:-28, mind:-12 } }
    ] },

  { at:'B', t:'상점가 — 마네킹 열둘',
    x:`상점가다. 셔터는 다 내려왔는데 진열창 불만 켜 놨다. 마네킹들이 비 오는 거리를 본다.<br><br>
    길 양끝에서 손전등이 온다. 두 무리다. 가운데서 만난다. 숨을 데는 진열창 안뿐이다. 진열창 문 하나가 안 잠겼다.<br>
    마네킹은 열둘이다. 다들 같은 자세다. 고개를 조금 기울이고 손을 들었다.<br><br>
    가만히 서 있는 건 쉽다. 사람처럼 안 보이는 게 어렵다.`,
    o:[
      { l:'① 마력으로 몸 위에 마네킹 겉을 씌운다.', k:'hide', dc:21, cost:{ mana:24 },
        ok:`진열창 안으로 들어가 마네킹들 사이에 섰다. 같은 자세. 그 위에 매끈한 겉을 씌웠다. 숨 쉴 때 가슴이 움직이는 것까지 덮었다.<br><br>손전등이 진열창을 훑었다. 열셋. 아무도 안 셌다. 마네킹은 아무도 안 센다.<br>두 무리가 만나 담배를 나눠 피우고 갈라졌다. 진열창을 나왔다.<br><br>나오면서 마네킹을 다시 셌다. 열셋이다. 이쪽은 이미 밖에 있다.`,
        ng:`겉을 씌웠는데 빗물이 머리카락에서 떨어졌다.<br><br>마네킹은 안 젖는다. 손전등이 떨어지는 물방울에 멎었다. 빛이 이쪽 얼굴로 올라왔다.<br>진열창을 깨고 뛰쳐나왔다. 유리가 팔뚝을 길게 그었다. 피가 빗물에 섞여 번졌다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-26, mind:-14 } },
      { l:'② 진열창 유리에 비친 이쪽만 다른 데로 걷게 한다.', k:'evade', dc:21,
        ok:`진열창 유리마다 이쪽이 비친다. 그 비친 모양에 손을 댔다. 비친 이쪽만 다른 쪽으로 걷게 했다.<br><br>손전등이 유리에 비친 이쪽을 따라갔다. 유리에서 유리로. 거리 끝 진열창까지. 그 끝에서 비친 이쪽이 모퉁이를 돌았다. 손전등 무리가 모퉁이로 뛰었다.<br>이쪽은 진열창 그늘을 따라 반대로 걸었다.<br><br>거리 끝 진열창에 아직 비친 이쪽이 서 있다. 거둔 지 한참 됐는데.`,
        ng:`비친 이쪽을 움직이는데 진짜 이쪽도 따라 움직였다.<br><br>유리 속 이쪽이 밖으로 걷자 이쪽 발도 그쪽으로 걸었다. 손전등 앞으로.<br>빛에 맞고서야 멈췄다. 뛰었다. 뒤에서 무언가 날아와 뒤통수를 쳤다. 한동안 귀가 울렸다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-22, spirit:-16 } }
    ] },

  { at:'B', t:'계단 — 위아래 발소리',
    x:`계단으로 내려가야 한다. 아래 층계참에서 누가 올라온다. 위층에서도 누가 내려온다. 이쪽은 가운데다.<br><br>
    둘 다 발소리를 듣고 온다. 이쪽 발소리를 듣고.<br>
    보이는 것만 만들 수 있는 건 아니다. 소리를 만드는 건 한 번 해 봤다. 서툴렀다.<br><br>
    아래가 가까워진다. 일곱 칸 남았다.`,
    o:[
      { l:'① 마력으로 이쪽 발소리를 위층으로 올려 보낸다.', k:'evade', dc:21, cost:{ mana:22 }, wake:1,
        ok:`소리를 짰다. 이쪽 구두 소리. 이쪽 박자. 위로 올라가게 놓았다.<br><br>아래에서 오던 발소리가 빨라졌다. 이쪽을 지나쳐 위로 뛰었다. 바로 옆을. 층계참 모퉁이 그늘에 붙은 이쪽을 못 봤다. 위에서 내려오던 것과 둘이 부딪쳤다. 욕이 나왔다.<br>그 사이 아래로 내려갔다.<br><br>젖은 밑창이 계단에 붙었다 떨어지는 소리까지 들렸다. 그건 짜 넣은 기억이 없다. 소리도 이제 혼자 젖는다.`,
        ng:`소리가 이쪽 귀에만 크게 들렸다. 위로 안 갔다.<br><br>아래에서 오던 것이 모퉁이를 돌았다. 마주쳤다. 서로 놀랐다. 저쪽이 먼저 놀람을 끝냈다.<br>밀쳤다. 저쪽도 밀었다. 계단을 다섯 칸 굴렀다. 일어나 아래로 뛰었다. 허리가 계단 모서리에 찍혔다.`,
        win:{ exp:22, dream:2 }, lose:{ hp:-26, mind:-12 } },
      { l:'② 층계참 창밖 차양으로 나가 둘을 보낸다.', k:'hide', dc:21,
        ok:`층계참 창을 열고 나가 차양에 섰다. 창을 닫았다. 유리에 이쪽 대신 빈 계단을 얹어 뒀다. 작은 것이다.<br><br>둘이 층계참에서 만났다. 서로 봤다. 창도 봤다. 빈 계단이 비친다. 둘이 같이 아래로 내려갔다. 서로를 같은 편이라 생각하는 얼굴로.<br>창으로 다시 들어왔다. 위로 갔다. 옥상을 건너 옆 건물 계단으로 내려왔다.<br><br>차양에 선 동안 비가 등을 다 적셨다. 그동안 유리 속 빈 계단은 한 번도 안 흔들렸다.`,
        ng:`창이 안 열렸다. 칠이 굳었다.<br><br>밀다가 유리가 덜컹 울었다. 둘이 동시에 뛰어왔다. 창을 깨고 차양으로 나갔다. 차양이 이쪽 무게에 꺾였다.<br>한 층 아래 차양에 떨어졌다. 깨진 유리 조각이 목덜미에 박혔다. 빼느라 손이 피투성이가 됐다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-28, spirit:-12 } }
    ] },

  { at:'B', t:'주차 빌딩 4층 — 전조등',
    x:`주차 빌딩 4층이다. 차는 몇 대 없다. 기둥만 많다.<br><br>
    경사로 아래에서 차 한 대가 올라왔다. 전조등을 켰다. 천천히 돈다. 전조등이 기둥을 하나하나 비춘다. 기둥 뒤에 사람이 있으면 차가 그쪽으로 꺾는다. 아까 한 번 봤다.<br>
    엔진 소리가 낮다. 오래 기다릴 수 있는 엔진이다.<br><br>
    전조등 빛은 환영이 제일 잘 서는 빛이다. 세고, 한쪽에서만 온다.`,
    o:[
      { l:'① 마력으로 전조등 앞에 이쪽 환영을 세워 달아나게 한다.', k:'evade', dc:22, cost:{ mana:25 },
        doom:{ title:'전조등', what:'차에 받혔습니다', dc:17, sec:50,
          text:`전조등 앞 스무 걸음에 이쪽 환영을 세웠다. 뛰게 했다. 차가 엔진을 높였다. 환영 쪽으로 꺾었다.<br><br>차가 환영을 지나가더니 그대로 섰다. 운전석 창이 내려갔다. 운전하는 사람이 환영이 흩어진 자리를 봤다. 그리고 빛이 닿지 않는 반대쪽, 이쪽을 봤다.<br>차가 후진으로 돌았다. 전조등이 이쪽에 꽂혔다. 기둥과 차 사이가 좁다. 엔진이 운다.<br><br>기둥과 범퍼 사이가 줄어든다.`,
          dieText:`전조등 빛에서 환영은 잘 선다. 빛을 보낸 쪽도 그 빛 끝을 안다.<br><br>엔진 소리가 경사로를 내려간다.<br>4층 바닥에 타이어 자국 두 줄이 기둥 앞에서 끝난다.` },
        ok:`전조등 앞 스무 걸음에 이쪽 환영을 세웠다. 뛰게 했다. 차가 엔진을 높였다. 환영 쪽으로 꺾었다.<br><br>차가 환영을 지나갔다. 지나간 자리에 벽이 있었다. 환영은 벽 앞에 세웠다. 차가 벽을 들이받았다. 경적이 길게 울다 멎었다.<br>기둥 뒤에서 나와 계단으로 갔다. 운전석은 안 돌아봤다.<br><br>계단 문을 열 때 경적이 한 번 더 짧게 울었다. 누가 핸들에 기댔다가 고개를 든 것이다.`,
        win:{ exp:25, dream:3 } },
      { l:'② 기둥 그림자를 한 뼘 늘려 그 안에 든다.', k:'hide', dc:21,
        ok:`전조등이 기둥을 비추면 그림자가 뒤로 길게 늘어진다. 그 그림자를 한 뼘 더 늘렸다. 이쪽이 들어갈 만큼만.<br><br>차가 지나갔다. 기둥 뒤를 비췄다. 그림자뿐이다. 그림자가 조금 넓다. 운전하는 사람은 그림자 넓이를 재지 않는다.<br>차가 위층으로 올라갔다. 그 사이 계단으로 빠졌다.<br><br>계단 벽 안내판. 『5층 · 6층 만차』. 5층과 6층에는 차가 한 대도 없었다.`,
        ng:`그림자를 늘리는데 그림자가 빛보다 늦게 움직였다.<br><br>차가 지나가다 섰다. 그림자가 뒤늦게 기울었다. 전조등이 그 기둥으로 돌아왔다.<br>뛰었다. 차가 쫓았다. 계단 문으로 몸을 던졌다. 사이드미러가 엉덩이를 쳤다. 문이 닫히며 손가락을 찧었다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-30, mind:-12 } },
      { l:'③ 마력으로 차 앞에 기둥 하나를 더 세운다.', k:'luck', dc:21, cost:{ mana:22 },
        ok:`차가 지나갈 길 한가운데 기둥 하나를 세웠다. 다른 기둥들과 똑같이. 칠 벗겨진 데까지.<br><br>차가 그 기둥을 피하려고 꺾었다. 꺾은 쪽이 진짜 기둥이었다. 범퍼가 찌그러지며 섰다. 엔진이 멎었다.<br>운전석 문이 기둥에 막혀 안 열린다. 그 사이 계단으로 갔다.<br><br>세운 기둥을 거뒀다. 차 안에서 운전하던 사람이 빈 데를 오래 봤다. 핸들을 손가락으로 두드리며.`,
        ng:`세운 기둥이 전조등을 받고도 그림자를 안 만들었다.<br><br>운전하는 사람은 그림자를 봤다. 그림자 없는 기둥을 그냥 뚫고 왔다. 이쪽 앞에서 섰다. 범퍼가 무릎에 닿았다.<br>밀려 넘어졌다. 차 밑으로 굴러 반대편으로 기어 나왔다. 무릎이 퉁퉁 부었다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-30, spirit:-12 } }
    ] },

  { at:'B', t:'보일러실 — 손전등 하나',
    x:`지하 보일러실이다. 불이 다 나갔다. 깜깜하다. 배관에서 물이 떨어진다.<br><br>
    계단으로 손전등 하나가 내려온다. 찾는 사람은 그 손전등 하나로 이 방을 다 봐야 한다.<br>
    깜깜한 데서 환영은 쓸모가 없다. 빛이 없으면 아무것도 안 보이고, 환영도 안 보인다.<br><br>
    빛은 저쪽 손에 있다. 그러니까 저쪽이 비추는 데만 만들면 된다.`,
    o:[
      { l:'① 손전등 동그라미 안에만 빈 바닥을 띄운다.', k:'gaze', dc:21, wake:1,
        ok:`손전등이 움직이는 대로 따라갔다. 동그라미가 이쪽에 닿기 직전 그 안을 비웠다. 동그라미 안에서만. 밖은 손 안 댔다.<br><br>손전등이 이쪽 위를 세 번 지났다. 세 번 다 녹슨 바닥과 배관이 보였을 것이다. 저쪽이 보일러를 한 바퀴 돌고 계단으로 올라갔다.<br>보일러실을 나왔다. 손끝이 시리다. 마력은 동그라미 하나만큼만 썼다.<br><br>보는 쪽이 어디를 보는지만 알면 나머지는 안 만들어도 된다. 이제는 빛이 오는 방향이 먼저 보인다.`,
        ng:`동그라미를 따라가다 늦었다.<br><br>빛 가장자리에 신발 끝이 걸렸다. 손전등이 멈췄다. 동그라미가 신발에서 다리로, 다리에서 얼굴로 올라왔다.<br>배관을 걷어차 물을 터뜨렸다. 김이 방을 덮었다. 그 속으로 빠져나왔다. 김에 팔이 데었다.`,
        win:{ exp:22, dream:2 }, lose:{ hp:-24, mind:-14 } },
      { l:'② 배관을 차 김으로 빛을 막는다.', k:'break', dc:20,
        ok:`배관 이음매를 발로 찼다. 세 번. 김이 터졌다. 보일러실이 하얗게 찼다.<br><br>손전등 빛이 김에 막혀 한 뼘 앞에서 끝난다. 저쪽이 기침을 했다. 이쪽은 숨을 참고 벽을 따라 계단으로 갔다. 저쪽 옆을 지났다.<br>계단을 올라 문을 닫았다. 문 밑으로 김이 새어 나온다.<br><br>김 속에서 손전등이 한참 헤맸다. 빛만으로는 안 보이는 것도 있다.`,
        ng:`배관이 안 터졌다. 소리만 났다.<br><br>손전등이 소리 쪽을 비췄다. 둘째 발길질에 이음매가 터졌다. 김이 이쪽 얼굴로 먼저 왔다.<br>얼굴을 감싸고 계단으로 뛰었다. 손등과 볼이 화끈거린다. 손전등은 이쪽 등을 끝까지 비췄다.`,
        win:{ exp:16, dream:2 }, lose:{ hp:-28, mind:-10 } }
    ] },

  { at:'B1', t:'3번 창고 — 칠판의 다섯',
    x:`창고 칠판에 숫자가 있다. 다섯. 그 옆에 작게. 모자라면 채울 것.<br><br>
    구석 방수포 밑에 무언가 누워 있다. 셋이다. 발만 나왔다. 신발이 젖었다.<br>
    청소부는 숫자를 맞추러 온다. 다섯이 되면 일을 끝낸다. 안 되면 채운다. 이쪽 무리로.<br><br>
    방수포 밑에 둘이 더 누워 있으면 청소부의 일은 끝난다. 보기에는.`,
    o:[
      { l:'① 마력으로 방수포 밑에 둘을 더 눕혀 둔다.', k:'hide', dc:21, cost:{ mana:24 }, wake:1,
        ok:`방수포 끝을 들어 그 밑에 발 두 켤레를 더 놓았다. 젖은 신발까지. 방수포가 둘만큼 더 불룩하게.<br><br>셔터가 올라갔다. 고무장화가 들어왔다. 양동이를 내려놓고 방수포를 셌다. 하나, 둘, 셋, 넷, 다섯. 칠판 숫자 밑에 줄을 그었다. 양동이를 들고 나갔다.<br>무리가 상자 더미에서 나왔다. 아무도 말을 안 했다.<br><br>방수포 밑 발 두 켤레는 청소부가 나간 뒤에도 그대로였다. 무게가 없는데 무거워 보였다. 누워 있는 것의 무거움을 손이 알았다.`,
        ng:`발 두 켤레를 놓았다. 청소부가 방수포를 셌다. 다섯. 그리고 발끝을 장화로 툭 찼다.<br><br>장화가 환영 발을 지나 바닥을 찼다. 청소부가 멈췄다. 양동이를 내려놓았다. 상자 더미 쪽으로 걸어왔다. 천천히.<br>무리가 쪽문으로 흩어졌다. 대걸레 자루가 이쪽 어깨를 쳤다. 팔이 한동안 안 올라갔다.`,
        win:{ exp:22, dream:2 }, lose:{ hp:-26, spirit:-14 } },
      { l:'② 방수포 밑의 셋을 들여다본다.', k:'gaze', dc:20,
        ok:`방수포 끝을 들었다. 셋이다. 사람이 아니다. 소금 자루에 옷을 입혔다. 발은 신발에 모래를 채운 것이다.<br><br>누가 이미 한 번 속인 것이다. 그 셋 덕에 청소부는 둘만 더 찾는다.<br>자루 하나에서 소금 덩이를 빼 왔다. 하나 빠져도 모양은 그대로다.<br><br>자루에 입힌 옷 하나에 이름표가 달렸다. 이쪽보다 먼저 이 창고에 온 사람 이름이다. 그 사람은 지금 어디 있는지 모른다.`,
        ng:`방수포를 들자 밑에서 손이 나왔다.<br><br>셋 중 하나는 사람이었다. 아직. 손이 이쪽 손목을 잡았다. 살려 달라는 게 아니라 놓지 않으려는 힘이다.<br>떼어 냈다. 방수포를 덮었다. 손목에 손톱자국이 넷 남았다. 그 손은 다시 안 나왔다.`,
        win:{ exp:16, item:'소금 덩이' }, lose:{ mind:-16, spirit:-18 } }
    ] },

  { at:'B1', t:'냉동 창고 — 하얀 숨',
    x:`냉동 창고 안이다. 숨이 하얗게 나온다. 숨 하나하나가 보인다.<br><br>
    문 유리에 성에가 꼈다. 그 너머에서 고무장화가 서성인다. 들어올 생각은 없다. 문 앞에서 숨이 나오는 데를 본다.<br>
    무리 숨이 사람 수만큼 줄지어 피어오른다. 숨길 수 없는 게 숨이다.<br><br>
    환영은 차가운 데서 오래 못 간다. 마력도 같이 언다.`,
    o:[
      { l:'① 마력으로 무리의 숨을 덮어 지운다.', k:'hide', dc:21, cost:{ mana:25 },
        ok:`숨이 올라가는 데마다 빈 공기를 얹었다. 한 줄도 빼지 않고. 손이 시려서 마력이 끊길 것 같다. 숨을 길게 쉬라고 일행에게 손짓했다.<br><br>성에 너머 장화가 멈췄다. 유리에 얼굴을 댔다. 성에가 얼굴 모양으로 녹는다. 안을 본다. 숨이 하나도 없다. 빈 창고다.<br>장화가 문 앞을 떠났다. 무리가 반대편 활송구로 빠졌다.<br><br>유리에 녹은 얼굴 자국이 다시 얼지 않았다. 아직 그 너머에서 보는 것처럼.`,
        ng:`마지막 줄에서 마력이 얼었다.<br><br>숨 하나가 그대로 올라갔다. 장화가 그걸 봤다. 문이 열렸다. 찬 바람과 같이 대걸레 자루가 들어왔다.<br>활송구로 뛰었다. 얼음 바닥에 미끄러졌다. 무릎이 얼음에 붙었다가 떨어졌다. 살갗도 같이 떨어졌다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-24, mind:-14 } },
      { l:'② 반대편 성에 위에 달아나는 그림자를 띄운다.', k:'evade', dc:21,
        ok:`반대편 벽 유리에 그림자 하나를 띄웠다. 성에 너머로 사람이 뛰어가는 모양. 흐릿하게. 성에는 흐린 것을 더 사람처럼 보이게 한다.<br><br>장화가 그쪽으로 돌았다. 반대편 문으로 갔다. 그 사이 무리는 원래 문으로 나왔다. 장화가 비운 자리를 지났다.<br>문 옆에 양동이가 있다. 물이 얼었다. 얼음 밑에 열쇠 하나가 갇혔다.<br><br>열쇠는 두고 왔다. 얼음 깨는 소리가 더 컸을 것이다.`,
        ng:`그림자가 성에 위에서 번졌다. 사람이 아니라 얼룩이 됐다.<br><br>장화는 얼룩이 아니라 이쪽 쪽을 봤다. 유리 이쪽에 김이 서렸다. 이쪽 숨이다.<br>문이 열렸다. 대걸레가 휘둘렸다. 막다 팔뚝이 찢어졌다. 활송구로 굴러 빠졌다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-26, spirit:-12 } }
    ] },

  { at:'B1', t:'경매장 — 이름 붙은 칠판',
    x:`경매장 칠판에 이름이 적혔다. 이쪽 무리 이름이다. 이름 옆에 값이 붙었다. 다 다르다.<br><br>
    경매사 자리 위로 불 하나가 켜졌다. 그 아래 객석은 어둡다. 어둠 속에서 손이 하나씩 올라간다. 값을 부를 때마다.<br>
    경매사가 망치를 든다. 셋을 세면 낙찰이다. 낙찰된 이름은 지워진다.<br><br>
    경매사의 눈이 칠판에 있다. 칠판은 이쪽 가까이 있다.`,
    o:[
      { l:'① 마력으로 칠판 이름마다 낙찰을 띄운다.', k:'luck', dc:21, cost:{ mana:22 },
        ok:`칠판 이름마다 줄을 긋고 옆에 붉게 적었다. 낙찰. 경매사 글씨를 흉내 냈다.<br><br>경매사가 칠판을 돌아봤다. 망치를 내렸다. 다 끝났다는 얼굴이다. 객석의 손들이 내려갔다. 사람들이 일어나 나간다. 어둠 속에서 의자 끄는 소리.<br>무리가 그 소리 틈에 섞여 나왔다.<br><br>나오면서 객석을 봤다. 일어난 사람이 없다. 의자 끄는 소리만 났다. 의자들이 비었다.`,
        ng:`글씨를 흉내 냈는데 경매사 글씨가 아니었다.<br><br>경매사가 칠판을 보고 웃었다. 지우개로 이쪽 줄을 지웠다. 환영이 진짜 지우개에 지워졌다. 이쪽 이름 옆 값이 두 배가 됐다.<br>객석에서 손이 한꺼번에 올라갔다. 뛰었다. 어둠 속 손 하나가 발목을 잡았다. 차고 나왔다. 발목이 퉁퉁 부었다.`,
        win:{ exp:20, dream:3 }, lose:{ hp:-22, spirit:-16 } },
      { l:'② 경매사를 본다.', k:'gaze', dc:20,
        ok:`경매사를 봤다. 입이 움직이는데 소리가 반 박자 늦다. 이음매다.<br><br>경매사는 환영이다. 그 뒤 벽에 작은 구멍이 있다. 구멍 너머에서 누가 띄우고 있다. 객석은 손만 띄웠다.<br>벽을 돌아 사무실 문을 찾았다. 사무실이 비었다. 의자가 아직 따뜻하다. 책상 위에 말린 고기 한 봉지.<br><br>서랍에 칠판과 같은 이름 목록이 있다. 맨 끝에 한 줄 더. 띄우던 사람의 이름이다. 줄이 그어졌다.`,
        ng:`보는 사이 경매사가 망치를 내리쳤다. 셋을 다 안 셌다.<br><br>칠판 이름 하나가 지워졌다. 이쪽 이름은 아니다. 일행 하나가 바닥에 주저앉았다. 다친 데가 없는데 못 일어난다.<br>일행을 업고 나왔다. 업힌 일행이 계속 자기 이름을 물었다. 이쪽이 대신 대답했다. 목이 쉬었다.`,
        win:{ exp:18, item:'말린 고기' }, lose:{ mind:-16, spirit:-16 } }
    ] },

  { at:'B1', t:'방파제 끝 — 갑판의 양동이',
    x:`방파제 끝이다. 해무호가 대 있다. 갑판에 청소부가 서 있다. 양동이를 들었다. 05:00.<br><br>
    청소부는 배에 오르는 사람을 기다린다. 배에 안 오르는 사람은 방파제 끝 계단으로 간다. 계단도 청소부 눈에 다 보인다.<br>
    배 위 탐조등은 꺼졌다. 남은 빛은 갑판 등 하나. 그 아래 청소부 그림자가 길다.<br><br>
    청소부가 보는 건 하나다. 무리가 어디로 가는지.`,
    o:[
      { l:'① 마력으로 무리가 배에 오르는 모습을 띄운다.', k:'evade', dc:22, cost:{ mana:26 },
        doom:{ title:'양동이', what:'청소부에게 끌려갑니다', dc:18, sec:45,
          text:`무리가 줄지어 배에 오르는 모습을 띄웠다. 하나씩, 고개를 숙이고. 진짜 무리는 계단 쪽 어둠으로 보냈다. 이쪽이 맨 끝이다.<br><br>청소부가 환영들을 보고 고개를 끄덕였다. 그리고 양동이를 내려놓고 갑판 물웅덩이를 봤다. 물에 비친 것이 없다. 환영은 물에 안 비친다.<br>청소부가 계단을 봤다. 맨 끝 이쪽과 눈이 마주쳤다. 손이 뻗었다. 길다. 이쪽 외투 깃을 잡았다. 갑판 쪽으로 당긴다.<br><br>양동이 안에서 물이 출렁인다. 아직 맑다.`,
          dieText:`보이는 것은 만들었다. 비치는 것은 못 만들었다.<br><br>해무호가 고동을 두 번 울렸다. 실을 것을 다 실은 소리다.<br>방파제 끝 계단에 물 자국이 길게 났다. 금방 비에 씻긴다.` },
        ok:`무리가 줄지어 배에 오르는 모습을 띄웠다. 갑판 물웅덩이에도 비치게 넣었다. 비치는 데까지 넣는 건 처음이다. 머리가 깨질 것 같다.<br><br>청소부가 환영들을 봤다. 물에 비친 것도 봤다. 고개를 끄덕이고 환영들을 따라 선실로 내려갔다.<br>진짜 무리는 계단을 올라 바깥 길로 나왔다. 이쪽이 마지막이다.<br><br>선실 쪽에서 양동이 엎어지는 소리가 났다. 아무것도 안 든 소리였다.`,
        win:{ exp:25, dream:3 } },
      { l:'② 마력으로 무리 위에만 빗줄기를 두 겹 띄운다.', k:'hide', dc:21, cost:{ mana:22 },
        ok:`빗줄기를 두 겹으로 띄웠다. 무리 위로만. 진짜 비 위에 가짜 비. 그 안이 더 어둡게 보인다.<br><br>그 장막 아래로 계단까지 걸었다. 청소부가 방파제를 훑었다. 비가 유난히 굵은 데가 있다. 비 굵은 데를 오래 보는 사람은 없다.<br>계단을 올라 바깥 길로 나왔다. 장막을 거뒀다.<br><br>돌아봤다. 청소부는 아직 그 굵은 비 쪽을 본다. 비는 이제 다 같은 굵기다. 청소부가 양동이를 들고 계단 쪽으로 걸어오기 시작했다.`,
        ng:`가짜 비가 진짜 비와 박자가 안 맞았다.<br><br>청소부가 그걸 봤다. 굵은 비 쪽으로 걸어왔다. 무리가 계단으로 뛰었다. 이쪽이 맨 뒤였다.<br>대걸레가 날아와 등을 쳤다. 계단에 엎어졌다. 턱이 깨졌다. 일행이 끌어 올렸다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-30, mind:-12 } },
      { l:'③ 청소부 그림자 옆에 그림자 하나를 겹친다.', k:'luck', dc:21,
        ok:`갑판 등 아래 청소부 그림자 옆에 그림자 하나를 겹쳐 세웠다. 등 뒤에 누가 손을 들고 서 있는 모양으로.<br><br>청소부가 자기 그림자를 봤다. 둘이다. 돌아섰다. 아무도 없다. 다시 돌아섰다. 또 둘이다. 청소부가 처음으로 양동이를 놓쳤다.<br>그 사이 무리가 계단을 올랐다.<br><br>마지막으로 봤을 때 청소부는 등을 갑판 벽에 붙이고 서 있었다. 그림자가 하나뿐인지 확인하면서.`,
        ng:`겹친 그림자가 등 방향과 반대로 누웠다.<br><br>청소부가 그걸 봤다. 그림자 끝을 따라 시선이 이쪽까지 왔다. 그림자가 이쪽을 가리켰다.<br>청소부가 갑판에서 방파제로 뛰어내렸다. 소리 없이. 무리를 밀어 계단으로 올렸다. 이쪽 손등이 대걸레 쇠에 찢겼다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-22, spirit:-16 } }
    ] },

  { at:'B2', t:'점호 — 빈 침대 하나',
    x:`점호다. 손전등이 병실을 돈다. 침대마다 비추고 센다. 스물한 침대, 스물한 명.<br><br>
    무리가 숨은 병실의 침대 하나가 비었다. 원래 있던 환자가 없다. 무리는 침대 밑과 옷장 안에 있다.<br>
    손전등은 침대 위를 센다. 누워 있으면 하나. 비어 있으면 문이 다 잠긴다.<br><br>
    누워 있는 사람 하나. 무게도 숨도 없이 그냥 누워 있기만 하면 된다.`,
    o:[
      { l:'① 마력으로 빈 침대에 잠든 환자를 눕힌다.', k:'hide', dc:21, cost:{ mana:24 }, wake:1,
        ok:`빈 침대에 환자를 눕혔다. 이불을 목까지. 등을 문 쪽으로 돌리게. 얼굴은 안 보이게 했다. 얼굴에는 손전등이 오래 머문다.<br><br>손전등이 들어왔다. 첫 침대, 둘째, 셋째. 이불이 숨 쉬는 박자로 오르내린다. 그건 넣었다. 손전등이 지나갔다. 스물하나.<br>문이 닫혔다. 거두려는데 환자가 몸을 뒤척였다. 그건 안 넣었다.<br><br>이쪽이 잠깐 딴 데를 봐도 환자는 숨을 쉬었다. 띄워 놓고 손을 떼도 한동안 가는 환영이 처음 생겼다.`,
        ng:`이불이 오르내리는 박자를 넣었다. 너무 고르게.<br><br>손전등이 그 침대에서 멈췄다. 이불을 젖혔다. 손이 들어오자 환영이 흩어졌다.<br>손전등이 빈 침대를 셌다. 스물. 문 잠기는 소리가 복도를 따라 이어졌다. 침대 밑에서 숨을 참는 동안 손전등이 바닥까지 내려왔다. 이쪽 눈을 비췄다.`,
        win:{ exp:22, dream:3 }, lose:{ mind:-16, spirit:-16 } },
      { l:'② 손전등을 든 것을 본다.', k:'gaze', dc:20,
        ok:`손전등을 든 것을 봤다. 하얀 모자. 모자 아래 얼굴이 없다. 손전등이 눈 대신이다. 빛이 닿는 것만 안다.<br><br>그러면 빛 밖은 모른다. 일행 하나를 빈 침대에 눕혔다. 나머지는 빛이 안 가는 문 뒤 벽에 붙였다.<br>스물하나. 손전등이 나갔다.<br><br>누웠던 일행이 일어났다. 베개에 머리카락이 몇 올 남았다. 일행 머리카락보다 길다.`,
        ng:`보는 사이 손전등이 이쪽 얼굴에 닿았다.<br><br>빛이 이쪽을 셌다. 하나. 이쪽은 침대에 없다. 손전등이 이쪽과 침대를 번갈아 비췄다. 셈이 엉켰다.<br>문이 잠겼다. 열리는 데 반 시간이 걸렸다. 그동안 손전등이 문 유리 밖에서 이쪽만 비췄다. 눈을 감아도 밝았다.`,
        win:{ exp:16, dream:2, mind:6 }, lose:{ mind:-14, spirit:-18 } }
    ] },

  { at:'B2', t:'간호사실 — 화면 아홉',
    x:`간호사실 벽에 작은 화면이 아홉 개다. 복도, 병실, 계단 문. 하얀 모자가 그 앞에 앉아 화면을 본다.<br><br>
    이쪽은 화면 하나에 비칠 복도를 지나야 한다. 계단 문 화면에도.<br>
    환영은 눈을 속인다. 렌즈는 눈이 아니다. 렌즈가 본 것을 화면이 보여 주고, 화면을 눈이 본다.<br><br>
    속일 것은 렌즈가 아니다. 화면을 보는 눈이다.`,
    o:[
      { l:'① 마력으로 화면 위에 빈 복도를 덧띄운다.', k:'evade', dc:21, cost:{ mana:24 },
        ok:`유리창 너머에서 화면 하나를 봤다. 그 위에 빈 복도 모양을 덧띄웠다. 화면 크기에 맞춰. 손바닥만 하게.<br><br>복도를 걸었다. 화면 속 진짜 복도에는 이쪽이 걷는다. 그 위를 빈 복도가 덮었다. 모자는 빈 복도를 봤다.<br>계단 문 앞에서 덮개를 거뒀다. 그 순간 화면에 이쪽 등이 한 번 비쳤다. 모자가 고개를 들었을 때는 이미 문 안이다.<br><br>계단에서 숨을 돌렸다. 손바닥만 한 환영이 사람만 한 환영보다 어려웠다.`,
        ng:`빈 복도를 덧띄웠다. 화면 구석 시계가 멈췄다.<br><br>띄운 환영 속 시계는 안 움직인다. 모자가 그걸 봤다. 다른 화면 시계와 비교했다. 일어섰다.<br>계단 문까지 뛰었다. 안 열린다. 다른 길로 뛰었다. 복도 모퉁이에 어깨를 박았다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-22, mind:-14 } },
      { l:'② 화면 아홉의 사각을 찾는다.', k:'sense', dc:20,
        ok:`화면 아홉을 봤다. 화면마다 보는 데를 머릿속에 그렸다. 복도 끝 소화기 옆 한 뼘이 어느 화면에도 없다.<br><br>그 한 뼘을 따라 벽에 붙어 걸었다. 소화기 옆에서 멈췄다가, 화면이 바뀌는 순간 계단 문으로 넘어갔다.<br>계단 첫 칸에 맑은 물 한 병이 놓였다. 뚜껑이 봉해졌다.<br><br>물병에 쪽지가 붙었다. 『사각에서 오셨군요』. 그 한 뼘을 아는 사람이 놓은 것이다.`,
        ng:`사각인 줄 알았던 데에 화면이 하나 더 있었다. 열째 화면. 벽에 안 걸린 것.<br><br>모자가 책상 서랍 속 화면을 봤다. 일어섰다. 복도 불이 한꺼번에 켜졌다.<br>뛰었다. 맨발로 미끄러져 벽에 부딪쳤다. 손목을 짚다 삐었다.`,
        win:{ exp:16, item:'맑은 물' }, lose:{ hp:-24, spirit:-14 } }
    ] },

  { at:'B2', t:'복도 — 가운만 보는 것들',
    x:`7층 복도를 하얀 가운들이 다닌다. 서로 지나칠 때 고개를 한 번 숙인다. 얼굴은 안 본다. 가운만 본다.<br><br>
    환자복을 입은 것은 멈춰 세운다. 손목 띠를 읽는다. 아까 일행 하나가 그렇게 멈춰 섰다. 겨우 빠져나왔다.<br>
    복도 끝이 계단이다. 가운 셋이 오간다.<br><br>
    가운만 보는 것들에게는 가운을 보여 주면 된다.`,
    o:[
      { l:'① 마력으로 이쪽에 하얀 가운을 덧입힌다.', k:'evade', dc:22, cost:{ mana:25 },
        doom:{ title:'이름표', what:'처치실로 끌려갑니다', dc:18, sec:50,
          text:`하얀 가운을 덧입혔다. 단추, 주머니, 볼펜. 걸어갔다. 첫째 가운이 고개를 숙였다. 이쪽도 숙였다.<br><br>둘째 가운은 숙이지 않았다. 이쪽 가슴께를 봤다. 이름표 자리다. 이름표를 안 넣었다. 둘째 가운이 그 자리를 손가락으로 짚었다. 손가락이 가운을 지나 환자복에 닿았다.<br>가운이 이쪽 손목을 쥐었다. 셋째 가운이 다른 손목을 쥐었다. 둘이 이쪽을 복도 반대편으로 데려간다. 발이 바닥에서 조금 뜬다.<br><br>처치실 문 위 불이 켜졌다.`,
          dieText:`가운만 본다. 이름표도 가운이다.<br><br>점호 손전등이 스물하나를 셌다. 맞았다.<br>처치실 문 위 불이 아침까지 꺼지지 않았다.` },
        ok:`하얀 가운을 덧입혔다. 단추, 주머니, 볼펜. 가슴에 이름표. 이름은 아까 지나친 가운 것을 그대로 따 왔다.<br><br>첫째 가운이 고개를 숙였다. 이쪽도 숙였다. 둘째 가운이 이름표를 보고 숙였다. 셋째는 보지도 않았다.<br>계단 문 앞에서 무리에게 손짓했다. 무리가 이쪽 뒤에 붙어 걸었다. 가운 하나가 환자들을 데려가는 모양이다. 아무도 안 멈춰 세웠다.<br><br>계단에 들어와 가운을 거뒀다. 거두기 직전 이름표의 이름이 이쪽 이름으로 바뀌어 있었다.`,
        win:{ exp:25, dream:3 } },
      { l:'② 마력으로 반대편에서 맨발 환자를 걸어 나오게 한다.', k:'evade', dc:21, cost:{ mana:22 },
        ok:`반대편 복도에서 환자 하나가 걸어 나오게 했다. 맨발, 환자복, 손목 띠.<br><br>가운 셋이 한꺼번에 그쪽으로 갔다. 환자를 둘러쌌다. 손목을 쥐려 했다. 쥘 것이 없다. 셋이 서로의 손을 쥐었다.<br>그 사이 무리가 계단 문으로 빠졌다.<br><br>계단에서 돌아봤다. 셋이 아직 빈 데를 둘러싸고 손목 띠를 읽는 시늉을 한다. 읽을 것이 없는데도 끝까지 읽는다.`,
        ng:`환자 환영이 맨발인데 발소리가 안 났다.<br><br>가운 하나만 그쪽으로 갔다. 둘은 이쪽 무리를 봤다. 손목을 쥐러 왔다.<br>일행 하나의 손목을 가운이 쥐었다. 이쪽이 그 손을 쳐냈다. 쳐낸 손등이 언 것처럼 감각이 없다. 무리는 흩어져 다른 길로 돌았다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-20, spirit:-18 } },
      { l:'③ 가운들이 고개 숙이는 박자를 본다.', k:'sense', dc:20,
        ok:`가운 셋이 오가는 걸 봤다. 셋이 서로 고개를 숙이는 순간, 셋 다 아래를 본다. 숨 한 번.<br><br>그 숨 한 번마다 무리 하나씩을 계단 쪽으로 보냈다. 사람 하나에 숨 하나.<br>마지막에 이쪽이 지났다. 셋째 가운이 고개를 들 때 이쪽 발뒤꿈치가 계단 문 안으로 들어갔다.<br><br>가운들은 고개 숙이는 걸 멈추지 않았다. 아무도 없는 복도에서도.`,
        ng:`넷째 숨에서 가운 하나가 고개를 안 숙였다.<br><br>무리 하나가 그 앞에 섰다. 가운이 손목을 쥐었다. 뛰어들어 떼어 냈다. 떼어 낼 때 가운 손톱이 이쪽 팔을 길게 그었다.<br>계단으로 굴러 들어갔다. 팔에서 피가 나는데 아프지 않다. 그게 더 이상하다.`,
        win:{ exp:16, dream:2 }, lose:{ hp:-26, mind:-12 } }
    ] },

  { at:'B2', t:'엘리베이터 — 7층에서만 서는 칸',
    x:`엘리베이터는 7층에서만 선다. 다른 층 버튼은 눌러도 불이 안 들어온다.<br><br>
    가운 둘이 엘리베이터 앞에 섰다. 문이 열리면 내리는 것을 센다. 타는 것도 센다. 7층 인원이 줄면 안 된다.<br>
    칸 천장에 점검구가 있다. 칸 위로 나가 케이블을 타면 아래로 갈 수 있다.<br><br>
    타는 것도 세어지고 내리는 것도 세어진다. 세는 눈에는 수만 맞으면 된다.`,
    o:[
      { l:'① 마력으로 표시등에 1을 띄워 둔다.', k:'luck', dc:21, cost:{ mana:22 },
        ok:`엘리베이터 위 표시등에 숫자를 띄웠다. 1. 칸이 1층에 있는 것처럼.<br><br>가운 둘이 표시등을 보며 기다렸다. 칸은 이미 7층에 있다. 문 뒤에. 무리가 비상계단 쪽에서 돌아와 문틈을 벌렸다. 칸 안으로 들어갔다. 가운 둘은 1을 보며 기다린다.<br>점검구로 칸 위에 올랐다. 케이블을 타고 내려갔다.<br><br>표시등 환영은 오래 띄워 뒀다. 7층에서 가운 둘이 아직 1층에서 올라올 칸을 기다린다.`,
        ng:`1을 띄웠는데 진짜 표시등이 7로 켜졌다. 둘이 겹쳤다.<br><br>가운 하나가 표시등을 손가락으로 짚었다. 숫자 하나가 손가락에 묻어 나왔다. 가운 둘이 동시에 이쪽을 봤다.<br>비상계단 쪽으로 뛰었다. 잠겼다. 다른 복도로 돌았다. 모퉁이에서 미끄러져 무릎을 깼다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-24, mind:-14 } },
      { l:'② 문이 열리면 무리 모양을 내리게 하고 진짜는 칸에 남는다.', k:'evade', dc:21, cost:{ mana:25 }, wake:1,
        ok:`칸이 7층에 섰다. 문이 열렸다. 무리가 칸 안에 있다. 그 무리와 같은 모양을 문밖으로 걸어 나오게 했다. 하나씩, 가운들 앞을 지나.<br><br>가운 둘이 셌다. 탄 만큼 내렸다. 7층 인원이 맞다. 고개를 끄덕였다. 문이 닫혔다. 진짜 무리는 칸 안이다.<br>점검구로 올라 케이블을 탔다. 아래로.<br><br>내린 무리 모양은 복도 끝 병실로 들어가게 하고 거두지 않았다. 몇 층을 내려가는 동안에도 그것들이 누워 있는 게 손끝에 느껴졌다. 멀리 둔 환영이 이쪽 손을 떠나서도 수를 지켰다.`,
        ng:`무리 모양을 걸어 나오게 했다. 하나가 문턱에서 흐려졌다.<br><br>가운이 그 하나를 다시 셌다. 셈이 엉켰다. 가운 하나가 칸 안으로 손을 넣었다. 진짜 일행 하나의 어깨를 잡았다.<br>문이 닫히며 그 손을 끊어 냈다. 칸 바닥에 손이 떨어졌다. 하얀 장갑뿐이다. 안이 비었다. 잡혔던 일행 어깨가 시퍼렇게 얼었다.`,
        win:{ exp:22, dream:2 }, lose:{ mind:-14, spirit:-18 } }
    ] },

  { at:'B3', t:'9호차 — 열둘째 얼굴',
    x:`객차에 열한 명이 잔다. 창에 비친 얼굴은 열둘이다. 맨 뒷자리 창에만 얼굴이 하나 더 있다.<br><br>
    그 자리는 비었다. 비었는데 창 속에서는 누가 앉아 이쪽을 본다.<br>
    남이 만든 환영에는 이음매가 있다. 빛이 안 맞는 데, 소리가 늦는 데. 그걸 찾는 것도 이쪽 일이다.<br><br>
    창 속 얼굴이 한 번 깜박였다. 빗방울이 그 위로 흐르는데 얼굴은 안 일그러진다.`,
    o:[
      { l:'① 창 속 얼굴의 이음매를 찾는다.', k:'gaze', dc:21, wake:1,
        ok:`오래 봤다. 빗방울이 흐를 때 다른 얼굴들은 빗물에 일그러진다. 이 얼굴만 그대로다. 유리 바깥이 아니라 안쪽에 붙은 것이다.<br><br>안쪽이면 객차 안이다. 빈자리 위 선반 그림자를 봤다. 그림자가 사람 하나만큼 두껍다.<br>일행에게 손짓했다. 그 자리 반대편 통로로 앞 칸에 빠졌다. 선반 그림자가 조금 따라 늘어났다가 멈췄다.<br><br>이음매를 찾을 때 눈보다 손끝이 먼저 저렸다. 남의 마력이 닿은 자리를 손이 먼저 안다.`,
        ng:`보는 사이 창 속 얼굴이 이쪽 얼굴이 됐다.<br><br>이음매를 찾는데 이음매가 이쪽에게 맞춰졌다. 이쪽 환영과 같은 모양으로. 이쪽 버릇을 다 안다.<br>눈을 떼고 앞 칸으로 갔다. 머리가 깨질 듯 아프다. 창마다 이쪽이 이쪽보다 조금 먼저 걷는다.`,
        win:{ exp:22, dream:2 }, lose:{ mind:-16, spirit:-16 } },
      { l:'② 마력으로 무리 얼굴 위에 잠든 얼굴을 씌운다.', k:'hide', dc:21, cost:{ mana:24 },
        ok:`무리 얼굴마다 잠든 얼굴을 얹었다. 고개를 창 쪽으로 기울인 얼굴. 열한 승객과 같은 모양.<br><br>무리가 빈자리에 하나씩 앉았다. 창 속 열둘째 얼굴이 객차를 훑었다. 잠든 얼굴만 있다. 입술이 움직였다. 수를 센다. 안 맞는다. 너무 많다.<br>열둘째 얼굴이 흐려졌다. 셀 수 없는 데서는 그것도 오래 못 있는다.<br><br>얼굴을 거두는데 일행 하나의 얼굴이 잠깐 안 돌아왔다. 숨 셋 만에 돌아왔다. 그 셋 동안 일행이 이쪽 이름을 몰랐다.`,
        ng:`얼굴을 씌우는데 일행 하나가 눈을 떴다. 씌운 얼굴은 감았다.<br><br>뜬 눈과 감은 눈이 겹쳤다. 창 속 열둘째가 그걸 봤다. 빈자리가 삐걱 울었다. 누가 일어선 소리다.<br>앞 칸으로 뛰었다. 통로에서 누가 어깨를 스쳤다. 아무도 없었다. 어깨가 얼음처럼 차다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-20, spirit:-18 } }
    ] },

  { at:'B3', t:'객실 — 검표',
    x:`검표원이 온다. 객차 앞에서부터 한 사람씩 표를 받아 구멍을 뚫는다. 딸깍. 딸깍.<br><br>
    표가 있으면 그냥 넘어간다. 없으면 검표원이 차장실로 데려간다. 데려간 사람은 안 돌아왔다. 아까 하나를 봤다.<br>
    이쪽 표는 행선지 칸이 비었다. 편도. 검표원은 그 칸을 읽을 것이다.<br><br>
    검표원 얼굴이 손님마다 조금씩 바뀐다. 표를 내는 손님과 닮아 간다.`,
    o:[
      { l:'① 마력으로 행선지가 찍힌 표를 덧띄워 내민다.', k:'luck', dc:22, cost:{ mana:25 },
        doom:{ title:'검표', what:'검표원에게 끌려갑니다', dc:18, sec:45,
          text:`표 위에 행선지를 덧띄웠다. 아까 지나간 역 이름. 검표원이 받았다. 펀치를 댔다.<br><br>딸깍. 구멍이 덧띄운 글자를 뚫고 진짜 표에 났다. 구멍 둘레에서 글자가 흩어졌다. 검표원이 표를 빛에 비췄다. 행선지 칸이 비었다.<br>검표원 얼굴이 이쪽 얼굴이 됐다. 이쪽 손목을 쥐었다. 차장실 쪽으로 끈다. 이쪽 얼굴을 한 것이 이쪽을 데려간다.<br><br>객차 사람들은 아무도 안 깼다.`,
          dieText:`구멍은 진짜 표에 뚫린다.<br><br>검표원이 다음 손님 앞에 섰다. 딸깍.<br>차장실 문이 닫혔다. 그 안에서 구멍 뚫는 소리가 한 번 더 났다.` },
        ok:`표 위에 행선지를 덧띄웠다. 검표원 눈에만. 펀치가 닿을 자리에는 진짜 표의 빈칸을 그대로 뒀다.<br><br>딸깍. 구멍이 빈칸에 났다. 검표원이 표를 봤다. 행선지가 보인다. 고개를 끄덕이고 표를 돌려줬다. 얼굴이 이쪽과 조금 닮았다가 다음 손님 쪽으로 돌아갔다.<br>일행 표에도 똑같이 했다. 마지막 표에서 손이 떨렸다. 버텼다.<br><br>돌려받은 표를 봤다. 행선지 칸에 진짜 글자가 찍혀 있다. 띄운 것이 아니다. 종착역 이름이다. 읽을 수가 없다.`,
        win:{ exp:25, dream:3 } },
      { l:'② 검표원이 오기 전에 화장실 칸에 숨는다.', k:'hide', dc:21,
        ok:`검표원이 두 칸 앞일 때 일어났다. 객차 끝 화장실로 들어가 문을 잠갔다. 『사용 중』이 붉게 켜졌다.<br><br>검표원이 화장실 앞에 섰다. 두 번 두드렸다. 대답하지 않았다. 문 밑 틈으로 그림자가 오래 서 있다가 갔다.<br>딸깍 소리가 다음 칸으로 넘어갔다. 나왔다.<br><br>세면대 위에 메모가 붙었다. 『여기 숨은 사람은 다음 검표에 먼저 찍힌다』. 이쪽 글씨다.`,
        ng:`화장실 문이 안 잠겼다. 고장이다.<br><br>검표원이 문을 열었다. 이쪽 얼굴로. 표를 달라고 손을 내밀었다. 내밀었다. 검표원이 행선지 칸을 오래 봤다.<br>뒤에서 일행이 비상 손잡이를 당겼다. 기차가 덜컹했다. 검표원이 휘청이는 사이 빠져나왔다. 목덜미에 손자국이 차갑게 남았다.`,
        win:{ exp:18, dream:2 }, lose:{ mind:-16, spirit:-16 } }
    ] },

  { at:'B3', t:'식당칸 — 빨간 외투',
    x:`식당칸 창가에 빨간 외투를 입은 여자가 앉았다. 혼자다. 맞은편 의자가 비었다. 커피가 두 잔이다.<br><br>
    여자가 이쪽을 불렀다. 앉으라고. 같이 내리자고. 맨 앞 칸 문을 여는 법을 안다고.<br>
    창에 여자가 비친다. 외투가 빨갛지 않다. 회색이다. 창 속 여자는 이쪽이 아니라 이쪽 뒤를 본다.<br><br>
    맞은편 의자에 누가 앉으면 여자의 이야기가 시작된다. 꼭 이쪽일 필요는 없다.`,
    o:[
      { l:'① 마력으로 맞은편 의자에 이쪽 환영을 앉힌다.', k:'evade', dc:21, cost:{ mana:22 },
        ok:`맞은편 의자에 이쪽 환영을 앉혔다. 커피잔에 손을 얹은 모양으로. 이쪽은 통로 그늘에 섰다.<br><br>여자가 환영에게 이야기를 시작했다. 맨 앞 칸 문, 비상 손잡이, 04:43. 다 들었다. 여자는 환영이 대답을 안 해도 신경 쓰지 않았다. 듣는 사람이 필요했을 뿐이다.<br>이야기가 끝났다. 여자가 환영 쪽 잔에 무언가를 떨어뜨렸다. 하얀 가루다.<br><br>환영을 거두고 떴다. 여자 이야기 중 무엇이 참말인지는 모른다. 비상 손잡이는 참말일 것이다. 그 이야기를 할 때만 목소리가 떨렸다.`,
        ng:`환영을 앉혔는데 커피 김이 환영 손을 지나 올라갔다.<br><br>여자가 그걸 봤다. 웃었다. 환영이 아니라 이쪽 그늘로 고개를 돌렸다. 앉으라고 다시 말했다. 이번에는 목소리가 둘이다.<br>뒤로 물러났다. 등 뒤에 누가 있었다. 창 속 여자가 보던 곳이다. 밀치고 빠졌다. 옆구리를 칼끝이 스쳤다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-28, mind:-12 } },
      { l:'② 창 속 여자가 보는 쪽을 본다.', k:'gaze', dc:20,
        ok:`창 속 여자의 시선을 따라갔다. 이쪽 어깨 뒤. 식당칸 문 옆에 종업원이 섰다. 쟁반 밑에 무언가 쥐었다.<br><br>여자는 미끼다. 앉으면 등이 문 쪽이다. 앉지 않았다. 대신 종업원이 정면으로 보이는 자리에 앉았다. 등을 벽에 댔다.<br>종업원이 쟁반을 든 채 오래 서 있다가 주방으로 들어갔다. 여자가 커피 두 잔을 혼자 다 마셨다.<br><br>이쪽이 안 앉는 걸 알자 창 속 여자 외투도 빨개졌다.`,
        ng:`시선을 따라 돌아보는 순간 여자가 이쪽 손을 잡았다.<br><br>앉혀졌다. 힘이 세다. 등 뒤에서 쟁반이 내려오는 소리. 몸을 비틀었다. 쟁반 모서리가 어깨에 떨어졌다.<br>테이블을 엎고 빠져나왔다. 커피가 손등에 쏟아졌다. 뜨겁지 않다. 차갑다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-24, spirit:-14 } }
    ] },

  { at:'B3', t:'맨 앞 칸 — 세는 손님',
    x:`맨 앞 칸이다. 기관실 문 앞에 그것이 섰다. 얼굴을 바꾸는 손님. 지금은 일행 중 하나의 얼굴이다.<br><br>
    시계는 04:41. 내리는 문은 그것 등 뒤에 있다.<br>
    그것은 이쪽을 막지 않는다. 무리를 센다. 하나씩. 다 이 칸에 와야 문 앞을 비킨다. 다 오면 하나를 데려간다. 등받이 글씨에 그렇게 적혀 있었다.<br><br>
    다 왔다고 믿게 하면 된다. 하나 모자라게. 아니면 하나 많게.`,
    o:[
      { l:'① 마력으로 무리가 뒤 칸으로 돌아가는 모습을 띄운다.', k:'evade', dc:22, cost:{ mana:26 }, wake:1,
        ok:`무리가 돌아서 뒤 칸으로 걸어가는 모습을 띄웠다. 하나씩, 문을 열고 나가는 데까지. 진짜 무리는 그 자리에 세우고 그 위에 빈 통로를 덮었다.<br><br>그것이 뒤 칸으로 가는 무리를 셌다. 다 갔다. 셀 것이 없다. 그것이 뒤 칸으로 따라갔다. 문 앞이 비었다.<br>진짜 무리가 내리는 문으로 갔다. 04:43. 문을 열었다.<br><br>가는 모습과 비운 자리를 한꺼번에 들고 있었는데 손이 안 떨렸다. 숨이 보내는 쪽과 덮는 쪽으로 갈라져 흘렀다. 띄우는 일과 지우는 일이 처음으로 같은 숨에 들어갔다.`,
        ng:`돌아가는 무리 하나가 문손잡이를 못 잡았다. 손이 손잡이를 지나갔다.<br><br>그것이 그걸 봤다. 셈을 멈췄다. 이쪽을 봤다. 얼굴이 이쪽 얼굴로 바뀌었다. 걸어왔다.<br>무리가 흩어졌다. 그것의 손이 목덜미를 스쳤다. 피부가 얼었다가 화끈거렸다. 객차 끝까지 밀려났다. 시간이 간다.`,
        win:{ exp:24, dream:3 }, lose:{ hp:-22, spirit:-20 } },
      { l:'② 마력으로 하나를 더 세워 그것이 데려가게 한다.', k:'luck', dc:21, cost:{ mana:24 },
        ok:`무리 끝에 하나를 더 세웠다. 일행 모양 하나. 맨 끝에, 조금 떨어져서.<br><br>그것이 셌다. 다 왔다. 문 앞을 비켰다. 무리가 문으로 갔다. 그것이 맨 끝 하나에게 다가가 손목을 쥐었다. 쥔 손이 비었다. 그것이 빈손을 오래 봤다.<br>그 사이 문이 열렸다. 무리가 뛰어내렸다. 이쪽이 마지막이다.<br><br>뛰어내리며 봤다. 그것이 빈손을 쥔 채 이쪽을 봤다. 화난 얼굴이 아니었다. 처음으로 아무 얼굴도 아니었다.`,
        ng:`하나를 더 세웠다. 그것이 셌다. 하나 많다. 많은 건 처음이라는 듯 고개를 갸웃했다.<br><br>그리고 처음부터 다시 셌다. 하나씩 얼굴을 만져 가며. 차가운 손이 일행 얼굴을 지났다. 다들 굳었다.<br>세운 하나를 거두자 그것이 또 셌다. 그 사이 04:43이 지나갔다. 휘는 데를 놓쳐 곧은 데서 뛰어야 했다. 다들 다쳤다. 이쪽은 어깨가 빠졌다.`,
        win:{ exp:20, dream:3 }, lose:{ hp:-30, mind:-14 } },
      { l:'③ 그것이 쓴 얼굴의 이음매를 짚어 준다.', k:'gaze', dc:21,
        ok:`그것의 얼굴을 봤다. 일행 얼굴이다. 그런데 귀 밑에서 빛이 안 맞는다. 이음매다. 얼굴이 거기서 붙었다.<br><br>손가락으로 그 자리를 가리켰다. 그것이 손을 귀 밑에 댔다. 얼굴이 미끄러졌다. 밑에 다른 얼굴이 있다. 그 밑에 또.<br>그것이 얼굴을 고르느라 바쁘다. 무리가 그 옆을 지나 문을 열었다.<br><br>뛰어내리기 직전 맨 밑 얼굴이 잠깐 보였다. 아무것도 없는 얼굴이었다. 처음 띄워 본 환영처럼.`,
        ng:`이음매를 가리켰다. 그것이 웃었다. 이음매가 이쪽 손가락 끝으로 옮겨 왔다.<br><br>손가락 끝 살갗이 들떴다. 이쪽 손이 이쪽 손 같지 않다. 그것이 그 들뜬 데를 잡아당기려 손을 뻗었다.<br>일행이 이쪽을 끌어 문밖으로 던졌다. 자갈 둑을 굴렀다. 들뜬 데가 가라앉는 데 한참 걸렸다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-24, spirit:-18 } }
    ] }
]);

// ── 척후병 (scout) · 무력 ────────────────────
kJob('scout', 'B', [
  { at:'B', t:'골목 미로 — 열 걸음 앞',
    x:`비 오는 밤 골목이다. 골목이 골목으로 갈라진다. 무리가 뒤에 있다. 척후병의 자리는 열 걸음 앞이다.<br><br>
    열 걸음 앞은 늘 혼자다. 오늘은 위에도 누가 있다. 지붕 어딘가에서 빗물 떨어지는 박자가 한 번씩 끊긴다. 누가 처마 밑에 서서 물줄기를 가린 것이다.<br>
    망꾼이다. 위에서 보면 골목이 다 보인다. 무리가 어디로 가는지도.<br><br>
    망꾼을 먼저 못 찾으면 무리는 망꾼이 보는 길로 걷는다.`,
    o:[
      { l:'① 끊기는 물줄기를 따라 망꾼 자리를 찾는다.', k:'sense', dc:21, wake:1,
        ok:`열 걸음 앞에서 멈췄다. 처마마다 떨어지는 물줄기를 봤다. 셋째 골목, 넷째 집 처마. 물줄기가 한 뼘 끊겼다가 이어진다. 그 자리에 사람이 서 있다.<br><br>뒤로 손을 펴 보였다. 멈춤. 다시 두 손가락. 왼쪽. 무리가 망꾼 처마를 피해 왼쪽으로 돌았다. 이쪽은 마지막까지 서서 망꾼 쪽을 봤다. 망꾼은 오른쪽 골목만 본다.<br>골목을 빠져나왔다.<br><br>앞만 보던 눈이 위까지 봤다. 앞과 위가 한 장으로 들어왔다. 물줄기 하나 끊기는 것까지.`,
        ng:`끊긴 물줄기를 찾았다. 하나가 아니었다. 셋이다.<br><br>하나를 피해 돌린 골목을 다른 하나가 보고 있었다. 위에서 휘파람이 울렸다. 골목 끝에서 사람들이 나왔다.<br>무리를 다른 길로 돌리고 맨 뒤에서 막았다. 쇠파이프가 팔뚝을 쳤다. 한동안 손이 안 펴졌다.`,
        win:{ exp:22, dream:2 }, lose:{ hp:-26, mind:-12 } },
      { l:'② 무력을 실어 처마를 타고 올라 망꾼을 누른다.', k:'break', dc:21, cost:{ might:24 },
        ok:`처마 밑 창살을 잡고 올랐다. 지붕 위로. 망꾼이 보기 전에 등 뒤에 섰다.<br><br>목덜미를 잡아 지붕에 눌렀다. 망꾼 손에서 손전등이 떨어졌다. 꺼진 채 골목으로 굴러떨어졌다. 소리가 빗소리에 묻혔다.<br>입을 손으로 막고 무리가 다 지날 때까지 버텼다. 그리고 놓았다. 망꾼은 숨만 몰아쉬었다. 소리 지르지 않았다.<br><br>망꾼 손목에 이쪽 무리 인원수가 볼펜으로 적혀 있다. 하나 많게.`,
        ng:`처마 창살이 이쪽 무게에 휘었다.<br><br>오르는 소리를 망꾼이 들었다. 위에서 이쪽 손을 밟았다. 떨어졌다. 골목 바닥에 등부터.<br>휘파람이 울렸다. 무리가 이쪽을 끌고 뛰었다. 등이 펴지지 않는다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-30, spirit:-12 } }
    ] },

  { at:'B', t:'갈림목 — 네온 셋',
    x:`골목이 셋으로 갈렸다. 셋 다 어둡다. 입구마다 네온이 하나씩 걸렸다. 빨강, 파랑, 초록.<br><br>
    하나는 큰길로 나간다. 하나는 막혔다. 하나에는 누가 기다린다. 어느 게 어느 건지 모른다.<br>
    무리는 기다린다. 뒤에서 오는 발소리가 있다. 기다릴 시간은 그 발소리가 정한다.<br><br>
    셋을 다 봐야 하나를 고른다. 다 보려면 빨라야 한다.`,
    o:[
      { l:'① 무력을 다해 셋 다 달려 보고 온다.', k:'sense', dc:21, cost:{ might:25 },
        ok:`빨강을 마흔 걸음, 파랑을 마흔 걸음, 초록을 마흔 걸음. 달려서 갔다 왔다.<br><br>빨강 끝은 벽이다. 파랑 끝은 큰길이다. 초록 끝 구석에 담뱃불이 둘. 이쪽이 지나가도 안 움직였다. 기다리는 건 무리지 이쪽 하나가 아니다.<br>파랑으로 무리를 보냈다. 뒤의 발소리가 갈림목에 닿기 전에 다 빠졌다.<br><br>숨이 턱에 찬다. 파랑 골목 네온이 한 번 꺼졌다 켜졌다. 이쪽이 지나간 뒤로 처음이다.`,
        ng:`초록에 들어가다 담뱃불 둘과 마주쳤다.<br><br>되돌아 뛰었다. 다리가 풀렸다. 파랑은 끝까지 못 봤다. 반만 보고 골랐다. 반은 맞았다. 큰길 앞을 차 한 대가 막고 있었다.<br>차를 넘어 무리를 빼냈다. 보닛에 무릎을 찧었다. 숨이 한참 안 돌아왔다.`,
        win:{ exp:22, dream:2 }, lose:{ hp:-26, mind:-12 } },
      { l:'② 바닥 물길을 읽는다.', k:'gaze', dc:20,
        ok:`바닥을 봤다. 빨강 골목 물은 고였다. 막힌 데다. 파랑 골목 물은 흘러 나간다. 뚫린 데다.<br><br>초록 골목 물에는 담뱃재가 떠내려온다. 누가 서 있다.<br>파랑으로 무리를 보냈다. 열 걸음 앞에서 이쪽이 먼저 갔다. 큰길이 나왔다.<br><br>물은 거짓말을 안 한다. 물에 재를 뿌린 사람이 아니라면.`,
        ng:`파랑 골목 물이 흘러 나갔다. 들어갔다. 끝에 하수구 쇠창살이 있다. 물만 나가는 길이다.<br><br>되돌아왔다. 시간을 썼다. 뒤의 발소리가 갈림목에 닿았다. 무리가 빨강으로 뛰었다. 막혔다. 담을 넘었다.<br>담 위 깨진 병에 손바닥이 찢어졌다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-24, spirit:-12 } },
      { l:'③ 본 것만 알리고 무리와 같이 고른다.', k:'bond', dc:20,
        ok:`갈림목 입구에서 본 것만 알렸다. 빨강은 바람이 없다. 파랑은 바람이 온다. 초록에서 담배 냄새가 난다.<br><br>무리가 같이 골랐다. 파랑. 틀리면 같이 틀린 것이다.<br>틀리지 않았다. 큰길이 나왔다. 건너편 처마 밑에 꿀 한 줌 든 단지가 있다. 노점이 두고 간 것이다.<br><br>무리 하나가 말했다. 담배 냄새는 못 맡았다고. 이쪽 코에만 났다.`,
        ng:`알리는데 말이 엉켰다. 바람이 어느 쪽이었는지 헷갈렸다.<br><br>무리가 초록으로 갔다. 담뱃불 둘이 일어섰다. 되돌아 뛰었다. 이쪽이 맨 뒤에서 막았다.<br>주먹이 광대뼈를 쳤다. 눈 밑이 부었다. 다들 말이 없다. 척후병이 제일 말이 없다.`,
        win:{ exp:16, item:'꿀 한 줌' }, lose:{ hp:-22, mind:-14 } }
    ] },

  { at:'B', t:'돌아오는 벽 — 바뀐 화살표',
    x:`지나온 벽마다 분필로 표식을 남겼다. 화살표 하나, 위험하면 가위표. 돌아올 때 이 표식을 따른다.<br><br>
    돌아오는 길이다. 표식이 있다. 그런데 화살 끝이 조금 다르다. 이쪽은 화살 끝을 둥글게 꺾는다. 이건 날카롭다.<br>
    누가 지우고 다시 그렸다. 이쪽 버릇을 흉내 냈지만 끝까지는 몰랐다.<br><br>
    화살표는 오른쪽을 가리킨다. 이쪽은 왼쪽에서 왔다.`,
    o:[
      { l:'① 무리만 아는 표식을 새로 남긴다.', k:'fix', dc:21,
        ok:`날카로운 화살표 옆에 작은 점 셋을 찍었다. 무리만 아는 표시다. 점 셋은 반대로 가라는 뜻이다.<br><br>무리가 뒤따라왔다. 점 셋을 봤다. 왼쪽으로 갔다. 이쪽이 맨 뒤에서 화살표를 문질러 지웠다.<br>왼쪽 끝에 처음 들어온 문이 있었다. 열고 나왔다.<br><br>오른쪽 골목에서는 사람들이 한참 기다렸다. 이쪽이 그린 적 없는 화살표 끝에서.`,
        ng:`점 셋을 찍는데 분필이 부러졌다.<br><br>점이 둘만 찍혔다. 무리 하나가 점 둘을 봤다. 둘은 아무 뜻이 아니다. 화살표를 따라 오른쪽으로 갔다.<br>뛰어가 붙잡았다. 오른쪽 골목 끝에서 사람들이 나왔다. 무리를 끌고 돌아섰다. 등에 각목이 날아왔다. 견갑골이 결린다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-26, mind:-12 } },
      { l:'② 바뀐 화살표를 따라 먼저 가 본다.', k:'evade', dc:22,
        doom:{ title:'바뀐 화살표', what:'바뀐 표식 끝에서 붙잡혔습니다', dc:17, sec:55,
          text:`화살표를 따라 먼저 갔다. 열 걸음 앞이 아니라 백 걸음 앞까지.<br><br>골목이 좁아진다. 벽에 화살표가 또 있다. 또. 흉내 낸 화살표가 점점 이쪽 버릇에 가까워진다. 마지막 화살표는 이쪽이 그린 것과 똑같다.<br>그 밑에 사람이 기대 서 있다. 분필을 쥐었다. 이쪽 팔을 잡았다. 다른 손이 어깨를 잡았다. 셋째 손이 뒤에서 입을 막았다.<br><br>무리는 백 걸음 뒤에 있다. 표식을 보고 오는 중이다.`,
          dieText:`먼저 가서 먼저 돌아온다. 돌아오지 못하면 표식만 남는다.<br><br>그 골목 벽에 화살표가 하나 더 그려졌다. 이쪽 버릇 그대로. 끝이 둥글게 꺾였다.<br>무리는 그 화살표 앞에서 오래 서 있었다.` },
        ok:`화살표를 따라 먼저 갔다. 마흔 걸음까지만. 그 이상은 안 갔다.<br><br>골목이 좁아진다. 벽에 화살표가 또 있다. 점점 이쪽 버릇에 가까워진다. 마흔 걸음째에 멈췄다. 다음 화살표 밑에 담뱃불이 있다.<br>담뱃불이 보기 전에 돌아섰다. 돌아오며 화살표를 하나씩 지웠다. 무리에게 손을 들었다. 반대.<br><br>지워도 분필 자국이 빗물에 다시 떠오른다. 누가 그 자리를 여러 번 그렸다. 이쪽 무리가 오기 전부터.`,
        win:{ exp:25, dream:3 } }
    ] },

  { at:'B', t:'철조망 — 손전등의 박자',
    x:`철조망 너머가 나갈 길이다. 이쪽 편을 경비 둘이 철조망 따라 돈다. 손전등을 들었다. 한 바퀴에 숨 백.<br><br>
    둘이 끝에서 마주치는 데가 있다. 거기서 담배를 나눠 피운다. 숨 스물.<br>
    박자를 세서 무리에게 넘기는 게 이쪽 일이다. 무리는 손짓 하나로 움직인다.<br><br>
    손짓이 늦으면 무리 전부가 늦는다.`,
    o:[
      { l:'① 먼저 넘고 담배 박자에 손짓한다.', k:'evade', dc:21, wake:1,
        ok:`두 바퀴를 셌다. 담배는 숨 스물. 셋째 바퀴에 담뱃불이 켜지는 순간 철조망 밑 틈으로 굴렀다. 먼저 넘었다.<br><br>바깥 풀숲에 엎드려 손을 들었다. 하나, 둘. 무리가 하나씩 넘었다. 담뱃불이 꺼지기 숨 셋 전에 마지막이 넘었다.<br>경비 둘이 다시 돌기 시작했다. 무리는 이미 바깥 어둠이다.<br><br>손이 박자보다 반 숨 먼저 올라갔다. 무리 다리가 손보다 늦게 움직인다는 걸 손이 알았다. 남의 걸음까지 세는 손이 됐다.`,
        ng:`셋째 바퀴에 담배가 없었다. 둘이 마주치고도 그냥 지나갔다.<br><br>이쪽은 이미 철조망 밑이다. 가시가 등에 걸렸다. 손전등이 철조망을 훑으며 온다. 억지로 빠져나갔다. 등이 길게 찢어졌다.<br>무리는 못 넘었다. 다음 박자까지 숨 백을 더 기다렸다. 그동안 이쪽 등에서 피가 철조망을 타고 흘렀다.`,
        win:{ exp:22, dream:2 }, lose:{ hp:-28, mind:-12 } },
      { l:'② 무력을 실어 말뚝을 흔들어 틈을 낸다.', k:'break', dc:21, cost:{ might:25 },
        ok:`말뚝 하나를 두 손으로 쥐었다. 젖은 흙이 무르다. 힘으로 흔들었다. 다섯 번. 말뚝이 기울었다.<br><br>철조망 밑이 무릎 높이로 들렸다. 담배 박자가 왔다. 무리가 그 밑으로 차례로 기었다. 말뚝을 붙든 채 마지막까지 버텼다.<br>놓았다. 말뚝이 제자리로 안 돌아온다. 기운 채 섰다.<br><br>다음 바퀴에 경비가 기운 말뚝을 볼 것이다. 그때 무리는 셋째 골목쯤에 있을 것이다.`,
        ng:`말뚝 밑에 콘크리트가 있었다.<br><br>흔들어도 안 뽑힌다. 소리만 났다. 손전등이 이쪽으로 돌았다. 빛을 받은 채 엎드렸다.<br>경비가 이쪽을 오래 비췄다. 그리고 갔다. 손바닥이 말뚝 가시에 다 찢어졌다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-24, spirit:-14 } }
    ] },

  { at:'B', t:'지하도 — 차오르는 물',
    x:`지하도다. 비가 계단으로 쏟아져 들어온다. 물이 무릎까지 찼다. 계속 찬다.<br><br>
    반대편 출구가 열렸는지 모른다. 철문이다. 닫혀 있으면 무리는 여기 갇힌다.<br>
    돌아가는 길은 뒤의 발소리가 막았다. 앞만 남았다. 앞이 열렸는지는 누가 먼저 가 봐야 안다.<br><br>
    물은 숨 쉴 때마다 손가락 한 마디씩 오른다.`,
    o:[
      { l:'① 물을 헤쳐 먼저 출구를 보고 온다.', k:'evade', dc:22,
        doom:{ title:'차오르는 물', what:'지하도 물에 빨려 들어갑니다', dc:17, sec:50,
          text:`물을 헤치고 앞서 갔다. 허리, 가슴. 반쯤 갔을 때 바닥이 꺼졌다. 배수구다. 뚜껑이 빠졌다.<br><br>발이 빨려 들어갔다. 물이 그쪽으로 흐른다. 몸이 배수구 쪽으로 끌려간다. 손이 벽 난간을 잡았다. 머리가 물 밑으로 들어갔다 나왔다.<br>뒤에서 무리가 이쪽 이름을 부른다. 물소리에 반만 들린다.<br><br>물은 아직도 한 마디씩 오른다.`,
          dieText:`먼저 가 보는 게 이쪽 일이다. 이번에는 가 본 것을 알려 줄 수 없었다.<br><br>무리는 다른 길을 찾았다. 배수구 쪽으로는 아무도 안 갔다.<br>물이 빠진 아침, 철문은 열려 있었다.` },
        ok:`물을 헤치고 앞서 갔다. 발로 바닥을 먼저 더듬었다. 반쯤 갔을 때 발끝이 빈 데를 짚었다. 배수구다. 뚜껑이 빠졌다.<br><br>빈 데를 돌아 벽 난간을 잡고 갔다. 철문에 닿았다. 밀었다. 열린다. 돌아왔다. 무리가 배수구를 피해 가도록 이쪽이 그 가장자리에 섰다. 다리가 빨려 든다. 버텼다.<br>무리가 다 지났다. 마지막에 이쪽이 빠져나왔다.<br><br>철문 밖은 비가 그치고 있었다. 지하도 안에서는 아직 물 차오르는 소리가 났다.`,
        win:{ exp:25, dream:3 } },
      { l:'② 벽에 남은 물 자국을 읽는다.', k:'sense', dc:20,
        ok:`벽에 물 자국이 줄줄이 남았다. 지난 비들이 남긴 높이다. 이쪽 벽 제일 높은 자국은 머리 위다. 반대편 벽 자국은 허리까지다.<br><br>물이 반대편에서 빠졌다는 뜻이다. 철문 밑에 틈이 있다.<br>무리를 데리고 반대편으로 갔다. 철문 아래로 물이 빠지고 있다. 문은 잠겼지만 틈이 기어 나갈 만하다. 하나씩 기었다.<br><br>틈 앞 웅덩이에 민물고기 한 마리가 퍼덕였다. 강에서 빗물 따라 들어왔다. 챙겼다.`,
        ng:`물 자국을 읽는 사이 물이 가슴까지 왔다.<br><br>반대편으로 가니 문 아래 틈이 쓰레기로 막혔다. 손으로 파냈다. 물속에서. 숨을 참고.<br>틈이 열렸다. 다 빠져나왔다. 이쪽이 마지막이다. 손톱이 다 깨졌다. 물을 몇 모금 먹었다.`,
        win:{ exp:18, item:'민물고기' }, lose:{ hp:-24, mind:-14 } },
      { l:'③ 무리를 끈으로 엮고 맨 앞에 선다.', k:'bond', dc:21,
        ok:`무리 허리를 외투 끈으로 엮었다. 맨 앞이 이쪽이다. 끈이 팽팽하면 멈추고 느슨하면 간다고 정했다.<br><br>물속에서 한 걸음씩 갔다. 배수구 앞에서 이쪽이 빠질 뻔했다. 끈이 팽팽해졌다. 무리가 당겼다. 빠졌다가 올라왔다.<br>철문에 닿았다. 열려 있었다. 다 같이 나왔다.<br><br>끈을 풀었다. 매듭 하나가 이쪽이 묶은 게 아니다. 누가 물속에서 하나 더 묶었다. 끈 끝이 물속으로 늘어져 있다. 잘라 냈다.`,
        ng:`배수구 앞에서 끈이 반대로 당겨졌다.<br><br>이쪽이 아니라 뒤에서 누가 빠졌다. 끈이 엉켰다. 돌아가 그 사람을 끌어 올렸다. 둘 다 물을 많이 먹었다.<br>철문까지 가는 데 한참 걸렸다. 열려 있었다. 다행이다. 폐 깊은 데가 아프다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-26, spirit:-14 } }
    ] },

  { at:'B', t:'뒷골목 — 같은 가로등',
    x:`길잡이가 붙었다. 이 동네를 잘 안다는 사람이다. 돈을 받았다. 앞서 걷는다.<br><br>
    원래 이쪽 자리는 앞이다. 오늘은 길잡이 뒤다. 그래서 길잡이 등을 본다. 길잡이는 가끔 시계를 본다.<br>
    세 번째 모퉁이에서 가로등을 지났다. 기둥에 찢어진 전단이 붙었다. 다섯 번째 모퉁이에서 또 지났다. 같은 전단이다.<br><br>
    같은 데를 돈다. 시간을 쓰고 있다. 누가 올 때까지.`,
    o:[
      { l:'① 길잡이 몰래 열 걸음 앞서 진짜 길을 찾는다.', k:'evade', dc:21, wake:1,
        ok:`길잡이가 모퉁이를 돌 때 이쪽은 안 돌았다. 곧장 갔다. 열 걸음 앞으로.<br><br>골목 셋을 지나자 바람이 바뀌었다. 바다 냄새. 큰길이다. 돌아와서 무리에게 손짓했다. 길잡이를 놔두고 무리가 하나씩 빠졌다.<br>길잡이는 다음 모퉁이에서 돌아봤다. 아무도 없다. 시계를 봤다. 아직 이르다. 이른데 다 갔다.<br><br>남이 앞서 걸어도 이쪽 열 걸음은 따로 있었다. 앞에 누가 있든 이쪽 앞은 이쪽이 정한다.`,
        ng:`앞서 갔는데 길잡이가 휘파람을 불었다.<br><br>모퉁이마다 사람이 하나씩 나왔다. 길잡이가 돈 길은 그 사람들 자리를 다 지나는 길이었다. 앞서 간 골목에도 하나가 있다.<br>밀치고 지나갔다. 칼끝이 옆구리를 스쳤다. 무리를 데리고 처음 골목으로 돌아가는 데 한참 걸렸다.`,
        win:{ exp:22, dream:2 }, lose:{ hp:-28, mind:-12 } },
      { l:'② 길잡이에게 길을 묻는 척 떠본다.', k:'gaze', dc:20,
        ok:`길잡이에게 물었다. 다음 모퉁이 가로등에도 전단이 붙었냐고. 길잡이가 그렇다고 했다. 보지도 않고.<br><br>그 모퉁이에 전단은 없었다. 길잡이는 질문에 맞춰 대답했다. 이 동네를 모른다. 아는 척을 아는 사람이다.<br>길잡이가 시계를 볼 때 무리를 데리고 반대로 갔다. 길잡이는 안 쫓아왔다. 다음 손님을 기다리는 사람이다.<br><br>준 돈은 못 돌려받았다. 대신 길잡이 주머니에서 떨어진 지도를 주웠다. 오늘 길이 그려져 있다. 반대로 읽으면 맞는 길이다.`,
        ng:`물었더니 길잡이가 웃었다.<br><br>전단은 없다고 했다. 대신 이쪽 이름을 불렀다. 말해 준 적 없는 이름이다. 그리고 손을 들었다. 지붕에서 벽돌이 떨어졌다. 어깨를 스쳤다.<br>무리를 데리고 뛰었다. 어깨에서 피가 난다. 길잡이는 그 자리에서 시계만 봤다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-24, spirit:-14 } }
    ] },

  { at:'B', t:'옥상 — 건너편 창 서른',
    x:`옥상이다. 건너편 건물 창이 서른이다. 불 켜진 창이 셋. 꺼진 창 중에 누가 있는 창이 있다.<br><br>
    무리가 건너편 건물 앞 골목을 지나야 한다. 창에서 다 보인다. 몇이 보는지 알아야 지날 때를 고른다.<br>
    척후병이 할 일은 세는 일이다. 세고, 돌아가서, 정확히 말하는 일.<br><br>
    옥상 물탱크가 제일 높다. 사다리가 녹슬었다.`,
    o:[
      { l:'① 무력을 실어 물탱크 위로 올라 창을 센다.', k:'sense', dc:21, cost:{ might:22 },
        ok:`녹슨 사다리를 힘으로 버티며 올랐다. 물탱크 위에 엎드렸다.<br><br>창 서른을 봤다. 불 켜진 셋은 비었다. 꺼진 창 둘에서 담뱃불이 한 번씩 켜진다. 꺼진 창 하나에서는 커튼이 바람 없이 움직인다. 셋이다.<br>내려와 무리에게 말했다. 셋. 자리. 담배 박자. 무리가 그 박자에 맞춰 골목을 지났다.<br><br>물탱크 위에 맑은 물이 고인 홈이 있었다. 내려오기 전에 통에 받았다.`,
        ng:`사다리 셋째 칸이 빠졌다.<br><br>매달렸다. 녹 가루가 눈에 들어갔다. 물탱크 위에서도 한쪽 눈이 안 보였다. 창을 반만 셌다.<br>둘이라고 말했다. 셋이었다. 골목을 지나던 무리 위로 창 하나가 열렸다. 다들 뛰었다. 눈이 하루 종일 따끔거렸다.`,
        win:{ exp:18, item:'맑은 물' }, lose:{ hp:-22, mind:-14 } },
      { l:'② 담뱃불에 맞춰 손 신호로 무리를 보낸다.', k:'bond', dc:20,
        ok:`난간에서 골목 입구의 무리를 내려다봤다. 창을 세는 대신 담뱃불만 봤다. 불이 켜질 때 피우는 사람은 창밖이 아니라 불을 본다.<br><br>담뱃불이 켜질 때마다 손을 내렸다. 무리 하나가 지났다. 무리 수만큼.<br>마지막 손을 내렸다. 다 지났다. 이쪽은 옥상을 건너 내려갔다.<br><br>무리 하나가 말했다. 이쪽 손이 내려갈 때마다 창 하나에서도 손이 같이 내려갔다고. 그 창에는 담뱃불이 없었다.`,
        ng:`피우는 사람이 둘이었다. 박자가 겹쳤다.<br><br>손을 내렸다. 무리 하나가 지났다. 그 순간 다른 창에 불이 켜졌다. 골목이 환해졌다. 아래서 고함이 났다.<br>무리를 다른 쪽으로 돌렸다. 옥상에서 내려가다 계단에서 미끄러졌다. 정강이가 찍혔다.`,
        win:{ exp:16, dream:2 }, lose:{ hp:-24, spirit:-12 } }
    ] },

  { at:'B', t:'처마 밑 — 먼저 와 있는 무리',
    x:`앞서 보고 돌아왔다. 무리를 둔 자리다. 가게 처마 밑. 무리가 그대로 있다. 젖은 외투.<br><br>
    무리가 동시에 이쪽을 봤다. 동시에 고개를 끄덕였다. 무리는 그렇게 안 한다.<br>
    처마 밑 바닥에 떠나기 전 분필로 그은 줄이 있다. 무리는 그 줄 뒤에 서 있기로 했다. 지금은 다들 줄 앞에 섰다.<br><br>
    척후병은 돌아올 때가 제일 위험하다. 돌아온 데가 떠난 데와 같은지 모른다.`,
    o:[
      { l:'① 정해 둔 암호를 묻는다.', k:'bond', dc:21,
        ok:`처마 밖에서 물었다. 정해 둔 말. 비가 언제 그치냐고.<br><br>처마 밑이 동시에 대답했다. 내일. 맞는 대답은 그친 적 없다, 다. 다들 고개를 기울였다. 처마 밑 불이 꺼졌다. 다시 켜지자 아무도 없었다.<br>건너편 골목 입구에서 진짜 무리가 손을 흔들었다. 처마 밑에서 기다리다 사람들이 와서 자리를 옮겼다고 했다.<br><br>분필 줄 앞에 젖은 발자국이 남았다. 발자국이 다 이쪽을 향한다.`,
        ng:`묻기 전에 처마 밑에서 누가 먼저 말했다. 비가 언제 그치냐고. 이쪽 목소리로.<br><br>대답이 목에서 막혔다. 처마 밑이 한 걸음씩 나왔다. 뒷걸음질 쳤다. 같은 걸음으로 따라왔다.<br>뛰었다. 골목 셋을 지나 진짜 무리를 찾았다. 그동안 등 뒤에서 이쪽 목소리가 암호를 계속 물었다. 밤새 그 목소리가 귀에 남았다.`,
        win:{ exp:20, dream:2 }, lose:{ mind:-16, spirit:-18 } },
      { l:'② 처마 밖에서 물러나 지켜본다.', k:'hide', dc:21, wake:1,
        ok:`처마 밖 어둠에서 멈췄다. 물러났다. 처마 밑은 이쪽이 물러난 자리를 계속 본다.<br><br>기다렸다. 숨 백. 처마 밑이 고개를 같이 돌렸다. 다른 쪽을 봤다. 진짜 무리가 그쪽 골목에서 이쪽을 찾으러 나오는 중이다.<br>먼저 그쪽으로 돌아가 무리를 붙잡았다. 손을 들어 멈추게 했다. 다른 길로 돌렸다. 처마 밑 것들은 무리가 지나갈 데를 끝까지 보고 섰다.<br><br>돌아올 때는 돌아온 자리부터 본다. 이제는 떠날 때도 돌아올 자리를 한 번 더 본다. 몸에 붙은 순서가 하나 늘었다.`,
        ng:`물러나다 웅덩이를 밟았다.<br><br>처마 밑이 동시에 이쪽을 봤다. 걸어 나왔다. 빠르지 않다. 이쪽이 뛰는 만큼 빨라진다.<br>골목을 셋 돌았다. 발소리가 끊겼다. 진짜 무리를 만났을 때 외투 등에 손자국이 여럿 젖어 있었다.`,
        win:{ exp:22, dream:2 }, lose:{ mind:-14, spirit:-18 } },
      { l:'③ 줄 앞에 선 발을 본다.', k:'gaze', dc:20,
        ok:`발을 봤다. 신발이 안 젖었다. 처마 밑이라 그럴 수 있다. 그런데 바닥 물웅덩이에 아무도 안 비친다.<br><br>무리를 흉내 낸 것이다. 진짜는 다른 데 있다. 분필 줄을 다시 봤다. 줄 끝에 작은 점 셋. 무리가 남긴 표식이다. 반대쪽으로 갔다는 뜻이다.<br>점 셋을 따라갔다. 무리가 그쪽 처마에 있었다.<br><br>왜 자리를 옮겼냐고 물었다. 이쪽이 돌아와서 옮기라고 했다고 했다. 이쪽은 방금 돌아왔다.`,
        ng:`발을 보느라 고개를 숙인 사이 처마 밑이 한 걸음 다가왔다.<br><br>분필 줄을 넘었다. 넘는 순간 처마 불이 꺼졌다. 어둠 속에서 차가운 손이 이쪽 손목을 잡았다. 무리 하나의 손 모양이다.<br>뿌리쳤다. 손목에 얼음 같은 자국이 남았다. 진짜 무리를 찾는 데 한참 걸렸다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-20, spirit:-18 } }
    ] },

  { at:'B1', t:'쪽문 밖 — 바퀴 자국',
    x:`3번 창고 쪽문 밖은 좁은 골목이다. 젖은 시멘트에 바퀴 자국이 두 줄. 손수레다.<br><br>
    청소부가 수레를 밀고 간 자국이다. 골목 끝에서 꺾인다. 수레가 무거웠다. 자국이 깊다.<br>
    무리를 골목 입구에 세웠다. 이쪽이 먼저다. 열 걸음 앞.<br><br>
    골목 끝은 둘로 갈린다. 수레가 간 쪽과 안 간 쪽.`,
    o:[
      { l:'① 바퀴 자국을 읽어 수레보다 앞서 길을 고른다.', k:'evade', dc:21, wake:1,
        ok:`자국을 봤다. 꺾인 데에서 자국이 한 번 멈췄다. 수레가 섰다. 무게를 내렸다. 그다음 자국이 얕다. 다시 출발했다.<br><br>내린 자리에 방수포가 덮였다. 안 들췄다. 가벼워진 수레는 돌아올 것이다. 안 간 쪽으로 무리를 보냈다. 이쪽은 꺾인 데서 바퀴 소리를 기다렸다. 돌아온다. 숨 마흔.<br>숨 서른에 이쪽도 빠졌다.<br><br>자국 하나로 수레가 가고 서고 돌아오는 걸 다 봤다. 한 번 지나간 것의 다음이 보였다. 땅이 이쪽에게 말을 했다.`,
        ng:`자국을 읽는 사이 바퀴 소리가 먼저 들렸다. 생각보다 빨리 돌아왔다.<br><br>골목 끝에서 수레와 마주쳤다. 수레를 민 것이 이쪽을 봤다. 고무장갑이 손잡이를 놓고 이쪽으로 왔다.<br>뒤로 뛰며 무리에게 손짓했다. 무리가 흩어졌다. 어깨에 대걸레 자루가 떨어졌다. 쇄골이 울렸다.`,
        win:{ exp:22, dream:2 }, lose:{ hp:-26, mind:-12 } },
      { l:'② 수레가 내려놓은 방수포를 들춰 본다.', k:'gaze', dc:20,
        ok:`꺾인 데의 방수포를 들췄다. 사람이 아니다. 건어물 상자다. 말린 고기가 가득하다.<br><br>청소부는 사람만 치우는 게 아니다. 창고에 있던 걸 다 치운다. 지나간 흔적까지. 한 묶음을 챙겼다.<br>상자 밑에 장부 한 장이 깔렸다. 3번 창고 출입 인원. 들어온 수와 나간 수. 나간 수 칸이 비었다.<br><br>그 칸을 연필로 채웠다. 이쪽 무리 수만큼. 지우개는 없다.`,
        ng:`들춘 방수포 밑에서 고무장갑 한 짝이 이쪽 손목을 잡았다.<br><br>장갑만 있다. 안이 비었다. 그런데 쥔다. 떼어 냈다. 손목이 표백제에 탄 것처럼 하얗게 일어났다.<br>바퀴 소리가 돌아왔다. 무리를 데리고 안 간 쪽으로 뛰었다. 손목이 따갑다.`,
        win:{ exp:16, item:'말린 고기' }, lose:{ hp:-20, spirit:-16 } }
    ] },

  { at:'B1', t:'냉동 창고 — 어둠 속 숫자',
    x:`냉동 창고 불이 꺼졌다. 깜깜하다. 하얀 숨도 안 보인다.<br><br>
    어둠 속에서 목소리가 센다. 하나. 둘. 셋. 무리 숨소리에 맞춰. 숫자 하나마다 가까워진다.<br>
    배전반은 창고 반대편 벽에 있다고 아까 봤다. 마흔 걸음. 그 사이에 레일 기둥, 갈고리, 얼음 기둥.<br><br>
    불을 켜면 목소리는 멈춘다. 켜기 전까지는 계속 센다.`,
    o:[
      { l:'① 무력을 실어 아까 본 길을 기억대로 달린다.', k:'evade', dc:21, cost:{ might:24 },
        ok:`불이 꺼지기 전 본 것을 떠올렸다. 레일 기둥 셋, 얼음 기둥 하나, 갈고리 줄. 눈을 감고 그 순서대로 달렸다.<br><br>스물째 걸음에 갈고리가 귀 옆을 스쳤다. 고개를 숙였다. 서른째에 얼음 기둥을 손바닥으로 짚고 돌았다. 마흔째에 벽에 손이 닿았다. 배전반 손잡이를 힘껏 내렸다.<br>불이 켜졌다. 목소리가 멎었다. 무리 앞 세 걸음에 빈 고무장화 한 켤레가 서 있었다.<br><br>장화 코가 무리를 향한다. 숫자는 무리 수보다 둘 더 가 있었다.`,
        ng:`서른째 걸음에서 얼음 기둥이 생각보다 가까웠다.<br><br>어깨부터 박았다. 쓰러졌다. 목소리가 귀 옆에서 숫자 하나를 말했다. 일어나 벽을 더듬었다. 배전반 손잡이를 찾는 데 한참 걸렸다.<br>불이 켜졌을 때 어깨에 얼음 조각이 박혀 피가 났다. 무리 하나가 바닥에 쓰러져 떨고 있었다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-28, mind:-14 } },
      { l:'② 목소리 박자를 읽어 무리 숨을 멈추게 한다.', k:'sense', dc:21,
        ok:`숫자는 숨소리에 맞춰 나온다. 숨을 멈추면 숫자도 멈춘다.<br><br>손을 뻗어 무리 어깨를 하나씩 눌렀다. 숨 참으라는 뜻. 다들 멈췄다. 목소리가 멈췄다. 기다린다. 이쪽도 기다렸다.<br>목소리가 먼저 지쳤다. 마지막 숫자를 말하고 다른 쪽으로 멀어졌다. 숨을 쉬며 반대편 문으로 빠졌다.<br><br>문 밖에서 숨을 몰아쉬었다. 안에서 목소리가 다시 셌다. 하나. 무리 숨이 아니다. 다른 누구의 숨에 맞춰.`,
        ng:`숨 참으라고 눌렀는데 하나가 기침을 했다.<br><br>목소리가 빨라졌다. 숫자가 줄줄이 나왔다. 가까워졌다. 귀 옆에서 숨이 느껴진다.<br>무리를 밀어 문으로 뛰었다. 갈고리가 등을 긁었다. 외투가 찢겼다. 등도.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-24, spirit:-16 } }
    ] },

  { at:'B1', t:'야적장 — 크레인 사다리 꼭대기',
    x:`야적장이 미로다. 컨테이너 골목이 끝없이 갈라진다. 아래서는 길이 안 보인다.<br><br>
    크레인 사다리가 하늘로 뻗었다. 꼭대기 운전실에서 보면 야적장이 다 보일 것이다. 방파제로 가는 길까지.<br>
    사다리는 젖었다. 탐조등이 가끔 사다리를 비춘다. 비출 때 거기 있으면 끝이다.<br><br>
    위에서 보고 아래로 가져온다. 본 것을 머리에 넣어서.`,
    o:[
      { l:'① 사다리를 올라 길을 보고 온다.', k:'sense', dc:22,
        doom:{ title:'젖은 가로대', what:'크레인 사다리에서 떨어졌습니다', dc:17, sec:55,
          text:`사다리를 올랐다. 서른 칸, 마흔 칸. 탐조등이 아래를 지날 때 멈추고 위를 지날 때 올랐다.<br><br>운전실 바로 밑에서 탐조등이 박자를 바꿨다. 위로 올라왔다. 이쪽에 꽂혔다. 눈이 멀었다. 한 손이 가로대를 놓쳤다. 발이 미끄러졌다.<br>한 손으로 매달렸다. 아래에서 누가 사다리 밑동을 흔든다. 사다리 전체가 운다.<br><br>손가락이 하나씩 풀린다.`,
          dieText:`위에서 본 길을 아래로 가져오는 게 이쪽 일이다. 이번에는 내려오는 길이 하나뿐이었다.<br><br>탐조등이 꺼졌다.<br>야적장 바닥에 젖은 지도 한 장이 떨어져 있다. 반쯤 그려졌다.` },
        ok:`사다리를 올랐다. 탐조등이 아래를 지날 때 멈추고 위를 지날 때 올랐다. 운전실 밑에서 탐조등 박자가 바뀌었다. 이쪽은 이미 운전실 문 뒤다.<br><br>창으로 봤다. 컨테이너 골목이 다 보인다. 막힌 데, 뚫린 데, 우비들이 선 데. 방파제로 가는 길이 하나 있다. 꺾임이 일곱.<br>내려왔다. 일곱 꺾임을 손가락으로 무리에게 그려 보였다. 그대로 갔다.<br><br>마지막 꺾임에서 돌아봤다. 운전실 창에 불이 켜졌다. 이쪽이 끄고 나왔는데.`,
        win:{ exp:25, dream:3 } },
      { l:'② 컨테이너 번호를 읽어 길을 짐작한다.', k:'gaze', dc:20,
        ok:`옆면 번호를 봤다. 앞자리가 같은 것끼리 줄지어 있다. 줄은 실을 배 순서다. 해무호에 실을 줄이 방파제 쪽으로 이어진다.<br><br>그 번호만 따라갔다. 꺾일 때마다 번호가 이어진다. 무리가 이쪽 뒤에 붙어 왔다.<br>방파제 앞에 닿았다. 줄 끝 컨테이너 문이 열렸다. 안에 소금 자루가 쌓였다. 하나를 터서 소금 덩이를 챙겼다.<br><br>그 컨테이너만 앞자리가 달랐다. 다른 배에 실릴 것이다. 문 안쪽에 긁힌 자국이 있다. 안에서 긁은 자국이다.`,
        ng:`번호를 따라가다 같은 번호를 두 번 만났다.<br><br>누가 번호판을 바꿔 달았다. 따라온 길이 돌아왔다. 골목 끝에 우비 셋이 서 있다.<br>무리를 돌려 뛰었다. 컨테이너 모서리에 이마를 찧었다. 피가 눈썹을 타고 흘렀다.`,
        win:{ exp:16, item:'소금 덩이' }, lose:{ hp:-26, mind:-12 } }
    ] },

  { at:'B1', t:'정문 — 교대 시간',
    x:`항구 정문이다. 철문 위 네온이 『출입』을 깜박인다. 철문은 사슬로 감겼다. 옆 초소에 불이 켜졌다.<br><br>
    초소 안에 경비가 하나 앉았다. 04:50에 교대가 온다. 둘이 인사하는 데 숨 열.<br>
    옆 쪽문은 열쇠로 연다. 열쇠는 초소 벽에 걸렸다.<br><br>
    05:10에 해무호가 뜬다. 그 전에 나가야 한다. 시간이 없다는 걸 아는 사람은 이쪽뿐이 아니다.`,
    o:[
      { l:'① 교대 인사 틈에 먼저 지나 손짓한다.', k:'evade', dc:21,
        ok:`교대가 왔다. 초소 문이 열렸다. 둘이 인사를 한다. 숨 하나에 초소 그늘에서 벽의 열쇠를 뺐다. 숨 다섯에 쪽문을 열었다. 숨 여덟에 손짓했다.<br><br>무리가 쪽문으로 빠졌다. 숨 열에 쪽문을 닫았다. 열쇠는 쪽문 밖 자물쇠에 꽂아 두었다.<br>새 경비가 의자에 앉았다. 벽을 봤다. 열쇠가 없다. 일어나지 않았다.<br><br>그 경비는 열쇠가 없는 걸 처음 보는 얼굴이 아니었다.`,
        ng:`교대가 인사를 안 했다. 둘이 그냥 자리를 바꿨다. 숨 둘.<br><br>열쇠에 손을 뻗다 새 경비와 눈이 마주쳤다. 경비가 초소 밖으로 나왔다. 무리가 철문 쪽에서 흩어졌다.<br>경비 앞에서 반대로 뛰었다. 곤봉이 무릎 뒤를 쳤다. 넘어졌다. 기어서 컨테이너 사이로 숨었다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-26, mind:-14 } },
      { l:'② 무력을 실어 철문 경첩 핀을 뽑는다.', k:'break', dc:21, cost:{ might:26 },
        ok:`경첩 쪽을 봤다. 사슬은 새것인데 경첩은 옛것이다. 녹슬었다. 핀에 손을 걸고 힘을 실었다.<br><br>핀이 빠졌다. 둘째 핀도. 철문이 사슬에 매달린 채 경첩 쪽으로 기울었다. 사람 하나 빠질 틈이 났다.<br>무리를 하나씩 보냈다. 철문 무게를 어깨로 받친 채 버텼다. 마지막에 이쪽이 빠졌다. 철문이 내려앉으며 큰 소리를 냈다.<br><br>초소 불이 꺼졌다. 소리가 났는데도 아무도 안 나왔다. 초소가 처음부터 비어 있었는지도 모른다.`,
        ng:`핀 하나가 안 빠졌다. 녹이 붙었다.<br><br>힘을 더 실었다. 철문이 이쪽으로 기울었다. 어깨로 받았다. 무게가 등까지 내려왔다. 무릎이 꺾였다.<br>무리가 같이 받쳐 들었다. 틈은 났다. 다 빠져나왔다. 이쪽 어깨가 내려앉았다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-30, mind:-10 } },
      { l:'③ 초소 창으로 경비를 본다.', k:'gaze', dc:20,
        ok:`초소 창을 봤다. 경비가 신문을 본다. 신문이 넘어가지 않는다. 한 면만 계속 본다.<br><br>1면에 3번 창고 사진이 있다. 경비는 정문이 아니라 그 사진을 지킨다.<br>초소를 크게 돌아 철조망 끝 구멍으로 무리를 보냈다. 경비는 끝까지 고개를 안 들었다.<br><br>구멍을 지나며 봤다. 경비 발치에 양동이가 있었다. 걸레가 걸쳐졌다. 청소부가 둘인지, 하나가 옷을 바꿔 입은 건지는 모른다.`,
        ng:`창을 보다 경비와 눈이 맞았다.<br><br>경비가 신문을 접었다. 손을 들어 인사했다. 무리 수만큼 손가락을 폈다. 그리고 하나를 접었다.<br>무리를 다른 쪽으로 돌렸다. 철조망을 넘다 종아리가 찢어졌다. 경비는 안 따라왔다. 손가락을 접은 채로 기다렸다.`,
        win:{ exp:16, dream:2 }, lose:{ hp:-22, spirit:-16 } }
    ] },

  { at:'B2', t:'7층 복도 — 문마다 작은 창',
    x:`7층 복도 양옆으로 병실 문이 이어진다. 문마다 작은 창이 달렸다. 창 안에서 환자들이 밖을 본다. 다 깨어 있다.<br><br>
    깨어 있는 환자는 말이 없다. 대신 누가 지나가면 창을 두드린다. 똑. 똑. 그 소리를 하얀 모자들이 듣는다.<br>
    복도 끝까지 문이 열넷. 무리가 다 지나야 한다.<br><br>
    열 걸음 앞에서 창 하나하나를 먼저 봐야 한다. 두드릴 창과 안 두드릴 창.`,
    o:[
      { l:'① 앞서 창마다 들여다보고 무리에게 손짓한다.', k:'evade', dc:21, wake:1,
        ok:`첫 창을 봤다. 환자가 이쪽을 보고 손을 든다. 두드리려는 손이다. 손가락을 입술에 댔다. 환자가 손을 내렸다. 둘째 창은 잔다. 셋째는 등을 돌렸다.<br><br>창마다 그렇게 봤다. 두드릴 창 앞에서는 이쪽이 먼저 손가락을 입술에 댔다. 열넷 중 열하나가 손을 내렸다. 셋은 처음부터 안 두드렸다. 무리가 손짓대로 지났다.<br>복도 끝에서 돌아봤다. 창 열넷에 얼굴이 다 붙어 있다. 아무도 안 두드린다.<br><br>앞을 보는 눈이 앞에 있는 사람 속까지 먼저 갔다. 열 걸음이 문 열넷만큼 길어졌다.`,
        ng:`일곱째 창의 환자가 이쪽 손가락을 보고 웃었다. 그리고 두드렸다. 세게.<br><br>나머지 창이 다 따라 두드렸다. 복도가 울렸다. 간호사실 문이 열렸다. 하얀 모자가 나왔다.<br>무리를 데리고 뛰었다. 복도 끝 문이 잠겼다. 다른 복도로 돌았다. 모서리에 무릎을 찧었다. 두드리는 소리가 오래 따라왔다.`,
        win:{ exp:22, dream:2 }, lose:{ hp:-22, mind:-16 } },
      { l:'② 창 밑으로 기어 무리를 이끈다.', k:'hide', dc:21,
        ok:`창보다 낮게 엎드렸다. 문 밑을 기었다. 무리에게도 그렇게 하라고 손짓했다.<br><br>창 안 환자들은 위를 본다. 바닥은 안 본다. 열넷을 기어서 지났다. 왁스 냄새가 코에 찼다.<br>복도 끝에서 일어나 무리를 셌다. 맞다.<br><br>마지막 창 밑에 종이컵 하나가 놓였다. 물이 담겼다. 기어 오는 사람 마시라고 놓은 것처럼. 안 마셨다.`,
        ng:`열째 문 앞에서 무리 하나의 등이 창 높이로 올라왔다.<br><br>창 안 환자가 그걸 봤다. 두드렸다. 그 사람을 눌러 엎드리게 했다. 늦었다. 복도 끝에서 카트 바퀴 소리가 왔다.<br>다들 병실 하나로 굴러 들어갔다. 그 병실 환자가 무리를 오래 봤다. 숨을 참느라 머리가 아팠다.`,
        win:{ exp:18, dream:2 }, lose:{ mind:-16, spirit:-14 } }
    ] },

  { at:'B2', t:'비상계단 — 다시 7층',
    x:`비상계단으로 내려왔다. 한 층. 문 위 번호판에 7이라고 적혔다.<br><br>
    한 층 더 내려왔다. 7. 또 내려왔다. 7. 내려갈수록 같은 층이다.<br>
    앞서서 끝까지 가 보는 게 이쪽 일이다. 끝이 없는 계단이라면 어디가 다른지 찾는다.<br><br>
    무리는 위 층계참에 남겨 뒀다. 돌아오지 않으면 거기서 기다리라고 했다.`,
    o:[
      { l:'① 무력을 다해 계단을 끝까지 달려 내려간다.', k:'sense', dc:21, cost:{ might:25 }, wake:1,
        ok:`달려 내려갔다. 층마다 번호판을 봤다. 7, 7, 7. 일곱 번째 7에서 번호판 나사가 하나 빠져 있었다. 다른 층은 넷 다 있다.<br><br>그 층 문을 열었다. 7층 복도다. 그런데 복도 끝 창밖 가로등이 한 층만큼 가깝다. 번호판만 7로 바꿔 단 것이다.<br>올라가 무리를 데리고 왔다. 그 층으로 들어가 반대편 계단으로 내려갔다. 거기서부터는 숫자가 줄었다.<br><br>층마다 다른 데를 찾는 동안 눈이 번호판보다 나사를 먼저 봤다. 다들 같은 것을 볼 때 다른 하나를 보는 눈이 생겼다.`,
        ng:`열 번째 7에서 다리가 풀렸다.<br><br>숨이 안 돌아왔다. 계단을 헛디뎌 반 층을 굴렀다. 일어나 보니 무리가 남은 층계참이 위가 아니라 바로 아래에 있다.<br>무리가 이쪽을 올려다봤다. 같은 데를 돌고 있었다. 무릎이 다 까졌다.`,
        win:{ exp:22, dream:2 }, lose:{ hp:-26, mind:-14 } },
      { l:'② 층계참마다 남은 손톱 표식을 본다.', k:'gaze', dc:20,
        ok:`층계참 벽에 손톱으로 긁은 표식이 있다. 줄 하나. 다음 층계참에 줄 둘. 그다음에 셋. 누가 앞서 세며 내려갔다.<br><br>줄이 일곱에서 멈췄다. 그 층계참 벽에 화살표가 있다. 옆 벽 점검문을 가리킨다. 계단이 아니라 배관 통로다.<br>무리를 데리고 점검문으로 들어갔다. 배관 사다리를 타고 내려갔다. 6이라는 숫자가 처음 보였다.<br><br>일곱 줄 밑에 손톱 자국이 하나 더 있었다. 끝까지 못 그은 여덟째 줄이다.`,
        ng:`표식을 세는 사이 줄이 늘었다. 눈앞에서.<br><br>벽 안쪽에서 손톱 긁는 소리가 났다. 여덟, 아홉. 귀를 대 봤다. 안에서 누가 이쪽 귀에 숨을 불었다.<br>물러나 무리에게 돌아갔다. 머리가 울렸다. 계단을 다시 올라가는 데 한참 걸렸다.`,
        win:{ exp:18, dream:2 }, lose:{ mind:-16, spirit:-16 } }
    ] },

  { at:'B2', t:'인원 점검 — 숨 쉰과 숨 예순',
    x:`05:00 인원 점검이다. 아래층으로 가는 문은 점검 시간에만 열린다. 그 너머가 맞는 길인지 먼저 봐야 한다.<br><br>
    이쪽이 앞서 다녀오면 점검 때 무리 수가 하나 모자란다. 모자라면 문이 다 잠긴다.<br>
    점검은 병실 문 앞에 무리를 세워 놓고 센다. 하얀 모자가 복도 끝에서부터 걸어온다.<br><br>
    다녀오는 데 숨 예순. 모자가 이쪽 병실까지 오는 데 숨 쉰.`,
    o:[
      { l:'① 점검이 오기 전에 다녀온다.', k:'evade', dc:22,
        doom:{ title:'인원 점검', what:'하얀 가운들에게 붙들려 갑니다', dc:18, sec:50,
          text:`문이 열리자마자 달렸다. 아래층 계단. 한 층 내려가 문을 봤다. 열려 있다. 길이 맞다. 돌아섰다. 숨 서른.<br><br>올라왔다. 숨 쉰다섯. 복도에 들어섰다. 하얀 모자가 이쪽 병실 앞에 서 있다. 무리를 다 셌다. 하나 모자란다. 고개를 돌려 이쪽을 봤다.<br>복도 양옆에서 하얀 가운이 둘 나왔다. 이쪽 팔을 하나씩 잡았다. 무리 앞에서 이쪽을 들어 올렸다. 발이 바닥에서 떴다. 처치실 쪽으로.<br><br>모자가 무리를 다시 센다. 맞다고 한다.`,
          dieText:`먼저 가서 먼저 돌아온다. 숨 다섯이 늦었다.<br><br>점검표의 숫자가 하나 줄어 고쳐졌다. 원래 그랬던 것처럼.<br>무리는 아래층으로 내려갔다. 이쪽이 확인한 길로.` },
        ok:`문이 열리자마자 달렸다. 한 층 내려가 문을 봤다. 열려 있다. 돌아섰다. 숨 서른.<br><br>올라오는 계단에서 난간을 넘어 한 층을 바로 올랐다. 숨 마흔다섯에 병실 앞에 섰다. 무리 맨 끝에. 모자가 와서 셌다. 맞다.<br>점검이 끝나고 문이 열린 사이 무리를 데리고 내려갔다. 확인한 길로.<br><br>숨이 목까지 찼다. 무리 하나가 이쪽 등을 두드렸다. 그 손에 하얀 장갑이 끼워져 있었다. 무리는 장갑을 낀 적이 없다.`,
        win:{ exp:25, dream:3 } },
      { l:'② 가는 대신 문틈으로 아래층 소리를 같이 듣는다.', k:'bond', dc:20,
        ok:`가지 않았다. 계단 문틈에 무리 귀를 대게 했다. 아래층 소리를 같이 들었다.<br><br>물 떨어지는 소리. 바람 소리. 사람 소리는 없다. 바람이 있으면 어딘가 열렸다. 길이 맞다.<br>점검을 받았다. 맞다. 문이 열린 사이 다 같이 내려갔다.<br><br>내려가서 보니 바람은 열린 창에서 왔다. 창밖이 아직 7층 높이다. 내려왔는데. 다음 계단을 찾았다.`,
        ng:`문틈에 귀를 댄 무리 하나가 아래층에서 자기 이름을 들었다고 했다.<br><br>그 사람이 문을 열고 내려가려 했다. 붙잡았다. 뿌리쳤다. 둘이 엉켜 계단 모서리에 넘어졌다. 이쪽이 밑이었다.<br>점검 때 둘 다 겨우 줄에 섰다. 허리가 찍혀 숨 쉴 때마다 아팠다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-24, mind:-14 } }
    ] },

  { at:'B2', t:'지하 — 구급차 출구',
    x:`병원 지하다. 구급차가 드나드는 출구가 있다. 셔터가 반쯤 올라갔다. 밖에 비가 온다.<br><br>
    출구 앞에 구급차 한 대가 섰다. 뒷문이 열렸다. 들것이 하나 실렸다. 하얀 시트. 시트 밑이 사람 모양이다.<br>
    운전석은 비었다. 들것 옆에 하얀 가운이 서서 시계를 본다. 05:20 출발.<br><br>
    셔터까지 스무 걸음. 구급차 옆을 지나야 한다.`,
    o:[
      { l:'① 가운이 시계를 볼 때 먼저 지나 손짓한다.', k:'evade', dc:21,
        ok:`가운이 시계를 볼 때마다 숨 셋 동안 고개를 숙인다. 그 셋에 먼저 지났다. 셔터 밑 어둠에 섰다.<br><br>손짓했다. 다음 셋에 하나. 또 하나. 무리가 다 지날 때까지 가운은 시계만 봤다.<br>셔터 밖은 빗속이다. 담장 너머로 큰길 불빛이 보인다.<br><br>돌아봤다. 들것 시트가 조금 들려 있다. 시트 밑에서 손 하나가 셔터 쪽을 가리킨다. 아까는 안 보였다.`,
        ng:`세 번째에 가운이 시계를 안 봤다.<br><br>고개를 든 가운 앞에 무리 하나가 서 있었다. 가운이 그 사람 손목을 잡았다. 들것 쪽으로 이끈다. 뛰어 돌아가 떼어 냈다.<br>떼어 낼 때 가운 손이 이쪽 손목으로 옮겨 붙었다. 셔터 밖까지 끌고 나와서야 떨어졌다. 손목이 얼음처럼 하얗다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-20, spirit:-18 } },
      { l:'② 들것의 시트를 들춘다.', k:'gaze', dc:21,
        ok:`가운이 운전석 쪽으로 갔을 때 시트를 들췄다.<br><br>사람이다. 살아 있다. 7층에서 없어진 환자다. 침대 하나가 비었던 이유다. 눈을 뜨고 이쪽을 봤다. 입을 움직였다. 소리는 없다. 같이.<br>들것에서 일으켜 무리에 섞었다. 하나 늘었다. 셔터를 빠져나왔다.<br><br>담장 밖에서 돌아보니 그 환자가 없다. 무리는 원래 수다. 들것에 시트가 다시 사람 모양으로 덮여 있다.`,
        ng:`시트를 들추자 아무것도 없었다. 시트가 사람 모양으로 접혀 있었을 뿐이다.<br><br>시트가 이쪽 손목을 감았다. 접힌 천이 손처럼 조였다. 가운이 돌아섰다.<br>시트째 찢어 떼어 냈다. 가운이 다가오는 사이 셔터로 굴렀다. 셔터 날에 어깨를 긁혔다.`,
        win:{ exp:18, dream:2, spirit:8 }, lose:{ hp:-22, mind:-16 } },
      { l:'③ 무력을 실어 셔터를 끝까지 밀어 올린다.', k:'break', dc:20, cost:{ might:22 },
        ok:`셔터 밑에 손을 넣고 힘으로 밀어 올렸다. 모터가 버틴다. 이쪽이 더 버텼다.<br><br>셔터가 끝까지 올라가 걸쇠가 걸렸다. 무리가 한꺼번에 빠져나갔다. 가운이 돌아봤을 때는 다 빗속이다.<br>마지막에 이쪽이 빠졌다. 걸쇠를 발로 차 풀었다. 셔터가 내려오며 가운과 구급차를 안에 가뒀다.<br><br>셔터 안에서 시동 소리가 났다. 05:20. 구급차가 출발했다. 닫힌 셔터를 향해.`,
        ng:`모터가 반대로 돌았다.<br><br>셔터가 내려왔다. 손이 셔터 날과 바닥 사이에 끼었다. 빼냈다. 손가락 둘이 부었다.<br>가운이 이쪽을 봤다. 걸어온다. 무리를 데리고 반대편 계단으로 돌았다. 한 층 올라가 창으로 빠져나가는 데 한참 걸렸다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-26, mind:-12 } }
    ] },

  { at:'B3', t:'9호차 앞 — 여덟 칸',
    x:`9호차 앞이다. 맨 앞까지 여덟 칸. 칸마다 그것이 있을 수 있다. 얼굴을 바꾸는 손님.<br><br>
    척후병이 먼저 간다. 앞 칸 문 유리로 들여다보고, 돌아와 알린다. 여덟 번.<br>
    칸 사이를 오가는 데 시간이 든다. 시계는 01:30. 종착은 04:44.<br><br>
    들여다볼 때 유리에 이쪽 얼굴도 비친다. 안에서도 이쪽이 보인다.`,
    o:[
      { l:'① 앞 칸마다 먼저 보고 손짓한다.', k:'evade', dc:21, wake:1,
        ok:`8호차 문 유리 모서리로만 봤다. 얼굴 반만 비치게. 손님 넷. 다 자는 얼굴이다. 손짓했다. 무리가 왔다.<br><br>7호차. 6호차. 칸마다 그렇게 했다. 5호차에서 손님 하나가 깨어 신문을 펼쳤다. 신문 너머가 안 보인다. 손을 들어 멈췄다. 신문이 내려갈 때까지 기다렸다. 얼굴이 무리 하나와 같았다. 지붕 고리로 돌았다.<br>다섯 칸을 지나는 데 한 시간이 걸렸다.<br><br>유리 모서리에 얼굴 반만 대는 버릇이 생겼다. 반만 보이는 얼굴은 안에서 아무도 안 센다.`,
        ng:`7호차 문 유리에 얼굴을 댔다. 안에서도 누가 유리에 얼굴을 대고 있었다. 이쪽 얼굴이다.<br><br>둘이 마주 봤다. 이쪽이 먼저 물러났다. 저쪽은 안 물러났다. 문손잡이가 돌아갔다.<br>무리를 데리고 지붕 고리로 뛰었다. 빗속 지붕을 지나 한 칸을 건넜다. 미끄러져 무릎을 깼다. 시간이 많이 갔다.`,
        win:{ exp:22, dream:2 }, lose:{ hp:-24, mind:-14 } },
      { l:'② 칸마다 쓸 손짓을 미리 맞춘다.', k:'fix', dc:20,
        ok:`가기 전에 손짓을 맞췄다. 주먹은 멈춤. 손바닥은 와도 된다. 두 손가락은 지붕. 손가락 하나는 뒤로.<br><br>칸마다 들여다보고 손짓만 했다. 돌아가지 않았다. 무리가 손짓을 보고 움직였다. 오가는 시간이 반으로 줄었다.<br>4호차까지 쉬지 않고 갔다.<br><br>4호차 앞에서 돌아봤다. 무리 맨 뒤에서 누가 주먹을 들고 있다. 멈춤. 이쪽은 그 손짓을 안 했다.`,
        ng:`5호차에서 손바닥을 폈다. 무리가 왔다.<br><br>문이 열리자 손님이 깨어 있었다. 이쪽이 본 사이 깼다. 손님 얼굴이 무리를 하나씩 훑으며 바뀌었다.<br>뒤로 뛰었다. 손짓이 엉켰다. 무리 하나가 반대로 뛰었다. 붙잡으러 가다 좌석 모서리에 옆구리를 찧었다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-22, spirit:-14 } }
    ] },

  { at:'B3', t:'침대칸 — 걷힌 커튼 하나',
    x:`침대칸이다. 커튼이 다 쳐졌다. 하나만 걷혔다. 걷힌 침대가 비었다. 베개가 움푹하다.<br><br>
    그것이 거기 있었다. 지금은 어딘가 다른 커튼 안에 있다. 다른 얼굴로.<br>
    지나간 것은 흔적을 남긴다. 바닥, 커튼, 손잡이. 어디로 갔는지가 남는다.<br><br>
    통로 끝 차장실 문이 잠겼다. 그 너머가 앞 칸이다.`,
    o:[
      { l:'① 바닥과 커튼 자국으로 그것이 든 침대를 찾는다.', k:'gaze', dc:21,
        ok:`통로 카펫이 젖었다. 젖은 발자국이 걷힌 침대에서 나와 셋째 침대 앞에서 끊겼다. 셋째 커튼 아래 끝이 젖었다.<br><br>셋째 침대 앞을 비켜, 무리를 반대쪽 줄로 붙여 지나게 했다. 커튼은 안 움직였다. 안에서 숨소리가 났다. 박자가 무리 하나와 같다.<br>차장실 앞에 닿았다.<br><br>걷힌 침대 베개 밑에 산나물 한 묶음이 있었다. 식당칸 주방 것이다. 그것도 먹기는 하는 모양이다.`,
        ng:`셋째에서 끊긴 줄 알았던 발자국이 다섯째에서도 끊겼다. 둘 다 젖었다.<br><br>고르다 시간이 갔다. 다섯째 커튼이 걷혔다. 손이 나와 무리 하나의 외투를 잡았다.<br>당겨서 떼어 냈다. 단추가 뜯겼다. 손이 단추를 쥐고 들어갔다. 커튼 안에서 단추를 세는 소리가 났다.`,
        win:{ exp:18, item:'산나물' }, lose:{ mind:-16, spirit:-16 } },
      { l:'② 무력을 실어 차장실 문을 비틀어 연다.', k:'break', dc:21, cost:{ might:24 },
        ok:`차장실 문손잡이를 두 손으로 쥐었다. 힘을 실어 비틀었다. 자물쇠 혀가 안에서 휘었다.<br><br>문이 열렸다. 아무도 없다. 옷장에 차장 옷이 여러 벌 걸렸다. 다 젖었다. 체격이 다 다르다.<br>차장실을 지나 앞 칸 문으로 나갔다. 무리가 따라왔다.<br><br>나가면서 옷장을 다시 봤다. 한 벌 늘었다. 이쪽 체격이다.`,
        ng:`비트는 소리가 컸다.<br><br>커튼 몇 개가 동시에 걷혔다. 손님들이 내다봤다. 얼굴이 다 같다. 차장 얼굴이다.<br>문이 열렸다. 다들 차장실로 뛰어들었다. 문을 닫고 등으로 버텼다. 바깥에서 밀었다. 한참 버티다 손목이 꺾였다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-26, mind:-12 } }
    ] },

  { at:'B3', t:'식당칸 창 — 서지 않는 역',
    x:`식당칸 창밖으로 역이 다가온다. 서지 않는 역이다. 승강장에 우산 쓴 사람 하나가 서 있다.<br><br>
    창이 그 사람 앞을 지날 때 그 사람은 늘 같은 창을 본다. 아까 역에서도 같은 사람이 서 있었다.<br>
    역 이름판이 지나간다. 승강장 기둥에 무언가 적혔다. 다음 역 이름이 아니다. 숫자다.<br><br>
    지나가는 것도 봐야 한다. 놓치면 다시 안 온다.`,
    o:[
      { l:'① 창을 열고 몸을 내밀어 기둥 숫자를 읽는다.', k:'sense', dc:22,
        doom:{ title:'승강장의 우산', what:'창밖으로 끌려 나갔습니다', dc:18, sec:45,
          text:`창을 열고 몸을 내밀었다. 빗바람이 얼굴을 친다. 기둥이 지나간다. 숫자를 읽었다. 04, 4—<br><br>승강장의 우산이 바로 앞에 있었다. 우산 밑에서 손이 나와 이쪽 손목을 잡았다. 기차는 달린다. 손은 안 놓는다. 몸이 창틀 밖으로 끌려 나간다. 허리까지.<br>무리가 이쪽 다리를 잡았다. 창틀이 배를 누른다. 승강장 끝이 다가온다. 끝에는 벽이 있다.<br><br>우산 밑 얼굴이 웃는다. 이쪽 얼굴로.`,
          dieText:`지나가는 것은 다시 안 온다. 이쪽도.<br><br>식당칸 창 하나가 열린 채 빗물이 들이친다.<br>다음 역 승강장에 우산 쓴 사람이 둘 서 있었다.` },
        ok:`창을 반만 열고 이마만 댔다. 몸은 안 내밀었다. 기둥이 지나간다. 숫자를 읽었다. 04 43.<br><br>승강장의 우산이 창 앞을 지났다. 우산 밑에서 손이 나와 창틀을 쳤다. 이마 바로 앞이다. 반만 연 창이 손을 막았다.<br>창을 닫았다. 숫자를 무리에게 말했다. 04:43. 내릴 시각이다. 종착 1분 전.<br><br>이마에 맺힌 물을 닦았다. 손바닥에 묻은 건 빗물이 아니라 분필 가루다.`,
        win:{ exp:25, dream:3 } },
      { l:'② 승강장 우산의 사람을 본다.', k:'gaze', dc:20,
        ok:`창 안에서 그 사람을 봤다. 역마다 같은 사람이다. 같은 우산, 같은 자리. 기차보다 먼저 다음 역에 가 있다.<br><br>그 사람이 보는 창을 봤다. 맨 앞 칸 창이다. 이쪽이 아니라 기관실을 본다. 기관실에 무엇이 있는지 아는 사람이다.<br>무리에게 말했다. 맨 앞에 내리는 문이 있다면 저 사람도 거기서 기다린다고.<br><br>다음 역에 그 사람이 없었다. 처음으로. 이제 기차 안에 있다는 뜻이다.`,
        ng:`보는 사이 그 사람이 우산을 들어 얼굴을 보였다.<br><br>무리 하나의 얼굴이다. 그 무리는 옆에 앉아 있다. 같은 얼굴이 하나는 창밖에서, 하나는 옆에서 이쪽을 봤다.<br>옆의 무리가 진짜인지 확인하는 데 한참 걸렸다. 진짜였다. 머리가 깨질 듯 아팠다.`,
        win:{ exp:18, dream:2 }, lose:{ mind:-16, spirit:-18 } }
    ] },

  { at:'B3', t:'맨 앞 칸 — 먼저 내리는 자리',
    x:`맨 앞 칸이다. 내리는 문이 있다. 04:42. 선로가 휘는 데가 곧 온다.<br><br>
    누가 먼저 내려야 한다. 내려서 둑이 어떤지 보고, 손을 흔들어 알려야 한다. 비 오는 둑은 자갈인지 풀인지 물인지 모른다.<br>
    먼저 내리는 사람은 혼자다. 늘 그렇듯.<br><br>
    기관실 문 너머에서 누가 기적 줄을 잡았다. 기적이 길게 운다. 무리에게 하는 인사다.`,
    o:[
      { l:'① 먼저 뛰어내려 둑을 보고 신호한다.', k:'evade', dc:22, wake:1,
        ok:`휘는 데가 왔다. 먼저 뛰었다. 굴렀다. 자갈이다. 둑 위로 다섯 걸음 기어 올랐다. 풀이다. 풀 쪽에 섰다.<br><br>손을 흔들었다. 오른쪽. 풀. 무리가 하나씩 뛰었다. 이쪽 손이 가리킨 데로 굴렀다. 다 풀에 떨어졌다.<br>꼬리등이 빗속으로 멀어진다. 무리를 셌다. 맞다.<br><br>먼저 내린 혼자가 외롭지 않았다. 뒤에 올 사람들 자리를 먼저 밟는 게 이쪽 몫이라는 걸 몸이 받아들였다. 열 걸음 앞이 무섭지 않은 자리가 됐다.`,
        ng:`뛰었다. 굴렀다. 자갈 밑이 물이었다. 배수로다. 빠졌다. 물이 빠르다.<br><br>기어 올라 손을 흔들었다. 늦었다. 무리 하나가 이미 배수로 쪽으로 뛰었다. 그 사람을 붙잡았다. 둘이 같이 쓸려 갈 뻔했다.<br>풀숲에 닿았다. 둘 다 물을 많이 먹었다. 무릎이 자갈에 다 갈렸다.`,
        win:{ exp:24, dream:3 }, lose:{ hp:-32, mind:-12 } },
      { l:'② 무력을 실어 비상 손잡이를 당겨 기차를 늦춘다.', k:'break', dc:21, cost:{ might:26 },
        ok:`문 옆 비상 손잡이를 잡았다. 녹슬어 안 내려간다. 힘을 다 실어 당겼다.<br><br>쇳소리가 났다. 바퀴가 비명을 질렀다. 기차가 느려진다. 서지는 않는다. 사람 뛰는 만큼 느려졌다.<br>그 속도에 무리를 내보냈다. 걷듯이 내렸다. 이쪽이 마지막이다. 손잡이를 놓는 순간 기차가 다시 빨라졌다. 뛰어내렸다.<br><br>기관실 창에서 누가 내다봤다. 손잡이를 당긴 손을 보고 고개를 끄덕였다. 기억해 두겠다는 듯이.`,
        ng:`손잡이가 끊어졌다. 손에 쇠 막대만 남았다.<br><br>시간이 갔다. 휘는 데를 지났다. 곧은 선로에서 뛰어야 했다. 이쪽이 먼저 뛰었다. 다섯 바퀴를 굴렀다.<br>무리는 이쪽이 구른 자리를 보고 따라 뛰었다. 다들 다쳤다. 이쪽 어깨가 빠졌다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-30, spirit:-12 } },
      { l:'③ 기관실 문을 막고 무리를 먼저 보낸다.', k:'steady', dc:21,
        ok:`기관실 문이 안에서 열리려 한다. 어깨로 막았다. 무리에게 턱짓했다. 먼저 가라.<br><br>무리가 하나씩 뛰어내렸다. 문 너머 미는 힘이 세진다. 버텼다. 문틈으로 손가락이 나와 이쪽 어깨를 더듬는다.<br>마지막 무리가 뛰었다. 문을 놓고 뛰었다. 등 뒤에서 문이 벌컥 열렸다. 이미 허공이다.<br><br>풀숲에서 일어났다. 무리가 이쪽을 기다리고 있었다. 이번에는 이쪽이 맨 뒤였다. 척후병이 맨 뒤에 오는 날도 있다.`,
        ng:`문 너머 힘이 이쪽보다 셌다.<br><br>문이 열렸다. 밀려 넘어졌다. 문 너머에서 누가 이쪽 발목을 잡았다. 무리 하나가 돌아와 그 손을 걷어찼다.<br>둘이 같이 뛰어내렸다. 늦었다. 곧은 데였다. 다들 다쳤다. 발목에 손자국이 시퍼렇게 남았다.`,
        win:{ exp:18, dream:2, hp:8 }, lose:{ hp:-28, spirit:-14 } }
    ] }
]);

// ── 투우사 (matador) · 무력 ──────────────────
kJob('matador', 'B', [
  { at:'B', t:'좁은 골목 — 달려드는 차',
    x:`좁은 골목이다. 차 한 대가 겨우 지나는 폭. 골목 끝에서 전조등이 켜졌다.<br><br>
    엔진이 운다. 바퀴가 젖은 바닥에서 한 번 헛돈다. 그리고 온다. 똑바로.<br>
    양옆은 벽이다. 차 폭이 골목 폭이다. 비킬 데는 골목 중간 전봇대 뒤 한 뼘뿐이다.<br><br>
    투우사는 달려드는 것을 피하지 않는다. 지나가게 한다. 지나갈 자리를 정해 줄 뿐이다.`,
    o:[
      { l:'① 천을 흔들어 부르고 마지막 반 걸음에 전봇대 뒤로 든다.', k:'evade', dc:21, wake:1,
        ok:`골목 한가운데 섰다. 천을 펼쳤다. 전조등이 천을 비춘다. 차가 천을 향해 왔다.<br><br>마지막 다섯 걸음. 운전석이 천만 본다. 셋. 천을 전봇대 쪽으로 뺐다. 이쪽은 반 걸음 그 뒤로 들었다. 차가 천을 따라 핸들을 꺾었다. 전봇대에 박혔다.<br>보닛에서 김이 오른다. 운전석 문이 안 열린다.<br><br>천을 거두며 알았다. 사람이 모는 것도 마지막엔 천을 본다. 운전대를 쥔 손이 눈을 따라간다. 이제 이쪽은 상대의 손까지 같이 본다.`,
        ng:`셋에서 천을 뺐다. 운전석은 천을 안 봤다. 이쪽 발을 봤다.<br><br>차가 이쪽으로 꺾었다. 전봇대 뒤로 몸을 밀어 넣었다. 사이드미러가 허리를 쳤다. 벽에 튕겼다.<br>차는 골목 끝에서 섰다. 후진등이 켜졌다. 기어서 담을 넘었다. 허리가 펴지지 않는다.`,
        win:{ exp:22, dream:2 }, lose:{ hp:-30, mind:-10 } },
      { l:'② 무력을 실어 쇠 수거함을 골목 한가운데로 민다.', k:'steady', dc:21, cost:{ might:25 },
        ok:`벽에 붙은 쇠 수거함을 어깨로 밀었다. 바퀴가 녹슬었다. 힘으로 밀었다. 골목 한가운데로 비스듬히.<br><br>차가 수거함을 들이받았다. 수거함이 차 앞에 걸렸다. 차가 수거함을 밀며 온다. 느려졌다. 그 사이 옆 문틈으로 빠졌다.<br>문틈 안은 식당 뒷문이다. 선반에 소금 덩이가 쌓였다. 하나를 챙겼다.<br><br>밖에서 차가 수거함을 끝까지 밀고 가 골목 끝 벽에 박는 소리가 났다. 수거함은 투우사보다 몸이 단단하다.`,
        ng:`수거함이 반만 움직였다.<br><br>차가 수거함 모서리를 치고 튕겨 이쪽으로 왔다. 범퍼가 정강이를 쳤다. 넘어졌다. 바퀴가 손가락 앞을 지나갔다.<br>일어나 문틈으로 기어 들어갔다. 정강이가 부어 신발이 안 들어간다.`,
        win:{ exp:18, item:'소금 덩이' }, lose:{ hp:-28, spirit:-12 } }
    ] },

  { at:'B', t:'지하 격투장 — 잠긴 철망 문',
    x:`지하 격투장이다. 철망 울타리 안에 이쪽이 섰다. 밖에서 사람들이 돈을 건다. 연기와 땀 냄새.<br><br>
    맞은편에서 사내가 걸어 나온다. 이쪽보다 머리 둘이 크다. 땅을 발로 긁는다. 뛰기 전에 하는 짓이다.<br>
    여기 데려온 사람이 출구를 잠갔다. 이기면 열어 준다고 했다. 그 사람 손에 열쇠가 없다.<br><br>
    투우사는 큰 것을 이기지 않는다. 지나가게 해서 지치게 한다.`,
    o:[
      { l:'① 천으로 불러 철망 쪽으로 계속 지나가게 한다.', k:'evade', dc:21,
        ok:`천을 펼쳤다. 사내가 왔다. 반 걸음 비켰다. 사내가 천을 따라 철망에 부딪혔다. 철망이 출렁였다.<br><br>또 왔다. 또 비켰다. 철망. 다섯 번. 사내 숨이 거칠어졌다. 여섯째에 사내가 철망에 기대 주저앉았다. 관객들이 야유했다.<br>철망 문 쪽으로 걸었다. 사내가 부딪혀 휜 철망 틈이 문 옆에 났다. 그 틈으로 나왔다.<br><br>나오며 데려온 사람을 봤다. 웃고 있다. 이쪽에 건 사람은 그 사람 하나였다.`,
        ng:`셋째에 사내가 천을 안 따라왔다. 한 박자 멈췄다. 이쪽이 비킨 쪽으로.<br><br>어깨에 받혔다. 철망에 등부터 박혔다. 사내가 다시 왔다. 바닥을 굴러 피했다.<br>일행이 철망을 흔들어 사내를 끌었다. 그 사이 틈으로 끌려 나왔다. 갈비가 결린다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-30, mind:-12 } },
      { l:'② 무력을 실어 받고, 그 힘째 등 뒤로 넘긴다.', k:'steady', dc:22, cost:{ might:26 },
        ok:`사내가 왔다. 비키지 않았다. 몸을 낮추고 사내 어깨를 두 손으로 받았다. 받는 순간 반 바퀴 돌았다. 사내 무게가 이쪽 등을 넘어갔다.<br><br>사내가 철망 문에 머리부터 박혔다. 문 경첩이 떨어져 나갔다. 사내는 일어나지 않았다.<br>떨어진 문으로 걸어 나왔다. 팔이 다 떨린다.<br><br>관객석이 조용하다. 데려온 사람이 주머니에서 열쇠를 꺼내 바닥에 떨어뜨렸다. 처음부터 주머니에 있었다.`,
        ng:`받았는데 사내가 더 무거웠다.<br><br>밀렸다. 철망에 끼었다. 사내 어깨가 가슴을 누른다. 숨이 안 쉬어진다. 천을 사내 얼굴에 씌웠다. 사내가 물러났다.<br>그 틈에 빠져나와 철망을 넘었다. 가슴뼈 쪽에서 소리가 났다.`,
        win:{ exp:22, dream:2 }, lose:{ hp:-32, mind:-12 } },
      { l:'③ 잠긴 문을 등지고 서서 사내를 문으로 부른다.', k:'luck', dc:21,
        ok:`철망 문에 등을 대고 섰다. 천을 흔들었다. 사내가 왔다. 마지막 걸음에 옆으로 빠졌다.<br><br>사내가 문을 들이받았다. 자물쇠가 튕겨 나갔다. 문이 열리며 사내가 관객석 쪽으로 굴러 나갔다.<br>관객들이 흩어졌다. 소란 속에 일행과 같이 열린 문으로 나왔다.<br><br>계단을 오르며 돌아봤다. 사내가 데려온 사람을 들이받고 있었다. 천은 이쪽 손에 있는데.`,
        ng:`사내가 문 앞에서 멈췄다. 문이 아니라 이쪽을 노렸다.<br><br>옆으로 빠지는 발목을 잡았다. 들어 올려 바닥에 내리쳤다. 숨이 끊겼다.<br>일행이 철망 밖에서 의자를 던졌다. 사내가 돌아본 사이 기어서 빠졌다. 등과 뒤통수가 울렸다.`,
        win:{ exp:18, dream:3 }, lose:{ hp:-34, spirit:-12 } }
    ] },

  { at:'B', t:'폐공장 마당 — 풀린 개 셋',
    x:`폐공장 마당이다. 사슬 풀리는 소리가 셋 났다. 개 세 마리가 어둠에서 나온다. 짖지 않는다.<br><br>
    셋이 동시에 안 온다. 하나가 앞, 둘이 양옆. 앞의 것이 덤비면 옆의 것이 다리를 문다. 사람 잡는 법을 배운 개들이다.<br>
    마당 끝 철문까지 서른 걸음. 문은 열렸다.<br><br>
    하나가 오는 건 지나가게 할 수 있다. 셋을 한꺼번에 보내려면 셋이 한 줄이어야 한다.`,
    o:[
      { l:'① 천을 땅에 끌어 셋을 한 줄로 모은다.', k:'evade', dc:21, wake:1,
        ok:`천을 땅에 끌었다. 천이 젖은 땅을 쓸며 움직인다. 개들이 천을 봤다. 사람보다 낮은 데서 움직이는 것.<br><br>천을 왼쪽으로 끌었다. 양옆의 둘이 천 쪽으로 붙었다. 셋이 천 뒤로 줄을 섰다. 천을 들어 올리며 오른쪽으로 크게 뺐다. 셋이 줄줄이 천을 따라 공장 벽 쪽으로 지나갔다.<br>그 사이 철문까지 갔다. 문을 닫았다. 셋이 문 너머에서 천만 본다.<br><br>천을 끌 때 손목이 셋을 한꺼번에 데려왔다. 하나를 지나가게 하던 손이 여럿을 한 줄로 세웠다.`,
        ng:`천을 끌었는데 옆의 하나가 천을 안 봤다.<br><br>이쪽 다리를 봤다. 뛰어들었다. 종아리를 물렸다. 천을 그 머리에 씌웠다. 떨어졌다. 나머지 둘이 동시에 왔다.<br>다리를 끌며 철문까지 뛰었다. 문을 닫다 손가락이 끼었다. 종아리 피가 신발로 흘러들었다.`,
        win:{ exp:22, dream:2 }, lose:{ hp:-30, mind:-12 } },
      { l:'② 녹슨 트럭 짐칸에 올라 개들을 다른 데로 보낸다.', k:'sense', dc:20,
        ok:`마당 구석 트럭 짐칸에 뛰어올랐다. 개들이 짐칸 둘레를 돈다. 뛰어오르지는 못한다.<br><br>짐칸 방수포 밑에 말린 고기 상자가 있다. 개 먹이다. 한 덩이를 마당 반대편으로 던졌다. 둘이 갔다. 하나가 남았다. 또 던졌다. 남은 하나도 갔다.<br>짐칸에서 내려 철문으로 걸었다. 말린 고기 한 덩이는 챙겼다.<br><br>상자 송장의 날짜가 오늘이다. 개들은 오늘 밥을 못 먹고 풀린 것이다.`,
        ng:`짐칸 바닥이 녹슬어 꺼졌다.<br><br>한 발이 빠졌다. 개 하나가 그 발을 물었다. 다른 발로 걷어찼다. 떨어졌다.<br>짐칸 위에서 오래 기다렸다. 개들은 안 지쳤다. 일행이 공장 안에서 소리를 내 끌어 줄 때까지. 발목에 이빨 자국이 깊다.`,
        win:{ exp:16, item:'말린 고기' }, lose:{ hp:-26, spirit:-14 } }
    ] },

  { at:'B', t:'뒷골목 — 낮게 쥔 칼',
    x:`뒷골목 끝에서 남자가 막아섰다. 외투 안에서 손이 나왔다. 칼이 젖은 네온을 받아 번쩍인다.<br><br>
    남자는 말이 없다. 칼끝을 낮게 쥐었다. 찌르는 사람이 쥐는 법이다. 휘두르는 사람과 다르다.<br>
    찌르기 직전에는 어깨가 먼저 내려간다. 소가 머리를 숙이는 것처럼.<br><br>
    천은 회색이다. 칼은 천을 지나도 멈추지 않는다.`,
    o:[
      { l:'① 어깨가 내려가는 순간 천으로 칼을 감아 흘린다.', k:'evade', dc:22,
        doom:{ title:'칼', what:'칼에 찔렸습니다', dc:17, sec:50,
          text:`어깨를 봤다. 내려갔다. 천을 칼 쪽으로 내밀었다. 천이 칼을 감았다.<br><br>칼이 천을 뚫었다. 천은 칼을 감았지만 손목은 못 감았다. 칼끝이 옆구리로 들어왔다. 차갑다. 그다음에 뜨겁다.<br>남자가 칼을 뺐다. 무릎이 꺾였다. 손으로 옆구리를 눌렀다. 손가락 사이로 따뜻한 것이 샌다.<br><br>남자는 칼을 외투에 닦고 다시 쥐었다. 서두르지 않는다.`,
          dieText:`천은 지나가게 한다. 칼은 지나가면서 남는다.<br><br>골목 바닥에 회색 천이 떨어졌다. 빗물이 그 위에 고인다.<br>남자의 발소리가 골목을 나간다. 다음 골목으로.` },
        ok:`어깨를 봤다. 내려갔다. 천을 칼 쪽이 아니라 남자 눈 쪽으로 펼쳤다. 칼은 눈이 본 데로 간다.<br><br>칼이 천을 뚫었다. 이쪽 몸 반 뼘 옆이다. 천으로 남자 손목째 칼을 감았다. 비틀었다. 칼이 떨어졌다. 발로 차서 하수구로 보냈다.<br>남자가 빈손으로 이쪽을 봤다. 돌아서 갔다. 칼이 없는 사람은 서두른다.<br><br>천에 구멍이 났다. 구멍 둘레가 젖었다. 빗물이다. 이번에는.`,
        win:{ exp:25, dream:3 } },
      { l:'② 천을 던져 눈을 가리고 반대로 뛴다.', k:'luck', dc:21,
        ok:`천을 남자 얼굴로 던졌다. 펼쳐지며 날았다. 남자가 칼로 천을 갈랐다. 그 반 숨에 돌아서 뛰었다.<br><br>골목 둘을 꺾었다. 남자는 안 쫓았다. 찌르는 사람은 쫓는 걸 싫어한다. 다음에 기다리면 된다.<br>천은 잃었다. 새로 구할 것이다.<br><br>골목 끝 철문에 갈라진 천 조각 하나가 걸려 있다. 이쪽 천이다. 남자가 이쪽보다 먼저 여기 왔다는 뜻이다. 다른 길로 갔다.`,
        ng:`천이 펼쳐지지 않고 뭉쳐 떨어졌다.<br><br>칼끝이 이쪽 팔을 그었다. 돌아서 뛰었다. 골목이 끝나지 않는다. 피가 손끝으로 떨어진다.<br>세 번째 골목에서 일행을 만났다. 남자는 거기서 멈췄다. 팔에 감은 천 쪼가리가 금방 젖었다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-30, mind:-12 } }
    ] },

  { at:'B', t:'공사장 — 돌아오는 철골',
    x:`짓다 만 건물이다. 크레인에 철골 하나가 매달렸다. 바람에 흔들린다. 크게. 이 층을 쓸고 지나간다.<br><br>
    쓸고 지나가는 자리가 이 층을 건너는 길이다. 다른 길은 계단인데 계단으로 사람들이 올라온다.<br>
    철골은 소처럼 같은 데로 온다. 다만 돌아온다. 갔다가, 돌아오고, 또 간다.<br><br>
    지나가게 하는 건 익숙하다. 돌아오는 건 처음이다.`,
    o:[
      { l:'① 철골이 지나간 직후 그 뒤를 따라 건넌다.', k:'evade', dc:21,
        ok:`철골이 왔다. 기다렸다. 코앞을 지나갔다. 바람이 얼굴을 쳤다. 지나간 순간 그 뒤를 따라 뛰었다.<br><br>철골이 끝까지 가서 멈췄다. 돌아온다. 이쪽은 아직 반이다. 엎드렸다. 철골이 등 위 한 뼘을 지나갔다. 다시 뛰었다. 건넜다.<br>건너편 기둥 뒤에 섰다. 계단 쪽 사람들이 그 흔들림 앞에서 멈췄다.<br><br>철골 끝 갈고리에 외투 하나가 걸려 있다. 누가 먼저 건너려다 남긴 것이다.`,
        ng:`돌아오는 박자를 잘못 셌다.<br><br>반에서 철골이 돌아왔다. 엎드리기 전에 왔다. 어깨를 스쳤다. 몸이 돌며 바닥에 내동댕이쳐졌다.<br>기어서 건넜다. 어깨가 안 올라간다. 계단 쪽에서 손전등이 이쪽을 찾았다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-32, mind:-10 } },
      { l:'② 무력을 실어 철골 끝에 매달려 흔들림을 죽인다.', k:'steady', dc:22, cost:{ might:27 },
        ok:`철골이 끝까지 가서 멈추는 순간이 있다. 그 순간 철골 끝에 매달렸다. 무게를 반대로 실었다.<br><br>철골이 덜 돌아왔다. 셋째에 거의 멈췄다. 팔이 빠질 것 같다. 일행에게 손짓했다. 건너라.<br>일행이 다 건넜다. 놓았다. 철골이 다시 흔들렸다. 그 흔들림을 타고 건너편에 내렸다.<br><br>계단 쪽 사람들이 그 흔들림 앞에서 멈췄다. 철골이 이쪽 편이 됐다.`,
        ng:`매달렸는데 철골이 생각보다 무거웠다.<br><br>안 멈췄다. 이쪽을 매단 채 돌아갔다. 허공을 지나 반대편 기둥에 이쪽이 먼저 부딪혔다.<br>떨어져서 바닥을 굴렀다. 일행이 끌어 기둥 뒤로 데려갔다. 등이 시퍼렇다.`,
        win:{ exp:22, dream:2 }, lose:{ hp:-30, spirit:-12 } },
      { l:'③ 천을 철골 갈고리에 걸어 계단 쪽 눈을 끈다.', k:'luck', dc:21,
        ok:`철골이 오는 순간 천을 그 끝 갈고리에 걸었다. 천이 펄럭이며 철골을 따라갔다.<br><br>계단으로 올라온 사람들이 펄럭이는 천을 봤다. 손전등을 비췄다. 사람이 매달린 줄 알았다. 다들 철골 끝을 따라 고개를 돌렸다.<br>그 사이 일행과 반대편 비계로 내려갔다.<br><br>천은 두고 왔다. 아직 펄럭인다. 크레인 꼭대기에서 누가 천을 감아올리는 게 보였다.`,
        ng:`천이 갈고리에 안 걸렸다.<br><br>손에 남은 천이 철골 바람에 당겨졌다. 끌려갈 뻔했다. 놓았다. 천이 날아갔다. 이쪽은 바닥에 넘어졌다. 계단 손전등이 이쪽을 찾았다.<br>일행과 비계로 뛰었다. 비계 파이프에 이마를 찧었다. 천 없이 맨손이다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-24, mind:-14 } }
    ] },

  { at:'B', t:'호텔 로비 — 도는 문',
    x:`호텔 로비 회전문이 돈다. 누가 바깥에서 세게 밀었다. 빠르게 돈다. 유리 날개 넷.<br><br>
    로비 안쪽에서 정장 둘이 이쪽으로 걸어온다. 회전문만 나가면 빗속이다.<br>
    도는 날개는 소처럼 같은 데로 온다. 다만 넷이다. 쉬지 않는다.<br><br>
    들어가는 박자는 하나다. 놓치면 날개가 이쪽을 유리에 누른다.`,
    o:[
      { l:'① 날개 박자에 맞춰 들어가 반 바퀴만 돈다.', k:'evade', dc:21, wake:1,
        ok:`날개 넷이 지나가는 걸 셌다. 하나, 둘, 셋, 넷. 다섯째가 지나간 바로 뒤에 들었다. 날개 사이 칸에 섰다.<br><br>날개가 등을 민다. 밀리는 대로 걸었다. 반 바퀴. 바깥이 열렸다. 나왔다. 뒤에서 정장 하나가 회전문에 들었다. 박자가 틀렸다. 날개가 그를 유리에 눌렀다. 돌던 문이 멈췄다.<br>빗속을 걸었다. 안 돌아봤다.<br><br>오는 것에 등을 맡긴 건 처음이다. 정면만 지키던 몸이 미는 것의 박자에는 등을 줘도 된다는 걸 알았다.`,
        ng:`다섯째 뒤에 들었다. 넷째가 덜 지나갔다.<br><br>날개 끝이 어깨를 쳤다. 칸 안에서 유리에 눌렸다. 숨이 막혔다. 문이 이쪽을 끼운 채 돈다.<br>바깥이 열렸을 때 굴러 나왔다. 어깨와 얼굴이 유리에 쓸렸다. 정장 둘이 회전문 앞에서 이쪽을 봤다.`,
        win:{ exp:22, dream:2 }, lose:{ hp:-26, mind:-14 } },
      { l:'② 화분 뒤 꺼진 비상구로 돌아간다.', k:'sense', dc:20,
        ok:`회전문을 버리고 로비 옆을 봤다. 화분 뒤에 비상구 표시. 불이 꺼졌다. 꺼진 표시를 찾는 사람은 없다.<br><br>그쪽으로 걸었다. 정장 둘은 회전문 쪽으로 갔다. 이쪽이 그리로 나갈 줄 알고.<br>비상구 문을 열었다. 주방 뒷골목이다. 산나물 상자가 비를 맞고 있다. 한 줌 챙겼다.<br><br>회전문이 계속 돈다. 정장 하나가 그 앞에서 박자를 세고 있다.`,
        ng:`비상구 문이 잠겼다. 안쪽에 사슬.<br><br>돌아섰다. 정장 하나가 바로 앞이다. 주먹이 명치로 왔다. 막다 팔뚝을 맞았다. 밀치고 회전문으로 뛰었다. 날개에 부딪히며 나왔다.<br>팔뚝이 퉁퉁 부었다.`,
        win:{ exp:16, item:'산나물' }, lose:{ hp:-24, spirit:-12 } }
    ] },

  { at:'B', t:'옥상 끝 — 등 뒤의 목소리',
    x:`옥상이다. 일행이 한 명씩 사다리로 옆 건물에 넘어간다. 이쪽이 마지막이다.<br><br>
    사다리 앞에 섰다. 등 뒤에 누가 섰다. 일행 목소리로 먼저 가라고 한다. 일행은 이미 다 건너갔다.<br>
    투우사는 등을 보이지 않는다. 등 뒤의 것은 밀 데를 찾는다. 사다리 위가 미는 데다.<br><br>
    돌아서면 정면이다. 정면이면 오는 게 보인다.`,
    o:[
      { l:'① 돌아서 정면을 지키며 뒷걸음으로 사다리를 건넌다.', k:'steady', dc:21,
        ok:`돌아섰다. 정면에 일행 얼굴이 있다. 웃는다. 그 얼굴을 보며 뒷걸음으로 사다리에 올랐다. 발로 가로대를 더듬었다.<br><br>얼굴이 사다리 끝에 섰다. 사다리에 손을 댔다. 이쪽은 얼굴만 봤다. 눈을 안 뗐다. 손이 사다리에서 떨어졌다.<br>건너편에 닿았다. 사다리를 당겨 거뒀다.<br><br>건너편 옥상의 얼굴은 이쪽이 사다리를 거둘 때까지 웃고 있었다. 정면에서 보는 얼굴은 미는 손을 못 쓴다.`,
        ng:`뒷걸음질에 발이 가로대를 헛디뎠다.<br><br>사다리가 기울었다. 얼굴이 손을 뻗어 사다리를 잡아 바로 세웠다. 고마웠다. 그리고 놓았다.<br>사다리 끝이 건너편 난간에서 미끄러졌다. 매달렸다. 건너편 일행이 끌어 올렸다. 손바닥이 가로대에 다 찢어졌다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-26, mind:-14 } },
      { l:'② 등을 보여 덤비게 하고 마지막에 비킨다.', k:'evade', dc:22,
        doom:{ title:'등 뒤', what:'옥상에서 밀려 떨어졌습니다', dc:18, sec:45,
          text:`일부러 등을 보였다. 오는 소리를 들으려고. 사다리 앞에 섰다.<br><br>왔다. 들었다. 비켰다. 그런데 등 뒤의 것도 비켰다. 이쪽이 비킬 쪽으로. 손이 이쪽 등을 밀었다. 가볍게.<br>발이 옥상 끝을 넘었다. 손이 사다리 끝을 잡았다. 사다리가 이쪽 무게에 기울었다. 아래는 골목이다. 일곱 층.<br><br>등 뒤의 것이 사다리 끝에 쭈그려 앉았다. 이쪽 손가락을 본다.`,
          dieText:`등을 보이지 않는 데는 이유가 있었다.<br><br>사다리가 골목으로 떨어지는 소리가 났다. 한참 뒤에.<br>옥상에 일행 얼굴을 한 것이 서서 아래를 내려다본다. 그리고 건너편 일행에게 손을 흔든다.` },
        ok:`일부러 등을 보였다. 오는 소리를 들었다. 비키지 않았다. 천을 등 뒤로 늘어뜨렸다.<br><br>손이 천을 밀었다. 천이 사다리 너머로 날았다. 손 주인이 천을 따라 한 걸음 더 나왔다. 옥상 끝에서 몸이 기울었다. 이쪽이 그 옷깃을 잡아 세웠다.<br>얼굴을 마주 봤다. 일행 얼굴이 흐려졌다. 그 사이 사다리를 건넜다.<br><br>천은 골목으로 떨어졌다. 나중에 찾았다. 천 위에 손자국이 찍혀 있었다. 손가락이 하나 더 많다.`,
        win:{ exp:25, dream:3 } }
    ] },

  { at:'B', t:'지하철 터널 — 막차 뒤의 차',
    x:`지하철 터널이다. 막차가 끊겼다. 선로를 따라 걷는다. 다음 역까지 반 시간.<br><br>
    선로가 떨린다. 뒤에서 불빛이 온다. 보수 차량이다. 막차 뒤에 다니는 차다. 사람이 걷는 줄 모른다.<br>
    터널 벽에 대피 홈이 있다. 쉰 걸음마다. 마지막 홈을 지나쳤다. 다음 홈까지 서른 걸음.<br><br>
    일찍 비키면 홈이 없다. 끝까지 가야 홈이 있다.`,
    o:[
      { l:'① 끝까지 걸어 홈 앞에서 마지막에 든다.', k:'evade', dc:22, wake:1,
        ok:`걸었다. 뛰지 않았다. 뛰면 침목에 걸린다. 불빛이 등을 비춘다. 이쪽 그림자가 앞으로 길게 늘었다.<br><br>스무 걸음. 경적이 울렸다. 이쪽을 봤다. 서지는 못한다. 스물여덟. 홈이 보인다. 서른. 홈에 몸을 밀어 넣었다. 차가 홈 앞을 지나갔다. 바람이 외투를 당겼다.<br>차가 다 지나갔다. 홈에서 나왔다. 무릎이 떨린다. 손은 안 떨린다.<br><br>홈까지 남은 걸음을 세는 동안 오는 것의 거리도 같이 셌다. 둘을 한꺼번에 셌다. 마지막 반 걸음이 서른 걸음 앞에서부터 보였다.`,
        ng:`스물다섯에서 침목에 발이 걸렸다.<br><br>넘어졌다. 불빛이 등 위로 왔다. 기어서 홈으로 들어갔다. 다 못 들어갔다. 차 옆구리가 발뒤꿈치를 스쳤다.<br>신발이 찢겨 나갔다. 발뒤꿈치가 갈렸다. 일어서는 데 오래 걸렸다.`,
        win:{ exp:24, dream:3 }, lose:{ hp:-32, mind:-12 } },
      { l:'② 천으로 벽 신호등을 덮어 차를 세운다.', k:'luck', dc:21,
        ok:`터널 벽 신호등이 초록이다. 회색 천을 신호등에 덮었다. 불빛이 천에 막혔다.<br><br>보수 차량이 신호 앞에서 속도를 줄였다. 섰다. 운전실에서 누가 내렸다. 천을 걷었다. 그 사이 다음 홈까지 걸었다.<br>차가 다시 출발했다. 홈 앞을 천천히 지나갔다. 운전실 창에 천이 걸려 있었다.<br><br>천은 거기 두고 왔다. 다음 역 승강장에 섰을 때 운전실에서 누가 천을 흔들며 지나갔다.`,
        ng:`천이 신호등을 다 못 덮었다. 초록이 새어 나왔다.<br><br>차는 안 섰다. 천이 차 바람에 날려 이쪽 얼굴을 덮었다. 앞이 안 보인다. 벽을 더듬어 홈을 찾았다.<br>홈에 들어가며 어깨를 벽에 박았다. 차가 지나갔다. 천은 어디로 갔는지 모른다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-24, spirit:-14 } },
      { l:'③ 선로 옆 배수로에 엎드린다.', k:'hide', dc:21,
        ok:`선로 옆에 배수로가 있다. 물이 흐른다. 깊이 한 뼘 반. 엎드렸다. 얼굴을 반쯤 물에 담갔다.<br><br>차가 지나갔다. 차 밑이 등 위 두 뼘이다. 쇠 냄새와 열이 등을 눌렀다. 숨을 참았다.<br>다 지나갔다. 일어났다. 온몸이 젖었다. 배수로 물이 맑다. 터널 위 어디서 새어 든 빗물이다. 통에 받았다.<br><br>배수로 물속에 신발 한 짝이 박혀 있다. 이쪽처럼 엎드렸다가 일어나지 못한 사람의 것이다.`,
        ng:`배수로가 생각보다 얕았다.<br><br>차 밑 무언가가 등을 긁고 지나갔다. 외투가 걸렸다. 몇 걸음 끌렸다. 외투가 찢어지며 풀려났다.<br>등이 길게 찢겼다. 물에 피가 풀린다. 일어날 때까지 한참 엎드려 있었다.`,
        win:{ exp:18, item:'맑은 물' }, lose:{ hp:-30, mind:-12 } }
    ] },

  { at:'B1', t:'3번 창고 — 빈 운전석의 지게차',
    x:`3번 창고 안에서 지게차 시동이 걸렸다. 운전석에 아무도 없다. 포크가 가슴 높이로 올라갔다.<br><br>
    지게차가 온다. 느리다. 그런데 안 멈춘다. 이쪽이 움직이는 쪽으로 머리를 튼다.<br>
    창고 안쪽에 소금 자루가 벽처럼 쌓였다. 반대편이 쪽문이다.<br><br>
    느린 것을 지나가게 하는 게 더 어렵다. 마지막까지 오래 기다려야 한다.`,
    o:[
      { l:'① 천으로 불러 소금 자루 더미에 박게 한다.', k:'evade', dc:21,
        ok:`소금 자루 더미 앞에 섰다. 천을 펼쳤다. 지게차가 천을 향해 왔다. 느리게. 오래 걸렸다.<br><br>포크 끝이 천에 닿기 직전 천을 뺐다. 반 걸음 비켰다. 포크가 자루에 박혔다. 지게차가 자루를 밀며 계속 간다. 더미가 무너져 지게차를 덮었다. 엔진이 멎었다.<br>쪽문으로 갔다. 터진 자루에서 소금 덩이 하나가 발밑으로 굴러왔다. 챙겼다.<br><br>무너진 자루 밑에서 시동이 다시 걸리는 소리가 났다. 아무도 열쇠를 안 돌렸는데.`,
        ng:`오래 기다리는 사이 지게차가 박자를 바꿨다. 마지막 세 걸음을 빨리 왔다.<br><br>천을 빼는 게 늦었다. 포크가 옆구리를 치고 지나갔다. 자루 더미에 같이 처박혔다.<br>자루 밑에서 기어 나왔다. 옆구리가 시퍼렇다. 숨 쉴 때마다 결린다.`,
        win:{ exp:20, item:'소금 덩이' }, lose:{ hp:-30, mind:-10 } },
      { l:'② 무력을 실어 포크를 딛고 운전석에 올라탄다.', k:'steady', dc:21, cost:{ might:25 },
        ok:`포크가 오는 순간 포크 위를 짚고 뛰어올랐다. 마스트를 잡았다. 운전석으로 넘어갔다.<br><br>운전석이 비었다. 레버가 저절로 움직인다. 레버를 두 손으로 붙잡고 반대로 당겼다. 레버가 버틴다. 이쪽이 더 버텼다.<br>지게차가 섰다. 열쇠를 뽑았다. 엔진이 멎었다.<br><br>운전석 바닥에 고무장갑 한 켤레가 있었다. 안이 젖었다. 방금까지 누가 끼고 있던 것이다.`,
        ng:`포크를 짚었는데 포크가 올라갔다.<br><br>몸이 들렸다. 천장 들보에 머리를 박을 뻔했다. 뛰어내렸다. 떨어지며 발목을 접질렸다.<br>지게차가 이쪽으로 머리를 틀었다. 절뚝이며 쪽문까지 갔다. 문을 닫는 순간 포크가 문을 찍었다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-26, spirit:-12 } }
    ] },

  { at:'B1', t:'냉동 창고 — 줄지어 오는 갈고리',
    x:`냉동 창고 레일이 멈췄다. 대신 갈고리들이 흔들린다. 누가 맨 끝 갈고리를 밀었다. 하나가 다음을 치고, 다음이 그다음을 친다.<br><br>
    갈고리가 줄줄이 흔들리며 이쪽으로 온다. 쇠끼리 부딪는 소리가 박자다. 하나씩이 아니다. 파도처럼 온다.<br>
    갈고리 사이를 지나야 문이다.<br><br>
    줄지어 오는 것도 하나하나는 다 똑바로 온다.`,
    o:[
      { l:'① 정면을 지키며 갈고리 하나하나를 보낸다.', k:'evade', dc:21, wake:1,
        ok:`첫 갈고리가 왔다. 반 걸음 비켰다. 둘째, 반대로 반 걸음. 셋째는 머리를 숙였다. 박자가 귀에 들어왔다. 쇠 소리 하나에 한 걸음.<br><br>갈고리 열둘을 지났다. 하나도 안 닿았다. 문 앞에서 돌아섰다. 갈고리가 아직 흔들린다. 이쪽이 지나간 길만 비었다.<br>문을 열고 나왔다.<br><br>하나를 보내고 다음을 보내는 사이에 쉬는 박자가 없었다. 그런데 숨이 안 찼다. 보내는 일이 숨 쉬는 일과 같은 박자가 됐다.`,
        ng:`일곱째에서 박자가 겹쳤다. 갈고리 둘이 동시에 왔다.<br><br>하나는 비켰다. 하나가 어깨를 쳤다. 갈고리 끝이 외투를 꿰었다. 몸이 갈고리와 같이 흔들렸다.<br>외투를 벗어 던지고 떨어졌다. 얼음 바닥에 등부터. 어깨 피가 얼어붙었다.`,
        win:{ exp:22, dream:2 }, lose:{ hp:-28, mind:-12 } },
      { l:'② 천으로 갈고리 둘을 묶어 흔들림을 엉키게 한다.', k:'fix', dc:20,
        ok:`가까운 갈고리가 지나간 순간 천을 던져 다음 갈고리와 감아 묶었다. 둘이 묶이자 박자가 엉켰다.<br><br>엉킨 갈고리들이 서로를 붙잡았다. 흔들림이 줄줄이 죽었다. 열둘째까지 다 멈췄다.<br>멈춘 갈고리 사이를 걸어서 지났다. 천은 거기 남겼다.<br><br>문 앞에서 돌아봤다. 맨 끝 갈고리가 다시 밀렸다. 누가 밀었다. 묶인 데서 멈췄다. 천이 이쪽 대신 받고 있다.`,
        ng:`천이 갈고리에 감겼다. 감긴 갈고리가 천째 이쪽을 끌었다.<br><br>천을 놓지 못했다. 같이 흔들렸다. 다음 갈고리가 등을 쳤다. 놓았다. 얼음 바닥을 굴렀다.<br>천은 갈고리 끝에 매달려 아직 흔들린다. 등이 결린다.`,
        win:{ exp:16, dream:2 }, lose:{ hp:-24, spirit:-14 } }
    ] },

  { at:'B1', t:'경매장 — 장대 든 남자',
    x:`경매장 얼음 더미 사이다. 남자 하나가 생선 장대를 들었다. 끝에 쇠갈고리가 달렸다. 길다. 세 걸음 밖에서 닿는다.<br><br>
    남자는 장대를 낮게 쥐었다. 찌르는 박자를 잰다. 소가 뿔을 낮추는 것처럼.<br>
    장대 끝은 천보다 멀리서 온다. 천 앞에서 안 멈춘다. 천 뒤까지 온다.<br><br>
    경매장 출구는 남자 등 뒤다.`,
    o:[
      { l:'① 장대 끝을 천으로 흘리고 남자 옆으로 지난다.', k:'evade', dc:22,
        doom:{ title:'장대 끝', what:'장대 갈고리에 걸려 끌려갑니다', dc:17, sec:50,
          text:`장대가 왔다. 천으로 흘렸다. 장대 끝이 천을 지나갔다. 남자 품으로 파고들었다.<br><br>남자가 장대를 당겼다. 갈고리가 뒤에서 돌아왔다. 이쪽 외투 등판을 걸었다. 남자가 장대를 끌었다. 이쪽이 얼음 바닥을 미끄러져 끌려간다. 수조 쪽으로.<br>수조 가장자리가 다가온다. 흐린 물. 무언가 돈다.<br><br>남자가 장대를 높이 든다. 이쪽을 매단 채.`,
          dieText:`천은 앞에서 오는 것을 흘린다. 돌아오는 것은 천이 모른다.<br><br>수조 물이 한 번 크게 출렁였다. 그리고 잔잔해졌다.<br>경매판에서 이름 하나가 지워졌다.` },
        ok:`장대가 왔다. 천으로 흘렸다. 장대 끝이 천을 지나갔다. 파고들지 않았다. 갈고리가 돌아올 자리를 먼저 봤다.<br><br>남자가 당겼다. 갈고리가 돌아왔다. 천을 그 갈고리에 감았다. 남자가 천을 낚았다. 천이 장대를 타고 남자 얼굴까지 날아갔다. 남자가 얼굴을 감싸는 사이 옆으로 지나 출구로 나왔다.<br><br>천은 장대 끝에 남았다. 남자가 천을 벗겨 수조에 던졌다. 수조 속 무언가가 천을 물고 내려갔다.`,
        win:{ exp:25, dream:3 } },
      { l:'② 얼음 더미 뒤로 돌아 남자 등 뒤를 지난다.', k:'hide', dc:21,
        ok:`얼음 더미 사이로 몸을 낮췄다. 장대 끝이 얼음을 쿡쿡 찌른다. 이쪽 소리 쪽으로.<br><br>얼음 조각 하나를 반대편으로 던졌다. 장대가 그쪽을 찔렀다. 그 사이 둘째 더미, 셋째 더미. 남자 등 뒤로 돌았다. 출구에 닿았다.<br>얼음 더미 밑에 민물고기 한 상자가 깔려 있었다. 경매에 안 오른 것이다. 하나를 챙겼다.<br><br>나오며 봤다. 장대가 이쪽이 숨었던 더미를 오래 찔렀다. 떠난 줄 모른다.`,
        ng:`얼음 더미 하나가 이쪽 무게에 무너졌다.<br><br>장대가 바로 왔다. 갈고리가 허벅지를 스쳤다. 바지가 찢겼다. 살도. 얼음 위에 피가 번진다.<br>굴러서 출구까지 갔다. 다리를 끌었다. 장대 끝이 문틀을 찍고 멈췄다.`,
        win:{ exp:18, item:'민물고기' }, lose:{ hp:-30, mind:-12 } }
    ] },

  { at:'B1', t:'방파제 — 처음 뛰는 청소부',
    x:`방파제 끝이다. 05:05. 청소부가 처음으로 뛴다. 대걸레를 들었다. 자루 끝 쇠가 번쩍인다.<br><br>
    청소부는 일을 끝내야 한다. 무리가 마지막 일이다. 방파제는 좁다. 한쪽은 바다, 한쪽은 해무호 선체.<br>
    청소부가 고개를 숙였다. 뛰기 직전 머리를 숙이는 건 소나 사람이나 같다.<br><br>
    천을 펼쳤다. 회색이다. 비를 맞아 무겁다.`,
    o:[
      { l:'① 끝까지 기다렸다 반 걸음 비켜 바다 쪽으로 보낸다.', k:'evade', dc:22, wake:1,
        ok:`기다렸다. 발소리가 빨라진다. 숨이 닿을 만큼 왔다. 대걸레 끝이 천에 닿기 직전 발소리가 한 박자 끊겼다. 머리를 숙인 것이다.<br><br>그때 반 걸음 비켰다. 천을 바다 쪽으로 뺐다. 청소부가 천을 따라 몸을 틀었다. 방파제 끝을 넘었다. 대걸레와 같이. 물소리가 한 번 났다.<br>방파제 끝 계단으로 무리를 보냈다. 이쪽이 마지막에 올랐다.<br><br>천이 무거웠는데 손목은 안 무거웠다. 젖은 천 무게까지 계산에 들어갔다. 끝까지 기다리는 동안 마음이 한 번도 먼저 비키지 않았다.`,
        ng:`박자 하나를 일찍 들었다.<br><br>비켰는데 청소부가 따라 꺾었다. 대걸레 쇠끝이 옆구리를 찔렀다. 둘이 같이 방파제에 넘어졌다.<br>청소부가 먼저 일어났다. 일행이 청소부를 밀쳐 냈다. 그 사이 계단으로 기었다. 옆구리 피가 빗물에 섞여 흘렀다.`,
        win:{ exp:24, dream:3 }, lose:{ hp:-32, mind:-12 } },
      { l:'② 무력을 실어 대걸레 자루를 붙잡아 꺾는다.', k:'steady', dc:21, cost:{ might:26 },
        ok:`대걸레 자루가 왔다. 비키지 않았다. 두 손으로 자루를 잡았다. 청소부 힘을 그대로 받아 옆으로 꺾었다.<br><br>자루가 부러졌다. 청소부가 부러진 자루를 쥔 채 이쪽 옆을 지나 선체에 부딪혔다. 미끄러져 앉았다. 고개를 안 들었다.<br>무리를 계단으로 보냈다. 부러진 자루 끝은 바다에 던졌다.<br><br>청소부가 앉은 채 양동이를 찾았다. 양동이는 멀리 굴러갔다. 손이 허공을 더듬는다. 일을 못 끝낸 손이다.`,
        ng:`자루를 잡았는데 청소부가 놓았다.<br><br>자루째 뒤로 넘어졌다. 청소부가 빈손으로 이쪽 목을 잡았다. 장갑이 차갑다. 조인다.<br>일행이 청소부 어깨를 끌어당겼다. 숨이 돌아왔다. 목에 장갑 자국이 남았다. 표백제 냄새가 오래 갔다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-28, spirit:-14 } },
      { l:'③ 굴러온 양동이를 천으로 덮어 차 보낸다.', k:'luck', dc:21,
        ok:`청소부 양동이가 발밑에 굴러와 있었다. 천으로 덮었다. 발로 찼다. 양동이가 청소부 쪽으로 굴러갔다.<br><br>청소부가 양동이를 봤다. 멈췄다. 자기 양동이다. 천에 덮였다. 천을 걷으려 허리를 숙였다. 그 숙인 사이 무리가 다 계단으로 지났다.<br>청소부가 천을 걷었다. 양동이 안을 봤다. 비었다.<br><br>청소부가 빈 양동이를 오래 들여다봤다. 이쪽은 계단 위에서 그걸 봤다. 천은 거기 두고 왔다.`,
        ng:`양동이가 덜 굴렀다. 청소부가 양동이를 넘어왔다.<br><br>천이 청소부 발에 감겼다. 청소부가 넘어지며 이쪽 다리를 잡았다. 같이 넘어져 바다 쪽으로 미끄러진다.<br>일행이 이쪽 외투를 잡아 당겼다. 청소부 손이 발목에서 미끄러져 떨어졌다. 발목이 퉁퉁 부었다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-26, mind:-14 } }
    ] },

  { at:'B2', t:'복도 — 밀려오는 휠체어',
    x:`복도 끝에서 휠체어가 온다. 빠르다. 미는 사람은 안 보인다. 환자 하나가 앉았다. 고개가 앞으로 떨어졌다.<br><br>
    바퀴가 왁스 위에서 미끄러진다. 방향을 못 잡는다. 아니다. 이쪽으로만 잡는다.<br>
    복도 옆 병실 문이 다 잠겼다. 비킬 데는 문틀 사이 한 뼘.<br><br>
    앉은 환자가 고개를 든다. 눈이 이쪽을 본다.`,
    o:[
      { l:'① 천으로 휠체어를 문틀 쪽으로 틀어 보낸다.', k:'evade', dc:21,
        ok:`천을 복도 한쪽으로 펼쳤다. 앉은 환자 눈이 천을 따라갔다. 휠체어가 따라갔다. 미는 것도 그 눈을 따른다.<br><br>마지막에 천을 반대로 뺐다. 휠체어가 문틀에 박혔다. 바퀴가 헛돈다. 환자가 앞으로 숙인 채 그대로 있다.<br>그 옆을 지났다. 손목 띠를 봤다. 이름 칸이 비었다.<br><br>복도 끝에서 돌아봤다. 휠체어가 비었다. 환자가 없다. 바퀴만 아직 돈다.`,
        ng:`환자 눈이 천을 안 봤다. 이쪽만 봤다.<br><br>휠체어가 이쪽으로 왔다. 문틀로 비켰다. 발판이 정강이를 찍었다. 환자 손이 소매를 잡았다.<br>소매를 찢고 빠졌다. 정강이가 부었다. 환자 손에 남은 소매 조각이 복도 끝까지 이쪽을 따라왔다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-26, spirit:-14 } },
      { l:'② 무력을 실어 휠체어를 받아 세운다.', k:'steady', dc:21, cost:{ might:24 },
        ok:`비키지 않았다. 몸을 낮추고 휠체어 손잡이를 두 손으로 받았다. 미는 힘이 세다. 사람 하나 미는 힘이 아니다.<br><br>발로 바닥을 버텼다. 세 걸음 밀렸다. 넷째에 섰다. 미는 것이 손을 뗐다. 손이 안 보이는데도 그게 느껴졌다.<br>앉은 환자가 이쪽을 올려다봤다. 입을 움직였다. 고마워. 그리고 눈을 감았다.<br><br>휠체어 주머니에 약초 뭉치가 있었다. 꼬리표에 처방이라고 적혔다. 환자는 이제 그게 필요 없을 것 같다.`,
        ng:`받았는데 바퀴가 미끄러져 휠체어가 옆으로 돌았다.<br><br>손잡이가 배를 쳤다. 밀려 넘어졌다. 휠체어가 이쪽 다리를 넘어갔다.<br>일어나 보니 휠체어가 복도 끝으로 다시 굴러간다. 돌아올 것이다. 다리를 끌고 다른 복도로 피했다.`,
        win:{ exp:18, item:'약초 뭉치' }, lose:{ hp:-28, mind:-12 } }
    ] },

  { at:'B2', t:'계단 문 앞 — 문만 한 조무사',
    x:`복도 끝 계단 문 앞에 조무사 하나가 섰다. 크다. 문만 하다. 하얀 옷. 얼굴은 없다.<br><br>
    조무사는 줄을 벗어난 환자에게 달려든다. 아까 한 환자가 붙잡혀 들려 갔다. 발이 바닥에 안 닿았다.<br>
    계단 문은 잠겼다. 열쇠는 없다. 문은 안쪽으로 열린다. 세게 밀면 부서질 문이다.<br><br>
    세게 미는 건 이쪽 일이 아니다. 세게 미는 것을 데려오는 게 이쪽 일이다.`,
    o:[
      { l:'① 천으로 불러 잠긴 계단 문을 들이받게 한다.', k:'evade', dc:22, wake:1,
        ok:`계단 문 앞에 등을 대고 섰다. 천을 펼쳤다. 조무사가 천을 봤다. 고개가 없는데 고개를 숙이는 게 보였다. 온다.<br><br>문 앞 반 걸음에서 옆으로 빠졌다. 조무사가 천을 따라 문을 들이받았다. 문이 안쪽으로 터졌다. 조무사가 문짝째 계단 아래로 굴러떨어졌다.<br>무리를 데리고 계단으로 내려갔다. 층계참에 조무사가 누워 있다. 안 일어난다. 그 옆을 지났다.<br><br>천을 펼칠 때 상대가 어디에 박힐지까지 같이 봤다. 지나가게 하는 데서 끝나지 않고, 지나간 다음을 정했다.`,
        ng:`조무사가 문 앞에서 섰다. 들이받지 않았다. 손을 뻗었다.<br><br>천이 아니라 이쪽 팔을 잡았다. 들어 올렸다. 발이 떴다. 무리가 조무사 다리를 붙잡았다. 조무사가 이쪽을 놓쳤다.<br>바닥에 떨어졌다. 어깨가 빠졌다. 무리가 다시 끼워 줬다. 소리를 삼키느라 입술이 터졌다.`,
        win:{ exp:24, dream:3 }, lose:{ hp:-30, mind:-14 } },
      { l:'② 투약 줄에 섞여 조무사 앞을 지난다.', k:'hide', dc:21,
        ok:`줄 선 환자들 틈에 섞였다. 고개를 숙였다. 줄은 계단 문 앞을 지나 투약실로 간다.<br><br>조무사는 줄에서 벗어난 것만 본다. 줄 안은 안 본다. 줄과 같이 계단 문 앞까지 갔다. 거기서 줄이 꺾였다. 꺾이는 반 박자에 무리가 문 옆 청소함 뒤로 빠졌다.<br>조무사가 줄을 따라 투약실로 갔다. 문 앞이 비었다. 경첩 핀을 뽑았다.<br><br>청소함 안에 꿀 한 줌이 든 병이 있었다. 환자들이 몰래 모은 것이다. 병에 이름들이 적혔다. 하나만 빼고 다 줄이 그어졌다.`,
        ng:`줄이 꺾일 때 무리 하나가 반 박자 늦었다.<br><br>조무사가 그쪽으로 달려왔다. 이쪽이 그 앞에 섰다. 천은 품 안이다. 꺼내는 사이 받혔다.<br>벽까지 날아갔다. 무리가 이쪽을 끌어 청소함 뒤로 넣었다. 조무사는 줄로 돌아갔다. 갈비 쪽에서 소리가 났다.`,
        win:{ exp:18, item:'꿀 한 줌' }, lose:{ hp:-30, spirit:-12 } }
    ] },

  { at:'B2', t:'처치실 문 — 열리면 나오는 것',
    x:`처치실 문 앞이다. 계단은 처치실 안을 지나야 있다. 다른 길은 다 잠겼다.<br><br>
    문 위 불이 켜졌다. 안에서 무언가 움직인다. 문 유리가 뿌옇다. 바퀴 소리. 무거운 것.<br>
    문이 열리면 그것이 나와 문 앞에 선 것에게 달려든다. 아까 복도 끝에서 봤다.<br><br>
    문 앞에 서야 문을 열 수 있다.`,
    o:[
      { l:'① 문을 열고 정면에 서서 나오는 것을 지나가게 한다.', k:'evade', dc:22,
        doom:{ title:'처치실', what:'처치실로 끌려갑니다', dc:18, sec:50,
          text:`문을 열었다. 정면에 섰다. 천을 펼쳤다.<br><br>나온 건 들것이 아니었다. 하얀 손이 여럿. 천을 지나 이쪽 팔과 어깨와 목을 잡았다. 지나가지 않는다. 잡는다.<br>손들이 이쪽을 안으로 당긴다. 처치실 바닥이 하얗다. 침대 하나가 비었다. 시트가 이쪽 모양으로 접혀 있다.<br><br>문이 천천히 닫힌다. 무리가 문틈에 손을 넣는다.`,
          dieText:`달려드는 것은 지나가게 할 수 있다. 붙잡는 것은 지나가지 않는다.<br><br>처치실 문 위 불이 꺼졌다.<br>점호 손전등이 스물하나를 셌다. 맞았다.` },
        ok:`문을 열었다. 정면에 섰다. 천을 펼치고 그 뒤에서 몸을 낮췄다.<br><br>나온 건 들것이 아니었다. 하얀 손이 여럿. 손들이 천을 잡았다. 이쪽은 천을 놓았다. 손들이 천을 끌고 안으로 들어갔다. 이쪽 대신.<br>그 사이 처치실을 가로질러 반대편 계단 문으로 갔다. 무리가 따라왔다. 손들은 천을 접고 있었다. 사람 모양으로.<br><br>계단 문을 닫으며 봤다. 빈 침대 위에 천이 사람 모양으로 눕혀졌다. 시트가 덮였다. 그것으로 수가 맞았다.`,
        win:{ exp:25, dream:3 } },
      { l:'② 문 옆 벽에 붙고 무리가 자루로 문을 열게 한다.', k:'bond', dc:21,
        ok:`문 옆 벽에 붙었다. 정면에는 아무도 안 세웠다. 무리 하나가 긴 대걸레 자루로 문손잡이를 눌러 밀었다.<br><br>문이 열렸다. 정면이 비었다. 안에서 나온 것이 빈 데로 달려 나왔다. 들것이다. 복도 끝 벽에 박혔다. 시트가 흘러내렸다. 아무것도 없다.<br>문이 닫히기 전에 다 같이 들어가 처치실을 지났다. 계단 문으로 나갔다.<br><br>처치실 침대들은 다 비었다. 시트만 반듯하게 개어 있었다. 침대 수는 스물하나였다.`,
        ng:`자루가 문손잡이에서 미끄러졌다.<br><br>무리 하나가 손으로 손잡이를 잡았다. 문이 열렸다. 그 사람이 정면이었다. 들것이 그 사람에게 달려들었다. 이쪽이 몸을 던져 그 사람을 밀어냈다.<br>들것 모서리가 이쪽 허리를 쳤다. 벽에 박혔다. 허리가 이쪽 것 같지 않다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-32, mind:-12 } }
    ] },

  { at:'B2', t:'비상계단 — 기어 내려오는 환자들',
    x:`계단을 내려가는데 위에서 소리가 난다. 손바닥이 계단을 치는 소리. 많다.<br><br>
    환자들이 기어 내려온다. 네 발로. 빠르다. 무리를 향해. 줄을 벗어난 것을 데려오라고 누가 보낸 것이다.<br>
    계단은 좁다. 둘이 겨우 지난다. 환자들은 줄줄이 온다.<br><br>
    낮게 오는 것에는 천도 낮게 들어야 한다.`,
    o:[
      { l:'① 천을 낮게 깔아 환자들을 난간 쪽으로 흘린다.', k:'evade', dc:21,
        ok:`천을 계단에 낮게 깔았다. 첫 환자가 천을 봤다. 천을 따라 몸을 틀었다. 난간 쪽으로. 난간 사이로 빠져 아래층 계단으로 떨어졌다.<br><br>다음 환자도 천을 봤다. 그다음도. 줄줄이 천을 따라 난간 쪽으로 흘렀다. 무리는 벽 쪽에 붙어 내려갔다.<br>아래에서 환자들이 일어나 다시 위로 기어 올라간다. 줄을 벗어난 것을 아직 못 찾았다는 듯이.<br><br>천이 젖었다. 계단에 깔렸던 쪽에 손바닥 자국이 가득하다.`,
        ng:`환자 하나가 천을 안 따라왔다. 천 위를 기어 넘었다.<br><br>이쪽 발목을 잡았다. 뒤의 환자들이 그 위로 넘어왔다. 무리가 이쪽을 끌어당겼다. 발목을 잡은 손이 안 놓는다.<br>신발이 벗겨지며 빠져나왔다. 발목에 손톱자국이 다섯 줄이다. 맨발로 계단을 뛰었다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-24, spirit:-16 } },
      { l:'② 층계참 문 안으로 무리를 넣고 등으로 막는다.', k:'steady', dc:21,
        ok:`층계참 문을 열었다. 무리를 밀어 넣었다. 마지막에 들어가 문을 등으로 막았다.<br><br>문밖에서 손바닥이 문을 친다. 수십 번. 버텼다. 등뼈까지 울린다. 한참 뒤 소리가 멀어졌다. 아래로.<br>문을 열었다. 계단이 비었다. 아래층까지 손바닥 자국이 이어진다.<br><br>자국을 따라 안 내려갔다. 위로 한 층 올라가 반대편 계단으로 갔다.`,
        ng:`문을 막는데 문 아래 틈으로 손가락들이 들어왔다.<br><br>발등을 긁었다. 발을 뗐다. 문이 밀렸다. 다시 막았다. 손가락이 문에 끼인 채 꿈틀거린다.<br>소리가 멀어질 때까지 버텼다. 발등이 다 긁혔다. 무리 하나는 그 손가락들을 오래 봤다. 그 뒤로 말이 없었다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-22, mind:-16 } },
      { l:'③ 맨 앞 환자의 눈을 본다.', k:'gaze', dc:20,
        ok:`맨 앞 환자의 눈을 봤다. 흐리다. 앞을 안 본다. 소리를 따라온다. 무리 발소리를.<br><br>손을 들어 무리를 멈췄다. 숨을 죽이게 했다. 환자들이 멈췄다. 고개를 이리저리 돌린다. 이쪽 바로 앞에서.<br>천을 위층으로 던졌다. 천이 계단에 떨어지는 소리. 환자들이 그쪽으로 기어올랐다. 그 사이 아래로 내려갔다.<br><br>맨 앞 환자 손목 띠에 이름이 있었다. 무리 이름이 아니다. 그런데 사진 칸이 이쪽 얼굴이었다.`,
        ng:`보는 사이 환자가 이쪽 눈을 봤다. 흐린 눈이 맑아졌다.<br><br>환자가 웃었다. 뒤의 환자들이 한꺼번에 덮쳤다. 계단을 같이 굴렀다. 무리가 이쪽을 끌어냈다.<br>몸 여기저기 손자국이 남았다. 흐린 눈이 맑아지던 순간이 오래 떠올랐다.`,
        win:{ exp:16, dream:2 }, lose:{ mind:-16, spirit:-18 } }
    ] },

  { at:'B3', t:'식당칸 — 굴러오는 쇠 카트',
    x:`기차가 급하게 꺾였다. 식당칸 저편에서 배식 카트가 굴러온다. 쇠 수레다. 잔과 접시가 실렸다.<br><br>
    카트가 통로를 꽉 채운다. 양옆은 식탁. 식탁마다 손님이 앉았다. 손님들은 카트를 안 본다. 이쪽을 본다.<br>
    카트 뒤에 종업원이 있다. 밀고 있다. 웃는다.<br><br>
    통로 폭이 카트 폭이다. 지나가게 할 자리가 없다. 자리는 만들어야 한다.`,
    o:[
      { l:'① 의자 틈 반 뼘에 몸을 세우고 카트를 보낸다.', k:'evade', dc:21, wake:1,
        ok:`식탁 사이 의자 등받이 틈을 봤다. 반 뼘이다. 몸을 옆으로 세웠다. 배를 집어넣었다.<br><br>카트가 왔다. 천을 통로 반대편으로 펼쳤다. 종업원이 천 쪽으로 카트를 틀었다. 카트가 반 뼘 비껴 지나갔다. 모서리가 이쪽 단추를 스쳤다. 단추 하나가 떨어졌다.<br>카트가 식당칸 끝 문에 박혔다. 접시가 쏟아졌다.<br><br>자리가 없을 때 자리를 만드는 법을 몸이 알았다. 비키는 일이 바닥이 아니라 몸 안에서 시작됐다.`,
        ng:`반 뼘이 모자랐다.<br><br>카트 모서리가 허리를 쳤다. 식탁에 등부터 넘어졌다. 손님 수프가 쏟아졌다. 뜨겁지 않다. 차갑다. 손님이 이쪽을 내려다봤다. 이쪽 얼굴로.<br>밀치고 일어났다. 허리가 결린다. 종업원이 카트를 다시 끌어당긴다.`,
        win:{ exp:22, dream:2 }, lose:{ hp:-28, spirit:-12 } },
      { l:'② 무력을 실어 카트를 받아 되민다.', k:'steady', dc:21, cost:{ might:25 },
        ok:`몸을 낮추고 카트 손잡이를 두 손으로 받았다. 무겁다. 밀렸다. 발뒤꿈치로 바닥을 긁으며 버텼다.<br><br>다섯 걸음 밀리고 섰다. 카트 위 잔들이 앞으로 쏟아졌다. 종업원 얼굴에. 종업원이 카트를 놓았다.<br>카트를 반대로 밀었다. 종업원이 카트와 같이 밀려 뒤 칸 문에 끼었다. 그 사이 앞 칸으로 갔다.<br><br>카트 아래 칸에 버섯 바구니가 있었다. 야생 버섯이다. 숲에서 막 딴 냄새가 난다. 한 줌 챙겼다.`,
        ng:`받는 순간 기차가 한 번 더 꺾였다.<br><br>카트 무게가 두 배가 됐다. 밀렸다. 식당칸 끝 문에 등이 박혔다. 카트가 가슴을 눌렀다.<br>종업원이 웃으며 더 밀었다. 일행이 카트 옆을 쳐서 겨우 틀었다. 가슴뼈가 결린다.`,
        win:{ exp:20, item:'야생 버섯' }, lose:{ hp:-30, mind:-12 } }
    ] },

  { at:'B3', t:'침대칸 통로 — 과도 든 손님',
    x:`침대칸 통로다. 사람 하나 폭. 저편에서 손님 하나가 걸어온다. 일행 얼굴이다. 손에 과도를 쥐었다.<br><br>
    과도 끝이 낮다. 찌르는 손이다. 걸음이 빨라진다. 통로에는 비킬 데가 없다.<br>
    양옆은 커튼 친 침대다. 커튼 안에서 손님들이 잔다.<br><br>
    비킬 데가 없으면 비킬 데를 빌린다.`,
    o:[
      { l:'① 마지막 걸음에 커튼 안으로 몸을 빼고 천을 통로에 남긴다.', k:'evade', dc:22,
        doom:{ title:'과도', what:'칼에 찔렸습니다', dc:18, sec:45,
          text:`마지막 걸음에 커튼을 걷고 침대 안으로 몸을 뺐다. 천은 통로에 남겼다.<br><br>침대 안 손님이 눈을 떴다. 얼굴이 바뀐다. 통로의 것과 같은 얼굴로. 손님 손에도 과도가 있다.<br>통로의 칼이 천을 지나갔다. 침대 안의 칼이 이쪽 옆구리로 들어왔다. 커튼이 다시 닫혔다. 안이 어둡다.<br><br>통로에서 일행 목소리가 이쪽 이름을 부른다. 진짜 일행인지 모른다.`,
          dieText:`비킬 데를 빌렸다. 빌린 데에도 주인이 있었다.<br><br>커튼 안에서 숨소리가 하나 줄었다.<br>다음 역 안내 방송이 나온다. 내리실 문은 오른쪽입니다.` },
        ok:`마지막 걸음에 커튼을 걷다 멈췄다. 커튼 안 손님 손이 이불 밖에 나와 있다. 과도가 쥐였다. 자는 척이다.<br><br>침대로 안 들어갔다. 천을 그 커튼 안에 던져 넣었다. 커튼 안의 칼이 천을 찔렀다. 통로의 칼도 그 소리를 따라 커튼을 찔렀다. 두 칼이 서로를 찔렀다.<br>그 사이 통로를 지났다. 등 뒤에서 커튼이 젖어 갔다.<br><br>천은 거기서 잃었다. 커튼 사이로 삐져나온 천 끝이 젖어 무거웠다.`,
        win:{ exp:25, dream:3 } },
      { l:'② 위 칸 사다리를 밟고 올라 머리 위로 보낸다.', k:'hide', dc:21,
        ok:`위 칸 사다리를 밟고 올라 커튼 안으로 몸을 굴렸다. 위 칸은 비었다.<br><br>과도 든 것이 아래를 지나갔다. 커튼 아래 틈으로 칼끝이 보였다. 멈췄다. 위를 안 봤다. 걸어갔다.<br>내려와 반대로 갔다. 그것이 왔던 쪽이 앞 칸이다.<br><br>위 칸 베개에 머리카락 몇 올. 일행 것과 같은 색이다. 그 칸에 누운 일행은 없다.`,
        ng:`위 칸에 사람이 있었다.<br><br>자는 손님 위로 굴렀다. 손님이 깼다. 얼굴이 안 바뀐다. 놀라서 소리를 질렀다. 진짜 사람이다.<br>그 소리에 과도 든 것이 돌아섰다. 위 칸 커튼을 찔렀다. 종아리를 그었다. 굴러 내려와 통로를 뛰었다. 피가 카펫에 길게 났다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-30, mind:-12 } }
    ] },

  { at:'B3', t:'연결 통로 — 들이치는 쇠문',
    x:`연결 통로다. 문이 둘. 기차가 터널에 들어서면 바람이 통로를 치고 문이 들이친다. 쾅. 쾅.<br><br>
    쇠문이다. 무겁다. 들이칠 때 그 사이에 있으면 손이든 머리든 성하지 않다.<br>
    이 구간은 터널이 짧고 많다. 박자가 일정하지 않다.<br><br>
    들이치는 문도 소처럼 똑바로 온다. 둘이 하나처럼 붙어서 온다.`,
    o:[
      { l:'① 문이 들이친 직후 반 박자에 지나간다.', k:'evade', dc:21,
        ok:`터널 소리를 들었다. 들어갈 때 귀가 먹먹해진다. 그 직후 바람이 온다. 문이 들이친다. 쾅. 다시 열린다.<br><br>열리는 순간 지나갔다. 둘째 문이 들이치기 직전에 몸을 뺐다. 등 뒤에서 문이 닫혔다. 외투 자락이 끼었다. 당겨 뺐다.<br>앞 칸에 섰다. 일행도 그 박자로 하나씩 지났다.<br><br>마지막 일행이 지날 때 문에 끼인 것이 있었다. 장갑 하나. 아무도 장갑을 안 꼈다.`,
        ng:`터널이 하나 더 붙어 왔다. 박자가 당겨졌다.<br><br>둘째 문이 일찍 들이쳤다. 어깨를 치고 닫혔다. 몸이 통로 벽에 내동댕이쳐졌다.<br>다음 박자에 기어서 지났다. 어깨에 문 모서리 자국이 깊다. 팔이 안 올라간다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-30, mind:-10 } },
      { l:'② 천으로 두 문 손잡이를 묶어 열어 둔다.', k:'fix', dc:20,
        ok:`문이 열린 박자에 천을 두 문 손잡이에 걸어 묶었다. 열린 채로. 바람이 와도 문이 안 닫힌다. 천이 팽팽해졌다 늘어진다.<br><br>일행이 다 지났다. 천을 풀려다 그만뒀다. 풀면 문이 이쪽 손을 친다.<br>천은 두고 앞 칸으로 갔다.<br><br>뒤에서 문 닫히는 소리가 났다. 천이 풀린 소리다. 누가 풀었다. 이쪽 뒤에 오는 누가.`,
        ng:`묶는 사이 바람이 왔다.<br><br>문이 천째 들이쳤다. 손이 천과 손잡이 사이에 감겼다. 문이 손을 끌고 닫힌다. 빼냈다. 손등 껍질이 벗겨졌다.<br>천은 문에 끼어 찢어졌다. 손이 화끈거린다.`,
        win:{ exp:16, dream:2 }, lose:{ hp:-24, spirit:-14 } }
    ] },

  { at:'B3', t:'맨 앞 칸 — 열린 문 앞',
    x:`맨 앞 칸이다. 내리는 문이 열렸다. 빗바람이 들이친다. 04:43.<br><br>
    그것이 칸 뒤쪽에 섰다. 얼굴을 바꾸는 손님. 이제 얼굴을 안 바꾼다. 이쪽을 본다. 고개를 숙인다.<br>
    문 앞에 서면 그것이 달려든다. 이쪽이 내리기 전에. 내리는 순간 등을 보이게 된다.<br><br>
    투우사는 등을 보이지 않는다. 문 앞에서 정면으로 선다. 문은 이쪽 등 뒤에 있다.`,
    o:[
      { l:'① 열린 문 앞에서 천을 흔들어 그것을 문밖으로 보낸다.', k:'evade', dc:22, wake:1,
        ok:`문을 등지고 섰다. 천을 펼쳤다. 그것이 왔다. 빠르다. 통로를 다 채우며 온다.<br><br>마지막 반 걸음. 발소리가 끊겼다. 머리를 숙였다. 천을 문밖으로 뺐다. 이쪽은 문틀 옆으로 반 걸음. 그것이 천을 따라 열린 문으로 나갔다. 빗속으로. 선로 옆 어둠으로.<br>문 앞이 비었다. 휘는 데에서 무리를 하나씩 내보냈다. 마지막에 이쪽이 뛰었다.<br><br>풀숲에서 일어나 손을 봤다. 천이 아직 손에 있다. 마지막 순간에도 안 놓았다. 보내고도 남는 손이 됐다.`,
        ng:`마지막 반 걸음에서 그것이 머리를 안 숙였다.<br><br>천을 뺐다. 그것이 천을 안 따라갔다. 이쪽을 들이받았다. 둘이 같이 문밖으로 떨어졌다. 자갈 둑을 같이 굴렀다.<br>먼저 일어났다. 그것이 누운 자리에 아무것도 없었다. 무리가 뒤따라 뛰어내렸다. 갈비 두 대가 결린다.`,
        win:{ exp:25, dream:3 }, lose:{ hp:-34, mind:-12 } },
      { l:'② 무력을 실어 받아 문틀에 걸어 누른다.', k:'steady', dc:22, cost:{ might:28 },
        ok:`그것이 왔다. 몸을 낮추고 받았다. 그것 어깨가 이쪽 어깨에 박혔다. 힘을 그대로 받아 옆으로 틀었다. 그것이 문틀에 걸렸다. 반은 안, 반은 밖.<br><br>빗바람이 그것을 밖으로 당긴다. 문틀에 그것을 누른 채 버텼다. 무리가 이쪽 옆으로 하나씩 뛰어내렸다.<br>다 갔다. 손을 놓았다. 그것이 빗속으로 떨어져 나갔다. 이쪽도 뛰었다.<br><br>팔이 한참 떨렸다. 그것을 누른 손바닥이 차갑다. 손바닥에 남은 감촉은 사람 어깨가 아니었다.`,
        ng:`받았는데 그것이 이쪽보다 무거웠다.<br><br>밀려서 문 반대편 벽에 박혔다. 그것이 이쪽을 벽에 누른다. 문이 멀어졌다.<br>무리가 그것을 뒤에서 끌어당겼다. 그 사이 빠져나와 문으로 굴렀다. 휘는 데를 지나 곧은 데서 뛰었다. 등과 어깨가 다 결린다.`,
        win:{ exp:22, dream:2 }, lose:{ hp:-32, spirit:-14 } },
      { l:'③ 천을 던져 얼굴을 덮고 무리를 먼저 내보낸다.', k:'bond', dc:21,
        ok:`천을 그것 얼굴 쪽으로 던졌다. 펼쳐져 덮였다. 그것이 천을 걷으려 멈췄다. 얼굴을 바꾸는 손님은 얼굴이 가려지는 걸 싫어한다.<br><br>무리를 문으로 밀었다. 하나씩. 휘는 데에서. 그것이 천을 걷었다. 천 밑 얼굴이 아무것도 아니었다. 다시 얼굴을 고르는 사이 이쪽이 뛰었다.<br>풀숲에서 무리를 셌다. 맞다.<br><br>기차가 멀어진다. 맨 앞 칸 열린 문에서 회색 천이 깃발처럼 나부낀다. 그것이 들고 흔든다.`,
        ng:`천이 그것 어깨에 걸리고 얼굴은 못 덮었다.<br><br>그것이 천을 끌어 내렸다. 그대로 왔다. 무리 하나를 노렸다. 이쪽이 그 앞을 막았다. 받혔다.<br>둘이 같이 문밖으로 떨어졌다. 곧은 선로였다. 굴렀다. 일행이 이쪽 위로 떨어졌다. 어깨가 빠졌다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-30, mind:-14 } }
    ] }
]);
